INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91890, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "无价值", "is_correct": true, "explanation": "“有价值”在“有用处、有意义”这一义项下的反义词是“无价值”，表示没有用处或意义。"}, {"text": "热情", "is_correct": false, "explanation": "与“有价值”无反义关系：“热情”形容人的态度。"}, {"text": "高大", "is_correct": false, "explanation": "与“有价值”无反义关系：“高大”形容身材，与价值无关。"}, {"text": "清楚", "is_correct": false, "explanation": "与“有价值”无反义关系：“清楚”形容清晰程度，与价值的有无不对应。"}], "correct_answer": "无价值", "explanations": {"无价值": "“有价值”在“有用处、有意义”这一义项下的反义词是“无价值”，表示没有用处或意义。", "热情": "与“有价值”无反义关系：“热情”形容人的态度。", "高大": "与“有价值”无反义关系：“高大”形容身材，与价值无关。", "清楚": "与“有价值”无反义关系：“清楚”形容清晰程度，与价值的有无不对应。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea50f9b6-3a44-4278-abbe-9c85b78917e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91890, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "具有价值的；有用处、有意义的。", "primary_collocate": null, "pronunciation": "yǒu jià zhí", "ipa": "jou˨˩˦ tɕja˥˩ ʈʂɨ˧˥", "syllable_count": 3, "sentences": [{"text": "这本书对学生很有价值。", "target_word": "有价值", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次旅行对我来说很有价值。", "target_word": "有价值", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他提出了一个很有价值的建议。", "target_word": "有价值", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说这个问题很有价值，值得讨论。", "target_word": "有价值", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些旧照片对历史研究很有价值。", "target_word": "有价值", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我觉得这份工作非常有价值。", "target_word": "有价值", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个实验得到了有价值的结果。", "target_word": "有价值", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "帮助别人是一件有价值的事。", "target_word": "有价值", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个博物馆里有价值的东西很多。", "target_word": "有价值", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的看法很有价值，我们要认真想想。", "target_word": "有价值", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "有價值", "label": "繁体"}], "register": "中性", "sense_fingerprint": "有用处、有意义的，值得做或值得讨论", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75fd202e-20bb-4aa3-a2f5-79e25091db51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91890, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "有价值", "is_correct": true, "explanation": "这里要用“有价值”，意思是有用处、有意义，正好描述这本书对学生的作用。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容人或建筑的身材，不能用来说书的好处。"}, {"text": "聪明", "is_correct": false, "explanation": "语义：“聪明”指人的智力，书本身没有智力，句子说不通。"}, {"text": "热闹", "is_correct": false, "explanation": "搭配：“热闹”多用于场所或场面，不能说“对学生很热闹”。"}], "explanations": {"有价值": "这里要用“有价值”，意思是有用处、有意义，正好描述这本书对学生的作用。", "高大": "体貌：“高大”形容人或建筑的身材，不能用来说书的好处。", "聪明": "语义：“聪明”指人的智力，书本身没有智力，句子说不通。", "热闹": "搭配：“热闹”多用于场所或场面，不能说“对学生很热闹”。"}, "sentence_index": 0, "correct_answer": "有价值"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这碗汤很有价值，我一口气喝了两碗。", "explanation": "这里应该用〈美味〉。有价值说事物的意义或用处，不描述味道；形容汤好喝要说美味。"}, {"text": "他长得很有价值，一看就很帅气。", "explanation": "这里应该用〈英俊〉。有价值说事物的意义或用处，不用来形容人的长相；形容相貌好看要说英俊。"}, {"text": "这阵风很有价值，吹得人睁不开眼。", "explanation": "这里应该用〈猛烈〉。有价值说事物的意义或用处，不用来形容风力；形容风势很大要说猛烈。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea50f9b6-3a44-4278-abbe-9c85b78917e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91890, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "有价值", "is_correct": true, "explanation": "这里要用“有价值”修饰“结果”，表示结果有意义、有用处。"}, {"text": "雄伟", "is_correct": false, "explanation": "体貌：“雄伟”形容山川或建筑的气势，不能用来形容实验的结果。"}, {"text": "狭窄", "is_correct": false, "explanation": "语义：“狭窄”说空间小，不能用来形容结果。"}, {"text": "嘈杂", "is_correct": false, "explanation": "搭配：“嘈杂”形容声音或环境，不能修饰“结果”。"}], "explanations": {"有价值": "这里要用“有价值”修饰“结果”，表示结果有意义、有用处。", "雄伟": "体貌：“雄伟”形容山川或建筑的气势，不能用来形容实验的结果。", "狭窄": "语义：“狭窄”说空间小，不能用来形容结果。", "嘈杂": "搭配：“嘈杂”形容声音或环境，不能修饰“结果”。"}, "sentence_index": 6, "correct_answer": "有价值"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的脾气很有价值，一生气就摔东西。", "explanation": "这里应该用〈暴躁〉。有价值说事物的意义或用处，不用来形容性情；脾气火爆要说暴躁。"}, {"text": "我的感冒很有价值，烧了三天也没退。", "explanation": "这里应该用〈严重〉。有价值说事物的意义或用处，不用来形容病情；病情厉害要说严重。"}, {"text": "窗外的鸟叫声很有价值，吵得我睡不着。", "explanation": "这里应该用〈嘈杂〉。有价值说事物的意义或用处，不用来形容声音杂乱；鸟叫声杂乱吵人要说嘈杂。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea50f9b6-3a44-4278-abbe-9c85b78917e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91890, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个方法对我们的有价值。", "corrected_sentence": "这个方法对我们很有价值。", "error_description": "错误形式：对我们的有价值；正确形式：对我们很有价值。“的”是结构助词，不能放在“对我们”和“有价值”之间，应用程度副词“很”修饰“有价值”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea50f9b6-3a44-4278-abbe-9c85b78917e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91890, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次培训对新员工不有价值。", "corrected_sentence": "这次培训对新员工很有价值。", "error_description": "错误形式：不有价值；正确形式：很有价值。“有价值”前面要用程度副词“很”，否定副词“不”不能和“有”组成“不有”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea50f9b6-3a44-4278-abbe-9c85b78917e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
