INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91893, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "尚是到现在还是，还没有变。", "primary_collocate": null, "pronunciation": "shàng", "ipa": "ʂɑŋ˥˩", "syllable_count": 1, "sentences": [{"text": "老人尚在，家里很热闹。", "target_word": "尚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的爷爷身体尚好。", "target_word": "尚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上的雪尚在。", "target_word": "尚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条老街尚存几家旧店。", "target_word": "尚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的钱尚有一些。", "target_word": "尚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他尚在国外，下个月才回来。", "target_word": "尚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里尚是老样子。", "target_word": "尚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "离开会时间尚有两个小时。", "target_word": "尚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她年纪尚轻，还需要多学习。", "target_word": "尚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老房子尚在，只是没有人住。", "target_word": "尚", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "副词：到现在仍然是这样，没有变化，常见尚在、尚有、尚存", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3716686e-219a-4097-9cd6-13972df5123d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91893, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "尚", "is_correct": true, "explanation": "尚 shàng 为本词，表示到现在仍然如此"}, {"text": "赏", "is_correct": false, "explanation": "shǎng（第三声）与 shàng（第四声）声调不同，意思是“欣赏”"}, {"text": "扇", "is_correct": false, "explanation": "shàn 与 shàng 韵母不同（an 与 ang），意思是量词“扇”"}, {"text": "丧", "is_correct": false, "explanation": "sàng 与 shàng 声母不同（s 与 sh），意思是“丧失”"}], "explanations": {"尚": "尚 shàng 为本词，表示到现在仍然如此", "赏": "shǎng（第三声）与 shàng（第四声）声调不同，意思是“欣赏”", "扇": "shàn 与 shàng 韵母不同（an 与 ang），意思是量词“扇”", "丧": "sàng 与 shàng 声母不同（s 与 sh），意思是“丧失”"}, "sentence_index": null, "correct_answer": "尚"}, "level_3": {"options": [{"text": "尚", "is_correct": true, "explanation": "尚表示到现在仍然在，“老人尚在”句意通顺"}, {"text": "很", "is_correct": false, "explanation": "语义：“很”表示程度，无法修饰“在”，句意不通"}, {"text": "太", "is_correct": false, "explanation": "搭配：“太”不能修饰“在”"}, {"text": "最", "is_correct": false, "explanation": "搭配：“最”表示程度，不能与“在”搭配"}], "explanations": {"尚": "尚表示到现在仍然在，“老人尚在”句意通顺", "很": "语义：“很”表示程度，无法修饰“在”，句意不通", "太": "搭配：“太”不能修饰“在”", "最": "搭配：“最”表示程度，不能与“在”搭配"}, "sentence_index": 0, "correct_answer": "尚"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这里尚变了样。", "explanation": "这里应该用〈已经〉。尚表示到现在仍然没有变化，与“变了样”矛盾"}, {"text": "这些树尚长高了不少。", "explanation": "这里应该用〈已经〉。尚表示到现在仍然没有变化，不能表示已经发生的变化，与“长高了不少”矛盾"}, {"text": "旧店尚卖光了。", "explanation": "这里应该用〈早就〉。尚表示到现在仍然如此，不能表示很久以前就已发生，与“卖光了”的完成义矛盾"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64c2c205-b12a-4484-951d-8c74f4f8502d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91893, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "尚", "is_correct": true, "explanation": "尚 shàng 为本词，表示到现在仍然如此"}, {"text": "商", "is_correct": false, "explanation": "shāng（第一声）与 shàng（第四声）声调不同，意思是“商店”"}, {"text": "伤", "is_correct": false, "explanation": "shāng（第一声）与 shàng（第四声）声调不同，意思是“受伤”"}, {"text": "善", "is_correct": false, "explanation": "shàn 与 shàng 韵母不同（an 与 ang），意思是“善良”"}], "explanations": {"尚": "尚 shàng 为本词，表示到现在仍然如此", "商": "shāng（第一声）与 shàng（第四声）声调不同，意思是“商店”", "伤": "shāng（第一声）与 shàng（第四声）声调不同，意思是“受伤”", "善": "shàn 与 shàng 韵母不同（an 与 ang），意思是“善良”"}, "sentence_index": null, "correct_answer": "尚"}, "level_3": {"options": [{"text": "尚", "is_correct": true, "explanation": "尚表示到现在仍然如此，“这里尚是老样子”句意通顺"}, {"text": "刚", "is_correct": false, "explanation": "语义：“刚”指时间刚刚，与“老样子”的持续状态不合"}, {"text": "太", "is_correct": false, "explanation": "搭配：“太”不能修饰“是”"}, {"text": "猛", "is_correct": false, "explanation": "语义：“猛”表示突然或猛烈，与“是老样子”的状态不合"}], "explanations": {"尚": "尚表示到现在仍然如此，“这里尚是老样子”句意通顺", "刚": "语义：“刚”指时间刚刚，与“老样子”的持续状态不合", "太": "搭配：“太”不能修饰“是”", "猛": "语义：“猛”表示突然或猛烈，与“是老样子”的状态不合"}, "sentence_index": 6, "correct_answer": "尚"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老房子尚拆完了。", "explanation": "这里应该用〈终于〉。尚表示到现在仍然如此，不能表示拆完的结果"}, {"text": "老街尚修过两次。", "explanation": "这里应该用〈曾经〉。尚表示到现在仍然如此，与“修过两次”的既往经历矛盾"}, {"text": "旧房子尚被推倒了。", "explanation": "这里应该用〈刚刚〉。尚表示到现在仍然如此，不能表示刚刚发生的变化，与“被推倒了”的完成义矛盾"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64c2c205-b12a-4484-951d-8c74f4f8502d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91893, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老屋在尚，里面的家具都还在。", "corrected_sentence": "老屋尚在，里面的家具都还在。", "error_description": "错误：“在尚”。正确：“尚在”。“尚”是副词，要放在动词“在”前面，表示到现在仍然存在", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64c2c205-b12a-4484-951d-8c74f4f8502d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91893, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个小镇有尚一座古桥。", "corrected_sentence": "这个小镇尚有一座古桥。", "error_description": "错误：“有尚”。正确：“尚有”。“尚”是副词，要放在“有”前面，不能放在“有”和数量词之间", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '64c2c205-b12a-4484-951d-8c74f4f8502d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91901, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "人道", "is_correct": true, "explanation": "正确：「人道」与「反人类」构成反义，指尊重人、关怀人的性质"}, {"text": "凶狠", "is_correct": false, "explanation": "凶狠指恶狠狠的样子，与「反人类」不构成反义"}, {"text": "残忍", "is_correct": false, "explanation": "近义：「残忍」与「反人类」意思相近，不是反义词"}, {"text": "冷漠", "is_correct": false, "explanation": "冷漠指对人缺乏热情，与「反人类」不构成词典列出的反义"}], "correct_answer": "人道", "explanations": {"人道": "正确：「人道」与「反人类」构成反义，指尊重人、关怀人的性质", "凶狠": "凶狠指恶狠狠的样子，与「反人类」不构成反义", "残忍": "近义：「残忍」与「反人类」意思相近，不是反义词", "冷漠": "冷漠指对人缺乏热情，与「反人类」不构成词典列出的反义"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34f8daac-37c4-4d08-8b43-b54a2adeda7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91901, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "人道", "is_correct": true, "explanation": "正确：「人道」与「反人类」构成反义，指尊重人、关怀人的性质"}, {"text": "粗鲁", "is_correct": false, "explanation": "粗鲁指言行不文雅，与「反人类」不构成反义"}, {"text": "随和", "is_correct": false, "explanation": "随和指性情温和、容易相处，与「反人类」不构成反义"}, {"text": "活泼", "is_correct": false, "explanation": "活泼指生动、爱动，与「反人类」不构成反义"}], "correct_answer": "人道", "explanations": {"人道": "正确：「人道」与「反人类」构成反义，指尊重人、关怀人的性质", "粗鲁": "粗鲁指言行不文雅，与「反人类」不构成反义", "随和": "随和指性情温和、容易相处，与「反人类」不构成反义", "活泼": "活泼指生动、爱动，与「反人类」不构成反义"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34f8daac-37c4-4d08-8b43-b54a2adeda7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91901, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "反人类是对人们非常坏、非常残忍的。", "primary_collocate": null, "pronunciation": "fǎn rén lèi", "ipa": "fan˨˩˦ ɻən˧˥ lei˥˩", "syllable_count": 3, "sentences": [{"text": "他这样对待小狗，太反人类了。", "target_word": "反人类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个老板让工人天天工作十八小时，真反人类。", "target_word": "反人类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用这种方法惩罚孩子，实在太反人类了。", "target_word": "反人类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把病人关在黑屋子里，这种做法很反人类。", "target_word": "反人类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影里的坏人做事非常反人类。", "target_word": "反人类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我觉得不给工人水喝，这样做太反人类了。", "target_word": "反人类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个故事里的国王又坏又残忍，他的法律很反人类。", "target_word": "反人类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他打骂老人，大家都说他的行为反人类。", "target_word": "反人类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不让饿了的孩子吃饭，这个规定太反人类了。", "target_word": "反人类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到他那样折磨小动物，我觉得特别反人类。", "target_word": "反人类", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "反人类罪", "label": "复合词"}], "register": "口语", "sense_fingerprint": "日常口语中形容做法对人非常坏、非常残忍", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b25d4a5-d08c-4cec-aadd-1aa0baf2491a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91901, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "甜", "is_correct": false, "explanation": "语义：「甜」形容味道，不能用来评价对待小狗的方式"}, {"text": "反人类", "is_correct": true, "explanation": "正确：「反人类」在口语中形容对人非常坏、非常残忍，符合句意"}, {"text": "冷清", "is_correct": false, "explanation": "语义：「冷清」形容场所或氛围，与对待方式不相关"}, {"text": "高大", "is_correct": false, "explanation": "搭配：「高大」形容身材或物体的高度，不能修饰「对待」的方式"}], "explanations": {"甜": "语义：「甜」形容味道，不能用来评价对待小狗的方式", "反人类": "正确：「反人类」在口语中形容对人非常坏、非常残忍，符合句意", "冷清": "语义：「冷清」形容场所或氛围，与对待方式不相关", "高大": "搭配：「高大」形容身材或物体的高度，不能修饰「对待」的方式"}, "sentence_index": 0, "correct_answer": "反人类"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天给孩子讲故事，这种做法很反人类。", "explanation": "这里应该用〈温馨〉。反人类指对人非常坏、非常残忍，给孩子讲故事是温暖的行为，要说温馨"}, {"text": "我们每次都帮老人过马路，真反人类。", "explanation": "这里应该用〈体贴〉。反人类指对人非常坏、非常残忍，帮老人过马路是体贴的行为，要说体贴"}, {"text": "他把自己的零花钱全部捐给了灾区，这种做法很反人类。", "explanation": "这里应该用〈慷慨〉。反人类指对人非常坏、非常残忍，捐钱救灾是善举，要说慷慨"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34f8daac-37c4-4d08-8b43-b54a2adeda7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91901, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "苦", "is_correct": false, "explanation": "语义：「苦」形容味道或处境，不能用来形容法律"}, {"text": "反人类", "is_correct": true, "explanation": "正确：「反人类」在口语中形容对人非常残忍，符合句意"}, {"text": "香", "is_correct": false, "explanation": "语义：「香」形容气味或味道，与「法律」不相容"}, {"text": "亮", "is_correct": false, "explanation": "搭配：「亮」多形容光线或颜色，不能修饰「法律」"}], "explanations": {"苦": "语义：「苦」形容味道或处境，不能用来形容法律", "反人类": "正确：「反人类」在口语中形容对人非常残忍，符合句意", "香": "语义：「香」形容气味或味道，与「法律」不相容", "亮": "搭配：「亮」多形容光线或颜色，不能修饰「法律」"}, "sentence_index": 6, "correct_answer": "反人类"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把路边那棵老树砍得很反人类。", "explanation": "这里应该用〈粗暴〉。反人类描述的是对人非常残忍，砍树属于对树木的粗暴，不能说反人类"}, {"text": "志愿者每周去养老院陪伴老人，这种做法很反人类。", "explanation": "这里应该用〈关怀〉。反人类指对人非常坏、非常残忍，陪伴老人是关怀的行为，意思相反"}, {"text": "老师耐心地教我们做题，真是太反人类了。", "explanation": "这里应该用〈耐心〉。反人类指对人非常坏、非常残忍，耐心教学是对学生有益的行为，要说耐心"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34f8daac-37c4-4d08-8b43-b54a2adeda7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91901, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的做法太反人类的了。", "corrected_sentence": "他的做法太反人类了。", "error_description": "错误：「反人类」作谓语后，「的」和「了」不能同时出现，「太反人类的了」不成立；正确：应说「太反人类了」", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34f8daac-37c4-4d08-8b43-b54a2adeda7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91901, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把小狗折磨很反人类。", "corrected_sentence": "他把小狗折磨得很反人类。", "error_description": "错误：「把」字句中「折磨」后缺少「得」，「折磨很反人类」不成立；正确：应说「折磨得很反人类」，「得」引出程度补语", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34f8daac-37c4-4d08-8b43-b54a2adeda7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
