INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91902, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "严重危害人类的；极端残暴的。", "primary_collocate": null, "pronunciation": "fǎn rén lèi", "ipa": "fan˨˩˦ ɻən˧˥ lei˥˩", "syllable_count": 3, "sentences": [{"text": "战争中的这些罪行是反人类的。", "target_word": "反人类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法院认为他的行为是反人类的罪行。", "target_word": "反人类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都反对这种反人类的暴行。", "target_word": "反人类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在战争中犯下了反人类的罪行。", "target_word": "反人类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用毒气杀害平民是反人类的行为。", "target_word": "反人类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "联合国谴责了这次反人类的屠杀。", "target_word": "反人类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的政府做了很多反人类的事。", "target_word": "反人类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "历史课上，老师讲了反人类的暴行。", "target_word": "反人类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法官说，这些人要为反人类的行为负责。", "target_word": "反人类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "虐待俘虏是极其反人类的做法。", "target_word": "反人类", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "反人类罪", "label": "复合词"}], "register": "书面", "sense_fingerprint": "形容罪行、暴行严重危害人类、极其残暴", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7b25d4a5-d08c-4cec-aadd-1aa0baf2491a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91902, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "好", "is_correct": false, "explanation": "语义：「好」是褒义，与「罪行」的恶性相矛盾，句子意思颠倒"}, {"text": "反人类", "is_correct": true, "explanation": "正确：「反人类」形容严重危害人类的罪行，符合句意"}, {"text": "漂亮", "is_correct": false, "explanation": "搭配：「漂亮」形容外表或事物的美好，不能用来修饰「罪行」"}, {"text": "轻松", "is_correct": false, "explanation": "语义：「轻松」指不费力或心情舒适，不能用于形容罪行"}], "explanations": {"好": "语义：「好」是褒义，与「罪行」的恶性相矛盾，句子意思颠倒", "反人类": "正确：「反人类」形容严重危害人类的罪行，符合句意", "漂亮": "搭配：「漂亮」形容外表或事物的美好，不能用来修饰「罪行」", "轻松": "语义：「轻松」指不费力或心情舒适，不能用于形容罪行"}, "sentence_index": 0, "correct_answer": "反人类"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老奶奶把自己的午饭分给了流浪猫，这种行为很反人类。", "explanation": "这里应该用〈善良〉。反人类指严重危害人类、极端残暴，分食救助流浪猫是善良的行为，要说善良"}, {"text": "消防员冒着大火救出了三个孩子，这是极其反人类的行为。", "explanation": "这里应该用〈英勇〉。反人类指严重危害人类、极端残暴，冒险救人是英勇的行为，要说英勇"}, {"text": "志愿者在灾区连续工作了三天，他们的精神非常反人类。", "explanation": "这里应该用〈坚韧〉。反人类指严重危害人类、极端残暴，连续奋战的精神要说坚韧"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34f8daac-37c4-4d08-8b43-b54a2adeda7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91902, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "甜", "is_correct": false, "explanation": "语义：「甜」形容味道，不能用来形容政府做的事"}, {"text": "反人类", "is_correct": true, "explanation": "正确：「反人类」形容严重危害人类的行为，符合句意"}, {"text": "凉快", "is_correct": false, "explanation": "语义：「凉快」形容温度感受，与「做的事」不相容"}, {"text": "湿润", "is_correct": false, "explanation": "搭配：「湿润」形容物体含水，不能修饰「事」"}], "explanations": {"甜": "语义：「甜」形容味道，不能用来形容政府做的事", "反人类": "正确：「反人类」形容严重危害人类的行为，符合句意", "凉快": "语义：「凉快」形容温度感受，与「做的事」不相容", "湿润": "搭配：「湿润」形容物体含水，不能修饰「事」"}, "sentence_index": 6, "correct_answer": "反人类"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他帮邻居修好了屋顶，这是很反人类的事。", "explanation": "这里应该用〈友善〉。反人类指严重危害人类、极端残暴，帮邻居修屋顶是对人有益的善举，要说友善"}, {"text": "妈妈每天早起做饭，这种付出十分反人类。", "explanation": "这里应该用〈无私〉。反人类指严重危害人类、极端残暴，妈妈的付出是爱与奉献，要说无私"}, {"text": "大家都在努力保护环境，这种行为很反人类。", "explanation": "这里应该用〈有益〉。反人类指严重危害人类，保护环境对人类有益，要说有益"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34f8daac-37c4-4d08-8b43-b54a2adeda7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91902, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们被控犯有反人类。", "corrected_sentence": "他们被控犯有反人类罪。", "error_description": "错误：「反人类」是形容词，不能作「犯有」的宾语，「犯有」需要名词，缺少「罪」；正确：应说「反人类罪」，这是名词复合词", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34f8daac-37c4-4d08-8b43-b54a2adeda7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91902, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次屠杀是反人类。", "corrected_sentence": "这次屠杀是反人类的。", "error_description": "错误：「是」字判断句中形容词「反人类」后缺少「的」；正确：应说「这次屠杀是反人类的」，「的」要放在形容词之后", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '34f8daac-37c4-4d08-8b43-b54a2adeda7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
