INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91906, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "戏剧；演出。", "primary_collocate": null, "pronunciation": "xì", "ipa": "ɕi˥˩", "syllable_count": 1, "sentences": [{"text": "今晚有戏。", "target_word": "戏", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "戏几点开始？", "target_word": "戏", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "戏八点开始，我们早点去。", "target_word": "戏", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他在戏里演一个老人。", "target_word": "戏", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "戏演完了，大家一起拍手。", "target_word": "戏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "晚上的戏很长，要演三个小时。", "target_word": "戏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "村里每年过年都请人来唱戏。", "target_word": "戏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下雨了，今天的戏不演了。", "target_word": "戏", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸带我去剧院看戏，那里的位子很舒服。", "target_word": "戏", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们每天晚上都要演戏，所以白天要好好休息。", "target_word": "戏", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "出", "label": "量词"}, {"form": "场", "label": "量词"}, {"form": "戏迷", "label": "复合"}, {"form": "戏台", "label": "复合"}, {"form": "戲", "label": "繁体"}], "register": "中性", "sense_fingerprint": "戏：戏剧演出这一活动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '27970c99-4f73-4e93-9f4f-b3aa2257ae1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
