UDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91906, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "戏", "is_correct": true, "explanation": "戏（xì）指戏剧、演出，是正确答案。"}, {"text": "希", "is_correct": false, "explanation": "xī（第一声）与 xì（第四声）声调不同，意思是希望。"}, {"text": "息", "is_correct": false, "explanation": "xī（第一声）与 xì（第四声）声调不同，意思是呼吸或消息。"}, {"text": "溪", "is_correct": false, "explanation": "xī（第一声）与 xì（第四声）声调不同，意思是小河。"}, {"text": "席", "is_correct": false, "explanation": "xí（第二声）与 xì（第四声）声调不同，意思是座位。"}, {"text": "许", "is_correct": false, "explanation": "xǔ（第三声）与 xì（第四声）声调不同，意思是允许。"}], "explanations": {"戏": "戏（xì）指戏剧、演出，是正确答案。", "希": "xī（第一声）与 xì（第四声）声调不同，意思是希望。", "息": "xī（第一声）与 xì（第四声）声调不同，意思是呼吸或消息。", "溪": "xī（第一声）与 xì（第四声）声调不同，意思是小河。", "席": "xí（第二声）与 xì（第四声）声调不同，意思是座位。", "许": "xǔ（第三声）与 xì（第四声）声调不同，意思是允许。"}, "sentence_index": null, "correct_answer": "戏"}, "level_3": {"options": [{"text": "戏", "is_correct": true, "explanation": "戏：指舞台上演的戏剧，“唱戏”即演戏，是正确答案。"}, {"text": "票", "is_correct": false, "explanation": "语义：“唱票”指计票，与村里过年请人表演的意思不符。"}, {"text": "名", "is_correct": false, "explanation": "搭配：“唱名”是点名的说法，不能用来指节日里的表演。"}, {"text": "价", "is_correct": false, "explanation": "语义：“唱价”指拍卖报价，与村里过年请人表演的意思不符。"}], "explanations": {"戏": "戏：指舞台上演的戏剧，“唱戏”即演戏，是正确答案。", "票": "语义：“唱票”指计票，与村里过年请人表演的意思不符。", "名": "搭配：“唱名”是点名的说法，不能用来指节日里的表演。", "价": "语义：“唱价”指拍卖报价，与村里过年请人表演的意思不符。"}, "sentence_index": 6, "correct_answer": "戏"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们每天晚上都要演一首戏，所以白天要好好休息。", "explanation": "这里应该用〈出〉或〈场〉。戏不用“首”计量，“首”用于诗词和歌曲。"}, {"text": "他们每天晚上都要演一幅戏，所以白天要好好休息。", "explanation": "这里应该用〈出〉或〈场〉。戏不用“幅”计量，“幅”用于画作、照片等。"}, {"text": "他们每天晚上都要演一座戏，所以白天要好好休息。", "explanation": "这里应该用〈出〉或〈场〉。戏不用「座」计量，「座」用于山、桥、房屋等大型物体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15892393-1ac4-4383-b4c1-61fa6b59c7c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91906, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今晚有一座戏，很多人都会去看。", "corrected_sentence": "今晚有一出戏，很多人都会去看。", "error_description": "量词错误：演出类的“戏”量词应用“出”。“座”用于山、桥、房屋等大型物体，不用于戏。应为“一出戏”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15892393-1ac4-4383-b4c1-61fa6b59c7c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91906, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "村里每年过年都请人来唱一首戏。", "corrected_sentence": "村里每年过年都请人来唱一出戏。", "error_description": "量词错误：「戏」的量词应为「出」，「首」用于诗词和歌曲。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15892393-1ac4-4383-b4c1-61fa6b59c7c6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
