INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91922, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一条河流的干流和支流所流经的整个区域。", "primary_collocate": null, "pronunciation": "liú yù", "ipa": "ljou˧˥ y˥˩", "syllable_count": 2, "sentences": [{"text": "长江流域包括干流和很多支流经过的地方。", "target_word": "流域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "黄河流域一共有九个省区。", "target_word": "流域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个流域里有大小河流上百条。", "target_word": "流域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家正在调查整个流域的水质。", "target_word": "流域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "流域内的城市要一起保护河水。", "target_word": "流域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "珠江流域的水系很复杂，支流很多。", "target_word": "流域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府为这个流域制定了新的规划。", "target_word": "流域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个流域面积很大，有十几万平方公里。", "target_word": "流域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下大雨后，整个流域都要注意洪水。", "target_word": "流域", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "流域管理需要上游和下游的城市一起努力。", "target_word": "流域", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "长江流域", "label": "复合"}], "register": "中性", "sense_fingerprint": "干流和支流流经的整个区域，用于水系、水质、管理等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75fd202e-20bb-4aa3-a2f5-79e25091db51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91922, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "流域", "is_correct": true, "explanation": "正确答案。「流域」指一条河的干流和支流流经的整个区域。"}, {"text": "留意", "is_correct": false, "explanation": "yì（第四声）与 yù（第四声）韵母不同，「留意」意思是注意。"}, {"text": "流于", "is_correct": false, "explanation": "yú（第二声）与 yù（第四声）声调不同，「流于」意思是停留在某种程度，如流于形式。"}, {"text": "留予", "is_correct": false, "explanation": "yǔ（第三声）与 yù（第四声）声调不同，「留予」意思是留给。"}], "explanations": {"流域": "正确答案。「流域」指一条河的干流和支流流经的整个区域。", "留意": "yì（第四声）与 yù（第四声）韵母不同，「留意」意思是注意。", "流于": "yú（第二声）与 yù（第四声）声调不同，「流于」意思是停留在某种程度，如流于形式。", "留予": "yǔ（第三声）与 yù（第四声）声调不同，「留予」意思是留给。"}, "sentence_index": null, "correct_answer": "流域"}, "level_3": {"options": [{"text": "河床", "is_correct": false, "explanation": "语义：「河床」是河底的地方，不能包括干流和支流，句子说不通。"}, {"text": "流域", "is_correct": true, "explanation": "正确答案。「流域」包括干流和支流流经的地方，长江流域正是如此。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：「身材」指人的体形，不能用来指一条江的地区。"}, {"text": "作风", "is_correct": false, "explanation": "搭配：「作风」指做事的态度和方式，不能作为「长江」的范围。"}], "explanations": {"河床": "语义：「河床」是河底的地方，不能包括干流和支流，句子说不通。", "流域": "正确答案。「流域」包括干流和支流流经的地方，长江流域正是如此。", "身材": "体貌：「身材」指人的体形，不能用来指一条江的地区。", "作风": "搭配：「作风」指做事的态度和方式，不能作为「长江」的范围。"}, "sentence_index": 0, "correct_answer": "流域"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个流域很害羞，一见人就脸红。", "explanation": "这里应该用〈她〉。流域是地区，不会害羞、脸红；说人害羞要用「她」等指人的词。"}, {"text": "这个流域很深。", "explanation": "这里应该用〈水库〉。「深」说水的深浅，流域是陆地上的大片地区，不能说深。"}, {"text": "这片流域的海水很咸，鱼都是海鱼。", "explanation": "这里应该用〈海域〉。流域是河流所经过的陆地区域，海水很咸、有海鱼的只能是海域，不能说流域。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea50f9b6-3a44-4278-abbe-9c85b78917e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91922, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "颜色", "is_correct": false, "explanation": "语义：「颜色」不是可以被政府规划的对象，「为这个颜色制定规划」说不通。"}, {"text": "流域", "is_correct": true, "explanation": "正确答案。政府可以为一大片地区制定规划，「流域」正合适。"}, {"text": "面孔", "is_correct": false, "explanation": "体貌：「面孔」指人的脸，不能作为政府规划的对象。"}, {"text": "乐曲", "is_correct": false, "explanation": "语义：「乐曲」是音乐作品，不是地区，不能作为规划的范围。"}], "explanations": {"颜色": "语义：「颜色」不是可以被政府规划的对象，「为这个颜色制定规划」说不通。", "流域": "正确答案。政府可以为一大片地区制定规划，「流域」正合适。", "面孔": "体貌：「面孔」指人的脸，不能作为政府规划的对象。", "乐曲": "语义：「乐曲」是音乐作品，不是地区，不能作为规划的范围。"}, "sentence_index": 6, "correct_answer": "流域"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个流域很会讲笑话，逗得大家直笑。", "explanation": "这里应该用〈他〉。流域是地区，不会讲笑话；说人幽默要用「他」。"}, {"text": "这个流域穿着一双很旧的鞋。", "explanation": "这里应该用〈他〉。流域是地区，不会穿鞋；说人穿鞋要用「他」。"}, {"text": "这个流域饿得走不动了，想找点吃的。", "explanation": "这里应该用〈我〉。流域是地区，不会饿；说人饿了要用「我」等指人的词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea50f9b6-3a44-4278-abbe-9c85b78917e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91922, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条长江流域一带有很多支流。", "corrected_sentence": "长江流域一带有很多支流。", "error_description": "量词错误：「长江流域」是一大片地区，前面不能加「条」（「条」用于河流、道路等细长的东西），应直接说「长江流域一带」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea50f9b6-3a44-4278-abbe-9c85b78917e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91922, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "政府正在保护这条流域的水质。", "corrected_sentence": "政府正在保护这个流域的水质。", "error_description": "量词错误：「流域」是一大片地区，应说「这个流域」或「这片流域」，不能用「条」（「条」用于河流、道路等细长的东西）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea50f9b6-3a44-4278-abbe-9c85b78917e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
