INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91931, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "做东西的公司。", "primary_collocate": null, "pronunciation": "shēng chǎn qǐ yè", "ipa": "ʂɤŋ˥ ʈʂʰan˨˩˦ tɕʰi˨˩˦ je˥˩", "syllable_count": 4, "sentences": [{"text": "他在一家生产企业做工程师。", "target_word": "生产企业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家生产企业做的玩具很受欢迎。", "target_word": "生产企业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们城里有很多生产企业。", "target_word": "生产企业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家生产企业每天做一万双鞋。", "target_word": "生产企业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐姐想去一家生产企业工作。", "target_word": "生产企业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个牌子的杯子来自一家生产企业。", "target_word": "生产企业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那家生产企业为工人建了新宿舍。", "target_word": "生产企业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家生产企业的工厂在城外。", "target_word": "生产企业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸的朋友开了一家生产企业，做家具。", "target_word": "生产企业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生产企业的工人早上七点就开始工作。", "target_word": "生产企业", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "家", "label": "量词"}, {"form": "生產企業", "label": "繁体"}], "register": "中性", "sense_fingerprint": "做东西、有工厂的公司，日常说法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75fd202e-20bb-4aa3-a2f5-79e25091db51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91931, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "诗歌", "is_correct": false, "explanation": "语义：「诗歌」是文学作品，不是公司，「在一家诗歌做工程师」说不通。"}, {"text": "生产企业", "is_correct": true, "explanation": "正确答案。「生产企业」指做东西的公司，工程师可以在这样的公司工作。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：「身材」指人的体形，不能用来指工作的地方。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：「颜色」不是公司，「在一家颜色做工程师」说不通。"}], "explanations": {"诗歌": "语义：「诗歌」是文学作品，不是公司，「在一家诗歌做工程师」说不通。", "生产企业": "正确答案。「生产企业」指做东西的公司，工程师可以在这样的公司工作。", "身材": "体貌：「身材」指人的体形，不能用来指工作的地方。", "颜色": "语义：「颜色」不是公司，「在一家颜色做工程师」说不通。"}, "sentence_index": 0, "correct_answer": "生产企业"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家生产企业每天帮客户存钱取钱。", "explanation": "这里应该用〈银行〉。生产企业是做东西的公司，办理存取款的是银行，不能说生产企业。"}, {"text": "这家生产企业每天看病的人很多。", "explanation": "这里应该用〈医院〉。生产企业是做东西的公司，不给人看病。"}, {"text": "这家生产企业有三百名学生。", "explanation": "这里应该用〈学校〉。生产企业是做东西的公司，不招收学生，「学生」说的是学校里的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea50f9b6-3a44-4278-abbe-9c85b78917e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91931, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "面孔", "is_correct": false, "explanation": "体貌：「面孔」指人的脸，不能作为公司，「那家面孔」说不通。"}, {"text": "谜语", "is_correct": false, "explanation": "语义：「谜语」是一种文字游戏，不是公司，不能为工人建宿舍。"}, {"text": "生产企业", "is_correct": true, "explanation": "正确答案。「生产企业」是做东西的公司，可以为工人建宿舍。"}, {"text": "乐器", "is_correct": false, "explanation": "语义：「乐器」是演奏用的器具，不是公司，不能为工人建宿舍。"}], "explanations": {"面孔": "体貌：「面孔」指人的脸，不能作为公司，「那家面孔」说不通。", "谜语": "语义：「谜语」是一种文字游戏，不是公司，不能为工人建宿舍。", "生产企业": "正确答案。「生产企业」是做东西的公司，可以为工人建宿舍。", "乐器": "语义：「乐器」是演奏用的器具，不是公司，不能为工人建宿舍。"}, "sentence_index": 6, "correct_answer": "生产企业"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家生产企业正在教小朋友唱歌。", "explanation": "这里应该用〈幼儿园〉。生产企业是做东西的公司，不教小朋友唱歌。"}, {"text": "这家生产企业每天都住满了客人。", "explanation": "这里应该用〈旅馆〉。生产企业是做东西的公司，不提供住宿。"}, {"text": "这家生产企业每天都有很多旅客上下车。", "explanation": "这里应该用〈车站〉。生产企业是做东西的公司，不接送旅客。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea50f9b6-3a44-4278-abbe-9c85b78917e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91931, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条生产企业每天生产很多玩具。", "corrected_sentence": "这家生产企业每天生产很多玩具。", "error_description": "量词错误：「生产企业」是公司，应说「家」，不能用「条」（「条」用于细长的东西）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea50f9b6-3a44-4278-abbe-9c85b78917e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91931, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那本生产企业今年新招了很多工人。", "corrected_sentence": "那家生产企业今年新招了很多工人。", "error_description": "量词错误：「生产企业」是公司，应说「家」，不能用「本」（「本」用于书籍）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea50f9b6-3a44-4278-abbe-9c85b78917e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
