INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91945, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "很短的电影。", "primary_collocate": null, "pronunciation": "duǎn piàn", "ipa": "tu̯an˨˩˦ pʰi̯ɛn˥˩", "syllable_count": 2, "sentences": [{"text": "这部短片只有五分钟。", "target_word": "短片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们昨天在学校看了一部短片。", "target_word": "短片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拍了一部很有意思的短片。", "target_word": "短片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个短片的故事很简单。", "target_word": "短片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想把这部短片送给朋友。", "target_word": "短片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影节上有很多外国短片。", "target_word": "短片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部短片没有对话，只有音乐。", "target_word": "短片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们写短片的故事。", "target_word": "短片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的短片得过一个奖。", "target_word": "短片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王学电影，想先拍短片。", "target_word": "短片", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "部", "label": "量词"}, {"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "时间很短的电影，常指拍成作品的小电影", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ee16441-0431-43df-88c5-2c1ecd454501') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91945, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "短片", "is_correct": true, "explanation": "正确：“短片”指时间很短的影片，与“只有五分钟”相符。"}, {"text": "长篇", "is_correct": false, "explanation": "语义：“长篇”指篇幅很长的作品，与“只有五分钟”矛盾。"}, {"text": "大片", "is_correct": false, "explanation": "语义：“大片”指投资大、规模大的影片，一般时间较长，与“只有五分钟”不符。"}, {"text": "巨著", "is_correct": false, "explanation": "语域：“巨著”是庄重的书面用语，多指鸿篇巨制，说一部影片时口语不这样讲；且与“只有五分钟”矛盾。"}], "explanations": {"短片": "正确：“短片”指时间很短的影片，与“只有五分钟”相符。", "长篇": "语义：“长篇”指篇幅很长的作品，与“只有五分钟”矛盾。", "大片": "语义：“大片”指投资大、规模大的影片，一般时间较长，与“只有五分钟”不符。", "巨著": "语域：“巨著”是庄重的书面用语，多指鸿篇巨制，说一部影片时口语不这样讲；且与“只有五分钟”矛盾。"}, "sentence_index": 0, "correct_answer": "短片"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这部短片有两个小时，我们看了一下午。", "explanation": "这里应该用〈长片〉。“短片”指时间很短的影片，两个小时的作品要说“长片”。"}, {"text": "这部短片只有三页，但是故事很感人。", "explanation": "这里应该用〈短篇小说〉。“短片”指很短的电影，不是文字作品；“三页”说的是文字篇幅，要用“短篇小说”。"}, {"text": "这部短片一共播了五十集。", "explanation": "这里应该用〈连续剧〉。“短片”是一部完整的短作品，不会分五十集连播；多集连播的作品要说“连续剧”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e8ac8a2-35e0-433f-81a2-bc7c511da4fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91945, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "短片", "is_correct": true, "explanation": "正确：“短片”是一部很短的影片，与“没有对话，只有音乐”相符。"}, {"text": "相声", "is_correct": false, "explanation": "语义：“相声”以对口说唱、台词为主，与“没有对话，只有音乐”矛盾。"}, {"text": "小说", "is_correct": false, "explanation": "语义：“小说”是文字作品，不会只有音乐，与“没有对话，只有音乐”的描述矛盾。"}, {"text": "戏文", "is_correct": false, "explanation": "语域：“戏文”是旧时戏曲的书面文本用语，现代口语和影片描述中不用；且戏文以唱词和念白为主，与“没有对话”矛盾。"}], "explanations": {"短片": "正确：“短片”是一部很短的影片，与“没有对话，只有音乐”相符。", "相声": "语义：“相声”以对口说唱、台词为主，与“没有对话，只有音乐”矛盾。", "小说": "语义：“小说”是文字作品，不会只有音乐，与“没有对话，只有音乐”的描述矛盾。", "戏文": "语域：“戏文”是旧时戏曲的书面文本用语，现代口语和影片描述中不用；且戏文以唱词和念白为主，与“没有对话”矛盾。"}, "sentence_index": 6, "correct_answer": "短片"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这部短片有三十关，难度很大。", "explanation": "这里应该用〈游戏〉。“短片”是电影，没有“关”（关卡）；这样的结构属于游戏。"}, {"text": "这部短片有四个乐章，每个乐章风格不同。", "explanation": "这里应该用〈交响曲〉。“短片”是电影，不分乐章；乐章是交响曲的结构。"}, {"text": "这部短片有十万个词条，每个词条都有解释。", "explanation": "这里应该用〈词典〉。“短片”是电影，没有词条；词条属于词典。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e8ac8a2-35e0-433f-81a2-bc7c511da4fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91945, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们在学校里做了一张短片。", "corrected_sentence": "我们在学校里做了一部短片。", "error_description": "错误：量词“张”用于纸张、照片等平面物，影片应用“部”。正确形式是“做了一部短片”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e8ac8a2-35e0-433f-81a2-bc7c511da4fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91945, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "周末我和朋友一起看了一本短片。", "corrected_sentence": "周末我和朋友一起看了一部短片。", "error_description": "错误：量词“本”用于书籍，影片应用“部”（或“个”）。正确形式是“看了一部短片”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e8ac8a2-35e0-433f-81a2-bc7c511da4fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
