INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91946, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "时间较短的影片。", "primary_collocate": null, "pronunciation": "duǎn piàn", "ipa": "tu̯an˨˩˦ pʰi̯ɛn˥˩", "syllable_count": 2, "sentences": [{"text": "我在手机上看了一个短片。", "target_word": "短片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个短片只有三十秒。", "target_word": "短片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天睡前都看短片。", "target_word": "短片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈给我发来一个孩子的短片。", "target_word": "短片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个短片拍的是我家的小狗。", "target_word": "短片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司做了一个介绍新产品的短片。", "target_word": "短片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把旅行的短片放在网上了。", "target_word": "短片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上课前，老师给我们放了一个短片。", "target_word": "短片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想学做短片，不知道从哪儿开始。", "target_word": "短片", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "短片里的音乐很好听。", "target_word": "短片", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "部", "label": "量词"}], "register": "中性", "sense_fingerprint": "时间较短的影片，如手机或网上看的小视频", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ee16441-0431-43df-88c5-2c1ecd454501') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91946, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "短片", "is_correct": true, "explanation": "正确：“短片”指时间较短的影片或视频，手机上能看，与句意相符。"}, {"text": "电影院", "is_correct": false, "explanation": "语义：“电影院”是放映场所，不能在手机上“看”，与“手机上”矛盾。"}, {"text": "剧院", "is_correct": false, "explanation": "语义：“剧院”是演出场所，不能在手机上看，与“手机上”矛盾。"}, {"text": "荧幕", "is_correct": false, "explanation": "语域：“荧幕”是偏书面的说法，口语多说“屏幕”；且“看了一个荧幕”指屏幕本身，不是可看的内容。"}], "explanations": {"短片": "正确：“短片”指时间较短的影片或视频，手机上能看，与句意相符。", "电影院": "语义：“电影院”是放映场所，不能在手机上“看”，与“手机上”矛盾。", "剧院": "语义：“剧院”是演出场所，不能在手机上看，与“手机上”矛盾。", "荧幕": "语域：“荧幕”是偏书面的说法，口语多说“屏幕”；且“看了一个荧幕”指屏幕本身，不是可看的内容。"}, "sentence_index": 0, "correct_answer": "短片"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个短片讲的是一座城市的历史，有两个小时。", "explanation": "这里应该用〈长视频〉。“短片”指时间较短的视频，讲两个小时的内容要说“长视频”。"}, {"text": "这部短片分成了三十集，每周播一集。", "explanation": "这里应该用〈电视剧〉。“短片”是单独的短作品，不会分三十集播出；分集播出的作品要说“电视剧”。"}, {"text": "这部短片贴在教室的墙上，大家都能看到。", "explanation": "这里应该用〈海报〉。“短片”是影片，不能贴在墙上；贴在墙上的是海报。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e8ac8a2-35e0-433f-81a2-bc7c511da4fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91946, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "短片", "is_correct": true, "explanation": "正确：“短片”是拍成的视频，可以放在网上，与“旅行的”相符。"}, {"text": "行李", "is_correct": false, "explanation": "语义：“行李”是出门携带的物品，不能“放在网上”，与句意矛盾。"}, {"text": "病历", "is_correct": false, "explanation": "语义：“病历”是私人的医疗记录，不会像旅行的内容那样放在网上，与句意矛盾。"}, {"text": "讣告", "is_correct": false, "explanation": "语域：“讣告”是报丧用的庄重书面文体，与分享旅行的口吻不符。"}], "explanations": {"短片": "正确：“短片”是拍成的视频，可以放在网上，与“旅行的”相符。", "行李": "语义：“行李”是出门携带的物品，不能“放在网上”，与句意矛盾。", "病历": "语义：“病历”是私人的医疗记录，不会像旅行的内容那样放在网上，与句意矛盾。", "讣告": "语域：“讣告”是报丧用的庄重书面文体，与分享旅行的口吻不符。"}, "sentence_index": 6, "correct_answer": "短片"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个短片的比分是二比一，很精彩。", "explanation": "这里应该用〈比赛〉。“短片”是影片，没有比分；比分只用于比赛。"}, {"text": "这个短片有十课，每课讲一个语法。", "explanation": "这里应该用〈教材〉。“短片”是视频，没有“课”的结构；课和语法属于教材。"}, {"text": "这个短片有三百公里长，很壮观。", "explanation": "这里应该用〈河〉。“短片”指很短的影片，不能用来形容三百公里的长度；这样的长度只用于河流等。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e8ac8a2-35e0-433f-81a2-bc7c511da4fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91946, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她给朋友发了一只短片。", "corrected_sentence": "她给朋友发了一个短片。", "error_description": "错误：量词“只”用于动物，短片应用“个”。正确形式是“发了一个短片”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e8ac8a2-35e0-433f-81a2-bc7c511da4fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91946, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "朋友昨晚给我发了一张短片。", "corrected_sentence": "朋友昨晚给我发了一个短片。", "error_description": "错误：量词“张”用于纸张、照片等平面物，短片应用“个”。正确形式是“发了一个短片”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e8ac8a2-35e0-433f-81a2-bc7c511da4fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91947, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bd0453e-b39e-4aac-817e-e61ec63def76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91947, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bd0453e-b39e-4aac-817e-e61ec63def76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91947, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "支援是别人有难处的时候，你送东西或者去帮忙。", "primary_collocate": null, "pronunciation": "zhī yuán", "ipa": "ʈʂɨ˥ ɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "邻居家有困难，我们去支援他们。", "target_word": "支援", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友家的房子进水了，我立刻去支援他。", "target_word": "支援", "complexity_tier": "T3", "furigana": "péng yǒu jiā de fáng zi jìn shuǐ le, wǒ lì kè qù zhī yuán tā.", "sentence_source": "generated"}, {"text": "村里发生火灾，大家都来支援。", "target_word": "支援", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他生病住院，同事们送水果支援他。", "target_word": "支援", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家没钱买书，老师常常支援我。", "target_word": "支援", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她最困难的时候，是你支援了她。", "target_word": "支援", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友遇到麻烦，我一定去支援。", "target_word": "支援", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下大雨了，邻居送来雨伞支援我们。", "target_word": "支援", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他支援过我很多次，我不会忘。", "target_word": "支援", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学有难处，大家都愿意支援他。", "target_word": "支援", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "支援了", "label": "体标"}, {"form": "支援过", "label": "体标"}], "register": "中性", "sense_fingerprint": "别人遇到困难时送东西或去帮忙", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a39b3718-fe59-4628-a5c2-d2e3e12e9e82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91947, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "支援", "is_correct": true, "explanation": "正确：zhī yuán，指别人有难处时送东西或去帮忙。"}, {"text": "资源", "is_correct": false, "explanation": "资 zī（第一声）与 zhī（第一声）声母不同，z 与 zh 相混，意思是资源。"}, {"text": "职员", "is_correct": false, "explanation": "职 zhí（第二声）与 zhī（第一声）声调不同，意思是职员。"}, {"text": "志愿", "is_correct": false, "explanation": "志 zhì（第四声）与 zhī（第一声）声调不同，yuàn（第四声）与 yuán（第二声）声调也不同，意思是志愿。"}, {"text": "机缘", "is_correct": false, "explanation": "jī（第一声）与 zhī（第一声）声母不同，j 与 zh 相混，意思是机缘。"}], "explanations": {"支援": "正确：zhī yuán，指别人有难处时送东西或去帮忙。", "资源": "资 zī（第一声）与 zhī（第一声）声母不同，z 与 zh 相混，意思是资源。", "职员": "职 zhí（第二声）与 zhī（第一声）声调不同，意思是职员。", "志愿": "志 zhì（第四声）与 zhī（第一声）声调不同，yuàn（第四声）与 yuán（第二声）声调也不同，意思是志愿。", "机缘": "jī（第一声）与 zhī（第一声）声母不同，j 与 zh 相混，意思是机缘。"}, "sentence_index": null, "correct_answer": "支援"}, "level_3": {"options": [{"text": "支援", "is_correct": true, "explanation": "句中“有困难”的人需要别人帮忙，“支援”指送东西或去帮忙，符合语境。"}, {"text": "抛弃", "is_correct": false, "explanation": "语义：“抛弃”是丢下不管，与“有困难”的人需要帮助、我们去帮忙的语境相反。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：“嘲笑”是讥笑，与我们去帮忙的善意语境相矛盾。"}, {"text": "参观", "is_correct": false, "explanation": "搭配：“参观”多用于场所、展览，不能直接以“他们”这样的人作对象来表示去帮忙。"}], "explanations": {"支援": "句中“有困难”的人需要别人帮忙，“支援”指送东西或去帮忙，符合语境。", "抛弃": "语义：“抛弃”是丢下不管，与“有困难”的人需要帮助、我们去帮忙的语境相反。", "嘲笑": "语义：“嘲笑”是讥笑，与我们去帮忙的善意语境相矛盾。", "参观": "搭配：“参观”多用于场所、展览，不能直接以“他们”这样的人作对象来表示去帮忙。"}, "sentence_index": 0, "correct_answer": "支援"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们都支援他的决定。", "explanation": "这里应该用〈支持〉。支援指用人力、物资去帮助有困难的人或单位，对决定和意见表示赞成要用支持。"}, {"text": "父母的话支援了我，我很有信心。", "explanation": "这里应该用〈鼓励〉。支援指用人力、物资去帮忙，给人精神上的激励要用鼓励。"}, {"text": "这根柱子支援着屋顶。", "explanation": "这里应该用〈支撑〉。支援的对象是人或单位，柱子承托屋顶要用支撑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bd0453e-b39e-4aac-817e-e61ec63def76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91947, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "支援", "is_correct": true, "explanation": "句中“朋友遇到麻烦”，说话人说“我一定去”，“支援”指去帮忙，符合语境。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：“拒绝”是不接受、不答应，与“我一定去”的主动帮忙相矛盾。"}, {"text": "逃避", "is_correct": false, "explanation": "语义：“逃避”是躲开，与“我一定去”的意思相反。"}, {"text": "讨论", "is_correct": false, "explanation": "配价：“讨论”需要带所讨论的内容，不能只说“我一定去讨论”来表示去帮朋友。"}], "explanations": {"支援": "句中“朋友遇到麻烦”，说话人说“我一定去”，“支援”指去帮忙，符合语境。", "拒绝": "语义：“拒绝”是不接受、不答应，与“我一定去”的主动帮忙相矛盾。", "逃避": "语义：“逃避”是躲开，与“我一定去”的意思相反。", "讨论": "配价：“讨论”需要带所讨论的内容，不能只说“我一定去讨论”来表示去帮朋友。"}, "sentence_index": 6, "correct_answer": "支援"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们支援新同学的加入。", "explanation": "这里应该用〈欢迎〉。支援指用人力、物资去帮忙，对新人的加入表示欢迎要用欢迎。"}, {"text": "大家支援他的生日。", "explanation": "这里应该用〈庆祝〉。支援的对象是需要帮助的人或单位，给生日表示喜庆要用庆祝。"}, {"text": "老师支援了我的努力。", "explanation": "这里应该用〈表扬〉。支援指给予实际帮助，对别人的努力给予肯定要用表扬。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bd0453e-b39e-4aac-817e-e61ec63def76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91947, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "救援队支援地很及时。", "corrected_sentence": "救援队支援得很及时。", "error_description": "错误：“支援地很及时”。正确：“支援得很及时”。补语标记应用“得”，不能用表示修饰的“地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bd0453e-b39e-4aac-817e-e61ec63def76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91947, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他去年去支援过了灾区。", "corrected_sentence": "他去年去支援过灾区。", "error_description": "错误：“支援过了灾区”。正确：“支援过灾区”。“过”已表示经历，与“了”不能同用，应去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bd0453e-b39e-4aac-817e-e61ec63def76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
