INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91948, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用人力、物力、财力或其他方式支持和援助。", "primary_collocate": null, "pronunciation": "zhī yuán", "ipa": "ʈʂɨ˥ ɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "国家用物资支援受灾的地区。", "target_word": "支援", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司派了十个工人去支援工厂。", "target_word": "支援", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生们去山区支援当地的医院。", "target_word": "支援", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "许多国家用资金支援灾区。", "target_word": "支援", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北京的医生支援了武汉的医院。", "target_word": "支援", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们用技术支援这个小城市。", "target_word": "支援", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家把粮食送去，支援前线。", "target_word": "支援", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新工厂缺人，老厂派人来支援。", "target_word": "支援", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司愿意出钱支援学校建图书馆。", "target_word": "支援", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府一直在资金上支援农村教育。", "target_word": "支援", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "支援了", "label": "体标"}, {"form": "支援过", "label": "体标"}], "register": "中性", "sense_fingerprint": "用人力物力财力支持援助某地或某单位", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a39b3718-fe59-4628-a5c2-d2e3e12e9e82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91948, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "支援", "is_correct": true, "explanation": "正确：zhī yuán，指用人力、物力、财力等支持和帮助。"}, {"text": "资源", "is_correct": false, "explanation": "资 zī（第一声）与 zhī（第一声）声母不同，z 与 zh 相混，意思是资源。"}, {"text": "职员", "is_correct": false, "explanation": "职 zhí（第二声）与 zhī（第一声）声调不同，意思是职员。"}, {"text": "志愿", "is_correct": false, "explanation": "志 zhì（第四声）与 zhī（第一声）声调不同，yuàn（第四声）与 yuán（第二声）声调也不同，意思是志愿。"}, {"text": "机缘", "is_correct": false, "explanation": "jī（第一声）与 zhī（第一声）声母不同，j 与 zh 相混，意思是机缘。"}], "explanations": {"支援": "正确：zhī yuán，指用人力、物力、财力等支持和帮助。", "资源": "资 zī（第一声）与 zhī（第一声）声母不同，z 与 zh 相混，意思是资源。", "职员": "职 zhí（第二声）与 zhī（第一声）声调不同，意思是职员。", "志愿": "志 zhì（第四声）与 zhī（第一声）声调不同，yuàn（第四声）与 yuán（第二声）声调也不同，意思是志愿。", "机缘": "jī（第一声）与 zhī（第一声）声母不同，j 与 zh 相混，意思是机缘。"}, "sentence_index": null, "correct_answer": "支援"}, "level_3": {"options": [{"text": "支援", "is_correct": true, "explanation": "句中“用物资”和“受灾的地区”，“支援”指用物资帮助地区，符合语境。"}, {"text": "回避", "is_correct": false, "explanation": "语义：“回避”是躲开，与国家用物资去帮助受灾地区的意思相反。"}, {"text": "参加", "is_correct": false, "explanation": "搭配：“参加”用于活动、组织，不能直接接“受灾的地区”作宾语。"}, {"text": "出售", "is_correct": false, "explanation": "配价：“出售”的宾语应是商品，不能接“受灾的地区”，句子不成立。"}], "explanations": {"支援": "句中“用物资”和“受灾的地区”，“支援”指用物资帮助地区，符合语境。", "回避": "语义：“回避”是躲开，与国家用物资去帮助受灾地区的意思相反。", "参加": "搭配：“参加”用于活动、组织，不能直接接“受灾的地区”作宾语。", "出售": "配价：“出售”的宾语应是商品，不能接“受灾的地区”，句子不成立。"}, "sentence_index": 0, "correct_answer": "支援"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们支援这个方案。", "explanation": "这里应该用〈支持〉。支援指用人力、物资去帮助，对方案表示赞成要用支持。"}, {"text": "他用现金支援了房租。", "explanation": "这里应该用〈支付〉。支援指给需要帮助的人或单位送去物资，付房租要用支付。"}, {"text": "大家支援她的善良。", "explanation": "这里应该用〈赞美〉。支援指给予实际帮助，对别人的品质表示称赞要用赞美。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bd0453e-b39e-4aac-817e-e61ec63def76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91948, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "支援", "is_correct": true, "explanation": "句中“把粮食送去”，“支援前线”指用物资去帮助前线，符合语境。"}, {"text": "欢迎", "is_correct": false, "explanation": "语义：“欢迎”是乐于接待，与“把粮食送去”的帮助语境不符，“欢迎前线”不成立。"}, {"text": "谴责", "is_correct": false, "explanation": "语义：“谴责”是严厉批评，与送粮食的善意语境相反。"}, {"text": "撤退", "is_correct": false, "explanation": "配价：“撤退”要接离开的地点，如“撤离前线”，不能直接说“撤退前线”。"}], "explanations": {"支援": "句中“把粮食送去”，“支援前线”指用物资去帮助前线，符合语境。", "欢迎": "语义：“欢迎”是乐于接待，与“把粮食送去”的帮助语境不符，“欢迎前线”不成立。", "谴责": "语义：“谴责”是严厉批评，与送粮食的善意语境相反。", "撤退": "配价：“撤退”要接离开的地点，如“撤离前线”，不能直接说“撤退前线”。"}, "sentence_index": 6, "correct_answer": "支援"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大家支援新年的到来。", "explanation": "这里应该用〈欢迎〉。支援指用人力、物资去帮忙，对新年的到来表示迎接要用欢迎。"}, {"text": "全家支援奶奶的寿辰。", "explanation": "这里应该用〈庆祝〉。支援指给需要帮助的人或单位送去物资，给寿辰表示祝贺要用庆祝。"}, {"text": "政府支援了英雄的事迹。", "explanation": "这里应该用〈表彰〉。支援指给予实际帮助，对英雄的事迹予以公开赞扬要用表彰。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bd0453e-b39e-4aac-817e-e61ec63def76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91948, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人们正在支援了灾区的重建。", "corrected_sentence": "工人们正在支援灾区的重建。", "error_description": "错误：“正在支援了”。正确：“正在支援”。“正在”表示动作进行，与表示完成的“了”不能同用，去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bd0453e-b39e-4aac-817e-e61ec63def76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91948, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工厂的工人们一直支援了农村的学校。", "corrected_sentence": "工厂的工人们一直支援着农村的学校。", "error_description": "错误：“一直支援了”。正确：“一直支援着”。“一直”表示持续，句中没有时段词，应用持续体“着”，不用表示完成的“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bd0453e-b39e-4aac-817e-e61ec63def76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
