INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91953, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "改为是把原来的变成新的。", "primary_collocate": null, "pronunciation": "gǎi wéi", "ipa": "kai˨˩˦ wei˧˥", "syllable_count": 2, "sentences": [{"text": "原来的名字太长，他把名字改为小明。", "target_word": "改为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们把星期五的会改为星期四。", "target_word": "改为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把考试时间改为下午三点。", "target_word": "改为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的名字已经改为“好运来”了。", "target_word": "改为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想把红色的灯改为白色的灯。", "target_word": "改为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为下雨，足球比赛改为明天进行。", "target_word": "改为", "complexity_tier": "T3", "furigana": "yīnwèi xiàyǔ, zúqiú bǐsài gǎi wéi míngtiān jìnxíng", "sentence_source": "generated"}, {"text": "小王把手机里的英文改为中文。", "target_word": "改为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司把每周工作六天改为五天。", "target_word": "改为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把房间的一个角落改为学习区。", "target_word": "改为", "complexity_tier": "T3", "furigana": "wǒ bǎ fángjiān de yí gè jiǎoluò gǎi wéi xuéxí qū", "sentence_source": "generated"}, {"text": "请把这个“三”字改为“五”字。", "target_word": "改为", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "把原来的东西换成新的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87287aec-525e-48a8-a475-07474285e1e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91953, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "改为", "is_correct": true, "explanation": "正确答案。“改为”表示把“原来的名字”换成“小明”，符合句意。"}, {"text": "念成", "is_correct": false, "explanation": "语义：「念成」指把字的读音读作某种发音，与句中“换名字”的意思不符。"}, {"text": "视为", "is_correct": false, "explanation": "搭配：「视为」多接抽象的观点或评价，不接具体的名称。"}, {"text": "认作", "is_correct": false, "explanation": "语义：「认作」指认定为某人或某物，与句中“换名字”的变化意义不符。"}], "explanations": {"改为": "正确答案。“改为”表示把“原来的名字”换成“小明”，符合句意。", "念成": "语义：「念成」指把字的读音读作某种发音，与句中“换名字”的意思不符。", "视为": "搭配：「视为」多接抽象的观点或评价，不接具体的名称。", "认作": "语义：「认作」指认定为某人或某物，与句中“换名字”的变化意义不符。"}, "sentence_index": 0, "correct_answer": "改为"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "河上的冰改为了水。", "explanation": "这里应该用〈融化〉。「改为」指有意把原来的做法、名称或形式换成新的，冰受热自然变成水要用「融化」。"}, {"text": "他去年改为了老师。", "explanation": "这里应该用〈成为〉。「改为」的对象是做法、名称或形式，表示人的身份变化要用「成为」。"}, {"text": "这个团队的水平改为了全国第一。", "explanation": "这里应该用〈提高〉。「改为」用于做法、名称或形式的替换，水平的提升要用「提高」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc2b2ba6-9230-4fbc-942c-da63e836e657') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91953, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "改为", "is_correct": true, "explanation": "正确答案。“改为”表示把手机里的英文换成中文，符合句意。"}, {"text": "看作", "is_correct": false, "explanation": "语义：「看作」指把某物认定为另一种事物，与“把英文换成中文”的变换意义不符。"}, {"text": "称作", "is_correct": false, "explanation": "搭配：「称作」多用于给人或事物命名，不能用于把英文内容替换为中文。"}, {"text": "算作", "is_correct": false, "explanation": "语义：「算作」指计入某一类，与句中“手机里的英文被替换”的意思不符。"}], "explanations": {"改为": "正确答案。“改为”表示把手机里的英文换成中文，符合句意。", "看作": "语义：「看作」指把某物认定为另一种事物，与“把英文换成中文”的变换意义不符。", "称作": "搭配：「称作」多用于给人或事物命名，不能用于把英文内容替换为中文。", "算作": "语义：「算作」指计入某一类，与句中“手机里的英文被替换”的意思不符。"}, "sentence_index": 6, "correct_answer": "改为"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我改为了一场比赛的冠军。", "explanation": "这里应该用〈获得〉。「改为」指把原有的做法、名称或形式换成另一种，赢得荣誉要用「获得」。"}, {"text": "班里改为了三个学生。", "explanation": "这里应该用〈增加〉。「改为」表示替换，人数变多要用「增加」。"}, {"text": "他的心情改为了一场雨。", "explanation": "这里应该用〈比作〉。「改为」指把原有的做法、名称或形式换掉，把心情比喻成雨要用「比作」，不能用「改为」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc2b2ba6-9230-4fbc-942c-da63e836e657') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91953, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈把菜单改为英文版着。", "corrected_sentence": "妈妈把菜单改为英文版。", "error_description": "“改为”的误用。“改为”表示一次性的替换动作，句末不能加表示持续状态的“着”。正确形式是“改为英文版”，不加“着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc2b2ba6-9230-4fbc-942c-da63e836e657') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91953, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校把考试日期改为下周一着。", "corrected_sentence": "学校把考试日期改为下周一。", "error_description": "“改为”的误用。“改为”表示一次性的替换动作，句末不能加表示持续状态的“着”。正确形式是“改为下周一”，不加“着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc2b2ba6-9230-4fbc-942c-da63e836e657') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
