INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91954, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把原来的做法、名称或形式改变成另一种。", "primary_collocate": null, "pronunciation": "gǎi wéi", "ipa": "kai˨˩˦ wei˧˥", "syllable_count": 2, "sentences": [{"text": "学校的规定改为每天八点上课。", "target_word": "改为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路的名称已经改为中山路。", "target_word": "改为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "以前用纸买票，现在改为用手机买票。", "target_word": "改为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把见面的做法改为网上聊天。", "target_word": "改为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司决定把开会形式改为视频会议。", "target_word": "改为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小城原来叫东村，后来改为东城。", "target_word": "改为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们把每月一次的活动改为每周一次。", "target_word": "改为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作方式改为在家上班后，他不用坐车了。", "target_word": "改为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院把现金付款改为手机付款。", "target_word": "改为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个节目的名称改为“周末音乐会”。", "target_word": "改为", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "把做法、名称或形式换成另一种", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87287aec-525e-48a8-a475-07474285e1e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91954, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "改为", "is_correct": true, "explanation": "正确答案。“改为”表示把规定的上课时间换成每天八点，符合句意。"}, {"text": "取消", "is_correct": false, "explanation": "语义：「取消」指撤销原有规定，不表示把规定换成新的内容。"}, {"text": "废除", "is_correct": false, "explanation": "搭配：「废除」多用于法律、制度，不接具体的上课时间。"}, {"text": "停止", "is_correct": false, "explanation": "语义：「停止」指中止某个行为，与“规定换成新的做法”的意思不符。"}], "explanations": {"改为": "正确答案。“改为”表示把规定的上课时间换成每天八点，符合句意。", "取消": "语义：「取消」指撤销原有规定，不表示把规定换成新的内容。", "废除": "搭配：「废除」多用于法律、制度，不接具体的上课时间。", "停止": "语义：「停止」指中止某个行为，与“规定换成新的做法”的意思不符。"}, "sentence_index": 0, "correct_answer": "改为"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一夜之间改为了大人。", "explanation": "这里应该用〈变成〉。「改为」用于把做法、名称或形式换掉，人自然长大要用「变成」。"}, {"text": "这块蜡烛改为了液体。", "explanation": "这里应该用〈融化〉。「改为」指有意把原来的做法、名称或形式换成新的，蜡烛受热变成液体是自然变化，要用「融化」。"}, {"text": "我们的队伍改为了五个人。", "explanation": "这里应该用〈增加〉。「改为」表示替换，人数变多要用「增加」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc2b2ba6-9230-4fbc-942c-da63e836e657') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91954, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "改为", "is_correct": true, "explanation": "正确答案。“改为”表示把每月一次的活动换成每周一次，符合句意。"}, {"text": "保留", "is_correct": false, "explanation": "语义：「保留」指不改变原来的内容，与句中“改成新频率”的意思相反。"}, {"text": "延长", "is_correct": false, "explanation": "搭配：「延长」多用于时间的长度，不接“每周一次”这种频率说法。"}, {"text": "维持", "is_correct": false, "explanation": "语义：「维持」表示保持现状，与句中“活动频率发生变化”的语境矛盾。"}], "explanations": {"改为": "正确答案。“改为”表示把每月一次的活动换成每周一次，符合句意。", "保留": "语义：「保留」指不改变原来的内容，与句中“改成新频率”的意思相反。", "延长": "搭配：「延长」多用于时间的长度，不接“每周一次”这种频率说法。", "维持": "语义：「维持」表示保持现状，与句中“活动频率发生变化”的语境矛盾。"}, "sentence_index": 6, "correct_answer": "改为"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她的身高改为了一米八。", "explanation": "这里应该用〈长到〉。「改为」指把原有的做法、名称或形式换掉，身高的增长要用「长到」。"}, {"text": "俱乐部改为了一个新成员。", "explanation": "这里应该用〈吸收〉。「改为」表示替换原有内容，接纳新成员要用「吸收」。"}, {"text": "这次考试他改为了第一名。", "explanation": "这里应该用〈取得〉。「改为」指把原有的做法、名称或形式换成另一种，取得名次要用「取得」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc2b2ba6-9230-4fbc-942c-da63e836e657') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91954, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校把上课方式改为线上着。", "corrected_sentence": "学校把上课方式改为线上。", "error_description": "“改为”的误用。“改为”表示一次性的替换动作，句末不能加表示持续状态的“着”。正确形式是“改为线上”，不加“着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc2b2ba6-9230-4fbc-942c-da63e836e657') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91954, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "公司把打卡方式改为指纹识别着。", "corrected_sentence": "公司把打卡方式改为指纹识别。", "error_description": "“改为”的误用。“改为”表示一次性的替换动作，句末不能加表示持续状态的“着”。正确形式是“改为指纹识别”，不加“着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc2b2ba6-9230-4fbc-942c-da63e836e657') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
