INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91957, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "从这一边走到那一边。", "primary_collocate": null, "pronunciation": "chuān guò", "ipa": "ʈʂʰwan˥ kwɔ˥˩", "syllable_count": 2, "sentences": [{"text": "我们穿过马路，就到学校了。", "target_word": "穿过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他穿过人群，走到老师身边。", "target_word": "穿过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫穿过院子，跑进了屋里。", "target_word": "穿过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请从这里穿过广场。", "target_word": "穿过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们穿过小树林去上学。", "target_word": "穿过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我穿过一条小街，找到了那家店。", "target_word": "穿过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "穿过这条隧道，就是我们的村子。", "target_word": "穿过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她穿过马路时，一直看着红绿灯。", "target_word": "穿过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们穿过草地，走向河边。", "target_word": "穿过", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你穿过前面的门，就能看到楼梯。", "target_word": "穿过", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "人或动物从这一边走到那一边", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a8897d1-e71b-427d-ba6c-d8eccd14f3cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91957, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "穿过", "is_correct": true, "explanation": "“穿过”表示从这一边走到那一边，这里说走过马路就到学校了。"}, {"text": "观看", "is_correct": false, "explanation": "搭配：“观看”的对象是比赛、节目等，不能说“观看马路”。"}, {"text": "学习", "is_correct": false, "explanation": "语义：“学习”指获取知识或技能，与“走过马路”无关。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指把食物咽下去，不能指走过马路。"}], "explanations": {"穿过": "“穿过”表示从这一边走到那一边，这里说走过马路就到学校了。", "观看": "搭配：“观看”的对象是比赛、节目等，不能说“观看马路”。", "学习": "语义：“学习”指获取知识或技能，与“走过马路”无关。", "吃": "语义：“吃”指把食物咽下去，不能指走过马路。"}, "sentence_index": 0, "correct_answer": "穿过"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次他穿过了考试。", "explanation": "这里应该用〈通过〉。“穿过”表示从一端到另一端的移动，不能用于考试这类抽象的事情。"}, {"text": "他已经穿过三十岁了。", "explanation": "这里应该用〈过了〉。“过了三十岁”表示年龄超过三十，“穿过”表示从一端到另一端的移动，不能用于年龄。"}, {"text": "他终于穿过了作业。", "explanation": "这里应该用〈完成〉。“穿过”表示从一端到另一端，不能用来表示做完作业。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '706c84f1-b3b0-4ece-a55b-fc10a0a53278') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91957, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "穿过", "is_correct": true, "explanation": "“穿过”表示从隧道的一端走到另一端，这里说走过隧道就到我们的村子。"}, {"text": "提醒", "is_correct": false, "explanation": "配价：“提醒”的对象是人，要说“提醒某人”，不能提醒一条隧道。"}, {"text": "驾临", "is_correct": false, "explanation": "语域：“驾临”是敬辞，指尊贵的人来到某地，不用于说走过隧道。"}, {"text": "打扮", "is_correct": false, "explanation": "体貌：“打扮”指修饰外貌、穿戴，与走过隧道没有关系。"}], "explanations": {"穿过": "“穿过”表示从隧道的一端走到另一端，这里说走过隧道就到我们的村子。", "提醒": "配价：“提醒”的对象是人，要说“提醒某人”，不能提醒一条隧道。", "驾临": "语域：“驾临”是敬辞，指尊贵的人来到某地，不用于说走过隧道。", "打扮": "体貌：“打扮”指修饰外貌、穿戴，与走过隧道没有关系。"}, "sentence_index": 6, "correct_answer": "穿过"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她在医院穿过了一个月。", "explanation": "这里应该用〈度过〉。“穿过”表示从一端到另一端，不能用于时间，度过一段时间要说“度过”。"}, {"text": "这个孩子的身高穿过了父亲。", "explanation": "这里应该用〈超过〉。“穿过”指从一端到另一端，不能表示在身高上胜过别人。"}, {"text": "这次就穿过他吧。", "explanation": "这里应该用〈放过〉。“穿过”指从一端到另一端，不能表示不追究、饶过某人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '706c84f1-b3b0-4ece-a55b-fc10a0a53278') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91957, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他穿过过树林，去找朋友。", "corrected_sentence": "他穿过树林，去找朋友。", "error_description": "动词“穿过”后面不能重复“过”。错误形式是“穿过过树林”，正确形式是“穿过树林”，应删去多余的“过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '706c84f1-b3b0-4ece-a55b-fc10a0a53278') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91957, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我很穿过公园去上班。", "corrected_sentence": "我穿过公园去上班。", "error_description": "“很”不能修饰动作动词“穿过”。错误形式是“很穿过”，正确形式是“穿过”，应删去“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '706c84f1-b3b0-4ece-a55b-fc10a0a53278') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
