INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91960, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "依法或依规定具有做某事的权利。", "primary_collocate": null, "pronunciation": "yǒu quán", "ipa": "joʊ˨˩˦ tɕʰɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "根据法律，公民有权参加选举。", "target_word": "有权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "按规定，工作满一年的人有权休假。", "target_word": "有权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察有权在路上检查司机的证件。", "target_word": "有权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法律说，买到坏东西的人有权退货。", "target_word": "有权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司规定，经理有权决定这笔钱怎么用。", "target_word": "有权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校长有权按学校规定处理这件事。", "target_word": "有权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "租房的人有权按合同住到年底。", "target_word": "有权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法院有权决定这个案子怎么办。", "target_word": "有权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "按照合同，我们有权要求他们按时送货。", "target_word": "有权", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法律规定，病人有权知道自己的病情。", "target_word": "有权", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "依照法律或规定拥有做某事的权利", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87287aec-525e-48a8-a475-07474285e1e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91960, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "有权", "is_correct": true, "explanation": "正确答案。yǒu quán，意思是依法拥有做某事的权利。"}, {"text": "有钱", "is_correct": false, "explanation": "qián 与 quán 的元音不同（i 与 u），意思是拥有钱财。"}, {"text": "有缘", "is_correct": false, "explanation": "yuán 与 quán 的声母不同（y 与 q），意思是有缘分。"}, {"text": "有券", "is_correct": false, "explanation": "quàn（第四声）与 quán（第二声）声调不同，意思是拥有优惠券。"}], "explanations": {"有权": "正确答案。yǒu quán，意思是依法拥有做某事的权利。", "有钱": "qián 与 quán 的元音不同（i 与 u），意思是拥有钱财。", "有缘": "yuán 与 quán 的声母不同（y 与 q），意思是有缘分。", "有券": "quàn（第四声）与 quán（第二声）声调不同，意思是拥有优惠券。"}, "sentence_index": null, "correct_answer": "有权"}, "level_3": {"options": [{"text": "有权", "is_correct": true, "explanation": "正确答案。“有权”表示根据法律，公民有权利参加选举，符合句意。"}, {"text": "禁止", "is_correct": false, "explanation": "语义：「禁止」表示不允许，与“根据法律”规定公民权利的语境相反。"}, {"text": "不许", "is_correct": false, "explanation": "语义：「不许」表示不让做，与法律赋予公民的权利相反。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：「拒绝」表示不接受或不同意，法律不会规定公民拒绝参加选举，与句意相反。"}], "explanations": {"有权": "正确答案。“有权”表示根据法律，公民有权利参加选举，符合句意。", "禁止": "语义：「禁止」表示不允许，与“根据法律”规定公民权利的语境相反。", "不许": "语义：「不许」表示不让做，与法律赋予公民的权利相反。", "拒绝": "语义：「拒绝」表示不接受或不同意，法律不会规定公民拒绝参加选举，与句意相反。"}, "sentence_index": 0, "correct_answer": "有权"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他有权一口气做完这十道题。", "explanation": "这里应该用〈有精力〉。「有权」指依规定具有做某事的权利，做事的精力要用「有精力」。"}, {"text": "她有权独自长得很高。", "explanation": "这里应该用〈长高〉。「有权」指依规定具有做某事的权利，身高的增长不能用「有权」。"}, {"text": "他有权对音乐感兴趣。", "explanation": "这里应该用〈有兴趣〉。「有权」指依法或依规定具有做某事的权利，对事物的喜爱要用「有兴趣」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc2b2ba6-9230-4fbc-942c-da63e836e657') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91960, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "有权", "is_correct": true, "explanation": "正确答案。“有权”表示租房的人依合同有权利住到年底，符合句意。"}, {"text": "不准", "is_correct": false, "explanation": "语义：「不准」表示禁止，与“按合同住到年底”的权利相反。"}, {"text": "阻止", "is_correct": false, "explanation": "搭配：「阻止」多用于阻拦他人的行为，不能用来描述租房人依合同居住的权利。"}, {"text": "限制", "is_correct": false, "explanation": "语义：「限制」表示加以约束，与句中“有权按合同住”的意思相反。"}], "explanations": {"有权": "正确答案。“有权”表示租房的人依合同有权利住到年底，符合句意。", "不准": "语义：「不准」表示禁止，与“按合同住到年底”的权利相反。", "阻止": "搭配：「阻止」多用于阻拦他人的行为，不能用来描述租房人依合同居住的权利。", "限制": "语义：「限制」表示加以约束，与句中“有权按合同住”的意思相反。"}, "sentence_index": 6, "correct_answer": "有权"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们有权一口气吃掉十个包子。", "explanation": "这里应该用〈有食欲〉。「有权」指依法或依规定具有做某事的权利，食欲方面要用「有食欲」。"}, {"text": "这次我们有权心情好。", "explanation": "这里应该用〈有心情〉。「有权」指权利，表示情绪状态要用「有心情」。"}, {"text": "这道题我有权做对。", "explanation": "这里应该用〈有把握〉。「有权」指权利，对能做对某事有信心要用「有把握」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc2b2ba6-9230-4fbc-942c-da63e836e657') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91960, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "消费者不有权要求退货。", "corrected_sentence": "消费者有权要求退货。", "error_description": "“有权”的否定错误。在“有权”前加“不”，构成“不有权”，不成立；表示没有权利应说“无权”或“没有权利”。正确形式是“有权”，不加否定词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc2b2ba6-9230-4fbc-942c-da63e836e657') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91960, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "员工不有权拒绝不合理的加班。", "corrected_sentence": "员工有权拒绝不合理的加班。", "error_description": "“有权”的否定错误。在“有权”前加“不”，构成“不有权”，不成立；表示没有权利应说“无权”或“没有权利”。正确形式是“有权”，不加否定词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc2b2ba6-9230-4fbc-942c-da63e836e657') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
