INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91965, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "演是在很多人面前，装成另一个人，做动作，说话。", "primary_collocate": null, "pronunciation": "yǎn", "ipa": "jɛn˨˩˦", "syllable_count": 1, "sentences": [{"text": "他在学校的晚会上演一只小狗。", "target_word": "演", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明演国王，小红演公主。", "target_word": "演", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们班要演一个小故事。", "target_word": "演", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在台上演了一个故事。", "target_word": "演", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她演过很多好人。", "target_word": "演", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天晚上，同学们要在大家面前演一出小品。", "target_word": "演", "complexity_tier": "T3", "furigana": "míngtiān wǎnshang, tóngxuémen yào zài dàjiā miànqián yǎn yì chū xiǎopǐn.", "sentence_source": "generated"}, {"text": "他演老人演得很像。", "target_word": "演", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事里有三个人，你想演谁？", "target_word": "演", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小女孩在台上演着一只小鸟。", "target_word": "演", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他第一次上台，不知道怎么演。", "target_word": "演", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "演了", "label": "完成体"}, {"form": "演过", "label": "经历体"}, {"form": "演着", "label": "持续体"}, {"form": "演出", "label": "复合"}, {"form": "演员", "label": "复合"}], "register": "中性", "sense_fingerprint": "在众人面前扮成别人，做动作、说话", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87287aec-525e-48a8-a475-07474285e1e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91965, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "演", "is_correct": true, "explanation": "演（yǎn，第三声）：在众人面前扮成别人、做动作，正确答案。"}, {"text": "盐", "is_correct": false, "explanation": "yán（第二声）与 yǎn（第三声）声调不同，意思是盐。"}, {"text": "烟", "is_correct": false, "explanation": "yān（第一声）与 yǎn（第三声）声调不同，意思是烟。"}, {"text": "养", "is_correct": false, "explanation": "yǎng 与 yǎn 声调相同，但韵母不同（ang 与 an），意思是饲养。"}, {"text": "验", "is_correct": false, "explanation": "yàn（第四声）与 yǎn（第三声）声调不同，意思是检验。"}], "explanations": {"演": "演（yǎn，第三声）：在众人面前扮成别人、做动作，正确答案。", "盐": "yán（第二声）与 yǎn（第三声）声调不同，意思是盐。", "烟": "yān（第一声）与 yǎn（第三声）声调不同，意思是烟。", "养": "yǎng 与 yǎn 声调相同，但韵母不同（ang 与 an），意思是饲养。", "验": "yàn（第四声）与 yǎn（第三声）声调不同，意思是检验。"}, "sentence_index": null, "correct_answer": "演"}, "level_3": {"options": [{"text": "演", "is_correct": true, "explanation": "演：表示在晚会上扮演小狗这一角色，符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指吃东西，“吃一只小狗”与晚会表演的语境不符。"}, {"text": "写", "is_correct": false, "explanation": "搭配：“写”的宾语应是文字、文章，不能说“写一只小狗”。"}, {"text": "跑", "is_correct": false, "explanation": "配价：“跑”一般不直接带“一只小狗”这样的宾语，表示扮演时句子不成立。"}], "explanations": {"演": "演：表示在晚会上扮演小狗这一角色，符合句意。", "吃": "语义：“吃”指吃东西，“吃一只小狗”与晚会表演的语境不符。", "写": "搭配：“写”的宾语应是文字、文章，不能说“写一只小狗”。", "跑": "配价：“跑”一般不直接带“一只小狗”这样的宾语，表示扮演时句子不成立。"}, "sentence_index": 0, "correct_answer": "演"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天早上用毛巾演桌子。", "explanation": "这里应该用〈擦〉。演指扮演角色或表演，擦桌子要用擦。"}, {"text": "他在教室里演了一把椅子。", "explanation": "这里应该用〈搬〉。演指扮演角色或表演，搬椅子要用搬。"}, {"text": "他在纸上演了一只小狗。", "explanation": "这里应该用〈画〉。演指在舞台或众人面前扮演角色，纸上画图要用画。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc2b2ba6-9230-4fbc-942c-da63e836e657') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91965, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "演", "is_correct": true, "explanation": "演（yǎn，第三声）：在众人面前扮成别人、做动作，正确答案。"}, {"text": "严", "is_correct": false, "explanation": "yán（第二声）与 yǎn（第三声）声调不同，意思是严格。"}, {"text": "宴", "is_correct": false, "explanation": "yàn（第四声）与 yǎn（第三声）声调不同，意思是宴席。"}, {"text": "厌", "is_correct": false, "explanation": "yàn（第四声）与 yǎn（第三声）声调不同，意思是讨厌。"}, {"text": "艳", "is_correct": false, "explanation": "yàn（第四声）与 yǎn（第三声）声调不同，意思是鲜艳。"}], "explanations": {"演": "演（yǎn，第三声）：在众人面前扮成别人、做动作，正确答案。", "严": "yán（第二声）与 yǎn（第三声）声调不同，意思是严格。", "宴": "yàn（第四声）与 yǎn（第三声）声调不同，意思是宴席。", "厌": "yàn（第四声）与 yǎn（第三声）声调不同，意思是讨厌。", "艳": "yàn（第四声）与 yǎn（第三声）声调不同，意思是鲜艳。"}, "sentence_index": null, "correct_answer": "演"}, "level_3": {"options": [{"text": "演", "is_correct": true, "explanation": "演：表示扮演老人这一角色，“演得很像”指表演逼真，符合句意。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”与后句“演得很像”不能搭配，“他唱老人演得很像”语义混乱。"}, {"text": "画", "is_correct": false, "explanation": "语义：“画”指作画，“画老人”与“演得很像”的表演语境不符。"}, {"text": "摘", "is_correct": false, "explanation": "配价：“摘”不能带“老人”作宾语，句子不成立。"}], "explanations": {"演": "演：表示扮演老人这一角色，“演得很像”指表演逼真，符合句意。", "唱": "搭配：“唱”与后句“演得很像”不能搭配，“他唱老人演得很像”语义混乱。", "画": "语义：“画”指作画，“画老人”与“演得很像”的表演语境不符。", "摘": "配价：“摘”不能带“老人”作宾语，句子不成立。"}, "sentence_index": 6, "correct_answer": "演"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天晚上在家演作业。", "explanation": "这里应该用〈做〉（或〈写〉）。演指扮演角色或表演，做作业要用做或写。"}, {"text": "妈妈每天在厨房演饭。", "explanation": "这里应该用〈做〉。演指扮演角色或表演，做饭要用做。"}, {"text": "工人昨天在路上演了一条小路。", "explanation": "这里应该用〈修〉。演指扮演角色或表演，修路要用修。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc2b2ba6-9230-4fbc-942c-da63e836e657') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91965, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她在话剧里了演一个老奶奶。", "corrected_sentence": "她在话剧里演了一个老奶奶。", "error_description": "“了”放错了位置。正确形式是“演了”，“了”放在动词之后表示完成；“了演”是错误的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc2b2ba6-9230-4fbc-942c-da63e836e657') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91965, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个小男孩在话剧里演很好。", "corrected_sentence": "这个小男孩在话剧里演得很好。", "error_description": "补语标记漏写。表示“演”的结果或程度时，动词后要用“得”，应为“演得很好”，不能说“演很好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc2b2ba6-9230-4fbc-942c-da63e836e657') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
