INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91969, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "国家派到远处，管一大片地方的大官。", "primary_collocate": null, "pronunciation": "zǒng dū", "ipa": "tsʊŋ˨˩˦ tu˥", "syllable_count": 2, "sentences": [{"text": "总督是国家派来管这个地方的官。", "target_word": "总督", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位总督住在海边的大房子里。", "target_word": "总督", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新总督昨天到了这个城市。", "target_word": "总督", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总督每年都给国王写信。", "target_word": "总督", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总督管着一大片地方。", "target_word": "总督", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个国家派了一位总督去南方。", "target_word": "总督", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当地人都很怕这位总督。", "target_word": "总督", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总督的家在山上。", "target_word": "总督", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总督坐船回国了。", "target_word": "总督", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书里说，这位总督很聪明。", "target_word": "总督", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "總督", "label": "繁体"}], "register": "中性", "sense_fingerprint": "国家派到远方管理大片地区的高级官员", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ee16441-0431-43df-88c5-2c1ecd454501') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91969, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "总督", "is_correct": true, "explanation": "正确：“总督”指国家派到远处管大片地方的大官，与“派来管这个地方”相合。"}, {"text": "管家", "is_correct": false, "explanation": "语义：管家是私人雇来料理家务的仆人，不是国家派来管地方的官。"}, {"text": "商人", "is_correct": false, "explanation": "语义：商人是做买卖的人，不会被国家派来管理地方。"}, {"text": "宫殿", "is_correct": false, "explanation": "搭配：“派来管”的对象必须是人，宫殿不能被派来管地方。"}], "explanations": {"总督": "正确：“总督”指国家派到远处管大片地方的大官，与“派来管这个地方”相合。", "管家": "语义：管家是私人雇来料理家务的仆人，不是国家派来管地方的官。", "商人": "语义：商人是做买卖的人，不会被国家派来管理地方。", "宫殿": "搭配：“派来管”的对象必须是人，宫殿不能被派来管地方。"}, "sentence_index": 0, "correct_answer": "总督"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家公司的总督每天都来检查账目。", "explanation": "这里应该用〈经理〉。总督是国家派到远处、统管一大片地方的官，不用来管理公司；检查公司账目的是经理。"}, {"text": "这家银行的总督每年都向股东报告工作。", "explanation": "这里应该用〈行长〉。总督管辖的是一大片地方，不管理银行；银行的负责人是行长。"}, {"text": "这个村的总督每年都给村民写一封信。", "explanation": "这里应该用〈村长〉。总督管的是国家派到远处的大片地区，不管一个村；管村子的是村长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e8ac8a2-35e0-433f-81a2-bc7c511da4fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91969, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "总督", "is_correct": true, "explanation": "正确：“总督”是管理当地的大官，当地人怕他，与句意相合。"}, {"text": "台风", "is_correct": false, "explanation": "搭配：量词“位”只用于人，不能用来数台风。"}, {"text": "阁下", "is_correct": false, "explanation": "语域：“阁下”是对人的敬称，不用来指称第三人。"}, {"text": "婴儿", "is_correct": false, "explanation": "语义：婴儿不会让当地人害怕，句意不通。"}], "explanations": {"总督": "正确：“总督”是管理当地的大官，当地人怕他，与句意相合。", "台风": "搭配：量词“位”只用于人，不能用来数台风。", "阁下": "语域：“阁下”是对人的敬称，不用来指称第三人。", "婴儿": "语义：婴儿不会让当地人害怕，句意不通。"}, "sentence_index": 6, "correct_answer": "总督"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "总督管着一个县。", "explanation": "这里应该用〈县令〉。总督管辖的是国家派到远处的大片地区，管一个县的是县令。"}, {"text": "总督管着一所学校。", "explanation": "这里应该用〈校长〉。总督治理大片地区，不管理一所学校；管学校的是校长。"}, {"text": "总督管着一家工厂。", "explanation": "这里应该用〈厂长〉。工厂由厂长管理，总督管辖的范围不包括工厂。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e8ac8a2-35e0-433f-81a2-bc7c511da4fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91969, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只总督昨天离开了城市。", "corrected_sentence": "这位总督昨天离开了城市。", "error_description": "“总督”指人，量词应用“位”，不应用“只”（“只”多用于动物）。正确的说法是“这位总督”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e8ac8a2-35e0-433f-81a2-bc7c511da4fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91969, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他去年开始当总督的了。", "corrected_sentence": "他去年开始当总督了。", "error_description": "“总督”后多加了“的”，名词后不能这样用。正确的说法是“开始当总督了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e8ac8a2-35e0-433f-81a2-bc7c511da4fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
