INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91970, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "旧时一国派驻殖民地或某一地区的最高官员。", "primary_collocate": null, "pronunciation": "zǒng dū", "ipa": "tsʊŋ˨˩˦ tu˥", "syllable_count": 2, "sentences": [{"text": "旧时，英国派总督去印度。", "target_word": "总督", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "殖民地的总督是最高官员。", "target_word": "总督", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位总督在殖民地住了十年。", "target_word": "总督", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总督要听国王的话。", "target_word": "总督", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一百年前，这里有一位法国总督。", "target_word": "总督", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总督下令修了一条铁路。", "target_word": "总督", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当地人不喜欢殖民地的总督。", "target_word": "总督", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "历史书上写着那位总督的故事。", "target_word": "总督", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他当过总督，后来回国了。", "target_word": "总督", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总督是殖民地最大的官。", "target_word": "总督", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "總督", "label": "繁体"}], "register": "书面", "sense_fingerprint": "旧时殖民国家派驻殖民地的最高官员", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ee16441-0431-43df-88c5-2c1ecd454501') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91970, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "总督", "is_correct": true, "explanation": "正确：殖民地时期由国家派去治理殖民地的最高官员，与“派去印度”相合。"}, {"text": "皇帝", "is_correct": false, "explanation": "语义：皇帝是国家的君主，不会被派去别的地方做官。"}, {"text": "总统", "is_correct": false, "explanation": "语义：英国是君主立宪国，没有总统，句中的“英国”与“总统”矛盾。"}, {"text": "皇宫", "is_correct": false, "explanation": "搭配：“派去”的对象是人，皇宫不能被派去印度。"}], "explanations": {"总督": "正确：殖民地时期由国家派去治理殖民地的最高官员，与“派去印度”相合。", "皇帝": "语义：皇帝是国家的君主，不会被派去别的地方做官。", "总统": "语义：英国是君主立宪国，没有总统，句中的“英国”与“总统”矛盾。", "皇宫": "搭配：“派去”的对象是人，皇宫不能被派去印度。"}, "sentence_index": 0, "correct_answer": "总督"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家报社的总督每天都来审稿。", "explanation": "这里应该用〈总编〉。总督是派驻殖民地的最高官员，不负责审阅稿件；报社里审稿的是总编。"}, {"text": "总督由当地居民投票选出，任期四年。", "explanation": "这里应该用〈市长〉。总督由派出国任命，不由当地人选举；经居民投票产生的是市长。"}, {"text": "总督每天在车间检查零件。", "explanation": "这里应该用〈质检员〉。总督管理的是殖民地的大片地区，不在车间检查零件；检查零件质量的是质检员。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e8ac8a2-35e0-433f-81a2-bc7c511da4fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91970, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "总督", "is_correct": true, "explanation": "正确：总督是殖民地的最高官员，当地人不喜欢他，与句意相合。"}, {"text": "婴儿", "is_correct": false, "explanation": "语义：婴儿不是殖民地的官员，句意不通。"}, {"text": "皇子", "is_correct": false, "explanation": "语义：皇子是君主的儿子，不是殖民地的官员。"}, {"text": "太守", "is_correct": false, "explanation": "语域：“太守”是中国古代的地方长官，不用来指殖民地的官员。"}], "explanations": {"总督": "正确：总督是殖民地的最高官员，当地人不喜欢他，与句意相合。", "婴儿": "语义：婴儿不是殖民地的官员，句意不通。", "皇子": "语义：皇子是君主的儿子，不是殖民地的官员。", "太守": "语域：“太守”是中国古代的地方长官，不用来指殖民地的官员。"}, "sentence_index": 6, "correct_answer": "总督"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "总督管着一个县。", "explanation": "这里应该用〈县令〉。总督管辖的是殖民地的大片地区，不管一个县；管一县的是县令。"}, {"text": "总督管着一所学校。", "explanation": "这里应该用〈校长〉。总督不管理学校，学校由校长负责。"}, {"text": "总督管着一家工厂。", "explanation": "这里应该用〈厂长〉。工厂由厂长管理，总督不管工厂。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e8ac8a2-35e0-433f-81a2-bc7c511da4fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91970, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一只总督在那里住了十年。", "corrected_sentence": "一位总督在那里住了十年。", "error_description": "“总督”指人，量词应用“位”，不应用“只”。正确的说法是“一位总督”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e8ac8a2-35e0-433f-81a2-bc7c511da4fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91970, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "殖民地的总督的很忙。", "corrected_sentence": "殖民地的总督很忙。", "error_description": "“总督”后多加了“的”，“的”只用在定语后，这里不需要。正确的说法是“殖民地的总督很忙”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e8ac8a2-35e0-433f-81a2-bc7c511da4fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
