INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91971, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "王国是有一个国王的国家。", "primary_collocate": null, "pronunciation": "wáng guó", "ipa": "waŋ˧˥ kuo˧˥", "syllable_count": 2, "sentences": [{"text": "这个王国的国王很年轻。", "target_word": "王国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很久以前，海边有一个小王国。", "target_word": "王国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王国里的人都爱他们的国王。", "target_word": "王国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国王住在王国中心的大城里。", "target_word": "王国", "complexity_tier": "T3", "furigana": "guó wáng zhù zài wáng guó zhōng xīn de dà chéng lǐ", "sentence_source": "generated"}, {"text": "这个王国不大，只有两座城。", "target_word": "王国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "英国是一个历史悠久的王国。", "target_word": "王国", "complexity_tier": "T3", "furigana": "yīng guó shì yí gè lì shǐ yōu jiǔ de wáng guó", "sentence_source": "generated"}, {"text": "国王把王国分给了三个儿子。", "target_word": "王国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个王国很久以前就没有了。", "target_word": "王国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "故事里，王国的公主很漂亮。", "target_word": "王国", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国王管着整个王国，每天很忙。", "target_word": "王国", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "王國", "label": "繁体"}], "register": "中性", "sense_fingerprint": "王国：有国王的国家", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d5693c-26b2-4f0a-ad61-6ebde57a6292') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91971, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "王国", "is_correct": true, "explanation": "王国：有国王的国家，与“这个……的国王”搭配。"}, {"text": "学校", "is_correct": false, "explanation": "语义：学校不是国家，不能有国王。"}, {"text": "车站", "is_correct": false, "explanation": "语义：车站是交通场所，与“国王”不搭。"}, {"text": "医院", "is_correct": false, "explanation": "搭配：“这个……的国王”要接国家，“医院”不能与“国王”搭配。"}], "explanations": {"王国": "王国：有国王的国家，与“这个……的国王”搭配。", "学校": "语义：学校不是国家，不能有国王。", "车站": "语义：车站是交通场所，与“国王”不搭。", "医院": "搭配：“这个……的国王”要接国家，“医院”不能与“国王”搭配。"}, "sentence_index": 0, "correct_answer": "王国"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这里有一张王国。", "explanation": "这里应该用〈个〉。王国的量词是“个”，“张”用于桌椅、纸张等平面物。"}, {"text": "这个国家是王国，选的是总统。", "explanation": "这里应该用〈共和国〉。王国由国王统治，选出总统的国家应说〈共和国〉。"}, {"text": "我们王国有十四亿人口。", "explanation": "这里应该用〈国家〉。王国特指有国王统治的国家，一般的国家要说〈国家〉，不能说“王国”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f43cda89-a885-4652-871f-f2ed34a5d6e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91971, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "王国", "is_correct": true, "explanation": "王国：国王统治的国家，可以被国王分给儿子。"}, {"text": "教室", "is_correct": false, "explanation": "语义：教室不是国家，不能被分给儿子。"}, {"text": "药店", "is_correct": false, "explanation": "搭配：“把……分给了”的对象要是领地，“药店”不能作为分配的对象。"}, {"text": "体育馆", "is_correct": false, "explanation": "语义：体育馆是运动场所，不是统治的领地。"}], "explanations": {"王国": "王国：国王统治的国家，可以被国王分给儿子。", "教室": "语义：教室不是国家，不能被分给儿子。", "药店": "搭配：“把……分给了”的对象要是领地，“药店”不能作为分配的对象。", "体育馆": "语义：体育馆是运动场所，不是统治的领地。"}, "sentence_index": 6, "correct_answer": "王国"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那里有一首很大的王国。", "explanation": "这里应该用〈个〉。“首”用于诗歌、歌曲，王国的量词是“个”。"}, {"text": "王国管着整个国家，每天很忙。", "explanation": "这里应该用〈政府〉。王国是被统治的国家，不是管理者，管理整个国家的应说〈政府〉。"}, {"text": "国王是我们的王国，每天很忙。", "explanation": "这里应该用〈君主〉。王国是有国王的国家，不能用来指人，指国王要说〈君主〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f43cda89-a885-4652-871f-f2ed34a5d6e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91971, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那个王国地国王很年轻。", "corrected_sentence": "那个王国的国王很年轻。", "error_description": "结构助词错误：“王国”修饰“国王”时应用“的”，不能用“地”。应为“那个王国的国王很年轻”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f43cda89-a885-4652-871f-f2ed34a5d6e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91971, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "国王把一条王国分给了三个儿子。", "corrected_sentence": "国王把一个王国分给了三个儿子。", "error_description": "量词错误：“条”用于细长的物件，不能量王国；王国应用“个”。应为“一个王国”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f43cda89-a885-4652-871f-f2ed34a5d6e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
