INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91975, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "少了，不够。", "primary_collocate": null, "pronunciation": "quē", "ipa": "tɕʰɥe˥", "syllable_count": 1, "sentences": [{"text": "这本书缺了两页。", "target_word": "缺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们打牌三缺一，你来吧。", "target_word": "缺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套杯子缺了一个，不能卖。", "target_word": "缺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份名单缺了他的名字。", "target_word": "缺", "complexity_tier": "T3", "furigana": "zhè fèn míngdān quē le tā de míngzi.", "sentence_source": "generated"}, {"text": "拼图缺了一块，怎么也拼不完。", "target_word": "缺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "数一数，还缺三个本子。", "target_word": "缺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张表缺一个日期。", "target_word": "缺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "菜单缺了一页，我们找服务员要。", "target_word": "缺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天班里缺三个人，大家都感冒了。", "target_word": "缺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "箱子里的零件缺了几个。", "target_word": "缺", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "缺了", "label": "体标"}, {"form": "缺少", "label": "复合"}], "register": "中性", "sense_fingerprint": "缺：整体中少了一部分，不完整", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '010817e2-98c0-49e8-8874-0f3dd93b1418') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91975, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "缺", "is_correct": true, "explanation": "缺（quē，第一声）表示少了一部分，不完整，是本词。"}, {"text": "约", "is_correct": false, "explanation": "约（yuē，第一声）与 quē 只差声母（y 与 q），声调相同，意思是“约定”。"}, {"text": "撅", "is_correct": false, "explanation": "撅（juē，第一声）与 quē 只差声母（j 与 q），声调相同，意思是“撅起”。"}, {"text": "却", "is_correct": false, "explanation": "却（què，第四声）与 quē 只差声调，意思是转折副词“却”。"}], "explanations": {"缺": "缺（quē，第一声）表示少了一部分，不完整，是本词。", "约": "约（yuē，第一声）与 quē 只差声母（y 与 q），声调相同，意思是“约定”。", "撅": "撅（juē，第一声）与 quē 只差声母（j 与 q），声调相同，意思是“撅起”。", "却": "却（què，第四声）与 quē 只差声调，意思是转折副词“却”。"}, "sentence_index": null, "correct_answer": "缺"}, "level_3": {"options": [{"text": "缺", "is_correct": true, "explanation": "正确：“缺”表示书少了两页，是本词的意思。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的宾语应是饮品，不能带“书”作宾语。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”不能与“书”和“页”搭配。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”指加热烹饪，与书页无关。"}], "explanations": {"缺": "正确：“缺”表示书少了两页，是本词的意思。", "喝": "搭配：“喝”的宾语应是饮品，不能带“书”作宾语。", "唱": "搭配：“唱”不能与“书”和“页”搭配。", "煮": "语义：“煮”指加热烹饪，与书页无关。"}, "sentence_index": 0, "correct_answer": "缺"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他今天缺席了会议，没有到场。", "explanation": "这里的“缺”指没有出席、不到场，是另一个义项，与本词“整体中少了一部分”的意思不同。"}, {"text": "他最大的缺点是太怕麻烦。", "explanation": "这里的“缺”指缺点、毛病，是另一个义项，与本词“整体中少了一部分”的意思不同。"}, {"text": "他这人太缺德，大家都不喜欢他。", "explanation": "这里的“缺”指缺少道德、品行不端，是另一个义项，与本词“整体中少了一部分”的意思不同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bc8d629-ae1c-4edc-ba37-b7f4bba02d3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
