INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91976, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "缺少；不够。", "primary_collocate": null, "pronunciation": "quē", "ipa": "tɕʰɥe˥", "syllable_count": 1, "sentences": [{"text": "这个队还缺一个守门员。", "target_word": "缺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们家最近缺水，不能洗太久。", "target_word": "缺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不缺钱，只缺时间。", "target_word": "缺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做饭时发现缺盐了。", "target_word": "缺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司缺有经验的人。", "target_word": "缺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沙漠里缺水，树很少。", "target_word": "缺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天开会，还缺几把椅子。", "target_word": "缺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个汤好像缺味道，再放点盐吧。", "target_word": "缺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校缺老师，一个人要教两个班。", "target_word": "缺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他什么都不缺，就缺一个朋友。", "target_word": "缺", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "缺了", "label": "体标"}, {"form": "缺少", "label": "复合"}, {"form": "缺乏", "label": "复合"}], "register": "中性", "sense_fingerprint": "缺：缺少某种东西或人，数量不够", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '010817e2-98c0-49e8-8874-0f3dd93b1418') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_