INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91978, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "在会议或集体场合上表达意见、看法。", "primary_collocate": null, "pronunciation": "fā yán", "ipa": "fa˥ jɛn˧˥", "syllable_count": 2, "sentences": [{"text": "开会时，王经理第一个站起来发言。", "target_word": "发言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请大家按顺序发言，不要随便打断别人。", "target_word": "发言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很紧张，轮到他发言时，手一直在发抖。", "target_word": "发言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小李在班会上发言，说了自己的想法。", "target_word": "发言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议开始前，主持人请代表们依次发言。", "target_word": "发言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她准备了很久，终于敢在大会上发言了。", "target_word": "发言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师鼓励我们在课堂讨论中积极发言。", "target_word": "发言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天的会上，你有什么想法就发言吧。", "target_word": "发言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他举手想发言，可是主持人没有看见。", "target_word": "发言", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会时每个人发言的时间只有三分钟。", "target_word": "发言", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "发过言", "label": "体标"}, {"form": "发了言", "label": "体标"}, {"form": "发言人", "label": "复合"}, {"form": "發言", "label": "繁体"}], "register": "中性", "sense_fingerprint": "在会议等集体场合表达意见", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '87287aec-525e-48a8-a475-07474285e1e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91978, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "发言", "is_correct": true, "explanation": "发言：在会上站起来表达意见，符合句意。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“睡觉”与“开会时站起来”的场合不符，句子荒谬。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：“游泳”需要水的场合，在会上站起来不成立。"}, {"text": "出差", "is_correct": false, "explanation": "配价：“出差”不能与“站起来”构成动作，且需要说明去向，句子不成立。"}], "explanations": {"发言": "发言：在会上站起来表达意见，符合句意。", "睡觉": "语义：“睡觉”与“开会时站起来”的场合不符，句子荒谬。", "游泳": "语义：“游泳”需要水的场合，在会上站起来不成立。", "出差": "配价：“出差”不能与“站起来”构成动作，且需要说明去向，句子不成立。"}, "sentence_index": 0, "correct_answer": "发言"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "小李在家里跟妈妈发言。", "explanation": "这里应该用〈说话〉。发言指在会议或集体场合表达意见，家里聊天要用说话。"}, {"text": "我们俩在咖啡馆里发言了很久。", "explanation": "这里应该用〈聊〉。发言指在会议或集体场合表达意见，两人闲聊要用聊。"}, {"text": "他在山上大声发言了三遍。", "explanation": "这里应该用〈喊〉。发言指有条理地表达意见，山上大声呼喊要用喊。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc2b2ba6-9230-4fbc-942c-da63e836e657') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91978, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "发言", "is_correct": true, "explanation": "发言：在课堂讨论中表达意见，符合句意。"}, {"text": "吃饭", "is_correct": false, "explanation": "语义：“吃饭”与课堂讨论无关，句子不通。"}, {"text": "跳舞", "is_correct": false, "explanation": "语义：“跳舞”与课堂讨论的语境不符。"}, {"text": "发愁", "is_correct": false, "explanation": "搭配：“积极”一般不修饰“发愁”这类消极状态。"}], "explanations": {"发言": "发言：在课堂讨论中表达意见，符合句意。", "吃饭": "语义：“吃饭”与课堂讨论无关，句子不通。", "跳舞": "语义：“跳舞”与课堂讨论的语境不符。", "发愁": "搭配：“积极”一般不修饰“发愁”这类消极状态。"}, "sentence_index": 6, "correct_answer": "发言"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈在厨房里发言了很久。", "explanation": "这里应该用〈唠叨〉。发言指在会议或集体场合表达意见，家里的啰嗦要用唠叨。"}, {"text": "他在电话里跟朋友发言了很久。", "explanation": "这里应该用〈抱怨〉。发言指在集体场合表达意见，私下抱怨要用抱怨。"}, {"text": "妹妹在床上发言了一下午。", "explanation": "这里应该用〈打盹〉。发言指在会议或集体场合表达意见，躺在床上小睡要用打盹。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc2b2ba6-9230-4fbc-942c-da63e836e657') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91978, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我明天要在会上发过言。", "corrected_sentence": "我明天要在会上发言。", "error_description": "经历体“过”用错。“过”表示已经经历过的动作，与“明天”的将来意思矛盾，应去掉“过”，写作“发言”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc2b2ba6-9230-4fbc-942c-da63e836e657') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91978, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他刚才在会上了发言。", "corrected_sentence": "他刚才在会上发了言。", "error_description": "体标“了”位置错误。“了”应放在“发”和“言”之间，写作“发了言”，“了发言”是错误的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc2b2ba6-9230-4fbc-942c-da63e836e657') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91983, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "满", "is_correct": true, "explanation": "反义：“满”指装得很多，与“空”指里面什么也没有相对。"}, {"text": "硬", "is_correct": false, "explanation": "无关：“硬”指不软，与“空”没有反义关系。"}, {"text": "圆", "is_correct": false, "explanation": "无关：“圆”指形状，与“空”没有反义关系。"}, {"text": "大", "is_correct": false, "explanation": "无关：“大”指体积或面积多，与“空”没有反义关系。"}], "correct_answer": "满", "explanations": {"满": "反义：“满”指装得很多，与“空”指里面什么也没有相对。", "硬": "无关：“硬”指不软，与“空”没有反义关系。", "圆": "无关：“圆”指形状，与“空”没有反义关系。", "大": "无关：“大”指体积或面积多，与“空”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f007e6e-add5-48b6-bbc7-edbd68d8d809') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91983, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "满", "is_correct": true, "explanation": "反义：“满”指装得很多，与“空”指里面什么也没有相对。"}, {"text": "慢", "is_correct": false, "explanation": "无关：“慢”指速度低，与“空”没有反义关系。"}, {"text": "深", "is_correct": false, "explanation": "无关：“深”指从表面到底部的距离大，与“空”没有反义关系。"}, {"text": "薄", "is_correct": false, "explanation": "无关：“薄”指厚度小，与“空”没有反义关系。"}], "correct_answer": "满", "explanations": {"满": "反义：“满”指装得很多，与“空”指里面什么也没有相对。", "慢": "无关：“慢”指速度低，与“空”没有反义关系。", "深": "无关：“深”指从表面到底部的距离大，与“空”没有反义关系。", "薄": "无关：“薄”指厚度小，与“空”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f007e6e-add5-48b6-bbc7-edbd68d8d809') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91983, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "空是里面什么也没有。", "primary_collocate": null, "pronunciation": "kōng", "ipa": "kʰʊŋ˥", "syllable_count": 1, "sentences": [{"text": "这个杯子空了，快倒点水吧。", "target_word": "空", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他回到家，发现屋子里是空的。", "target_word": "空", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们的冰箱几乎是空的。", "target_word": "空", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那只篮子是空的，没有苹果。", "target_word": "空", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那个纸箱是空的，我正好用来装书。", "target_word": "空", "complexity_tier": "T3", "furigana": "nà ge zhǐ xiāng shì kōng de, wǒ zhèng hǎo yòng lái zhuāng shū.", "sentence_source": "generated"}, {"text": "饮料喝完了，罐子空了。", "target_word": "空", "complexity_tier": "T3", "furigana": "yǐn liào hē wán le, guàn zi kōng le.", "sentence_source": "generated"}, {"text": "你的碗空了，我再给你盛一点。", "target_word": "空", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "书包是空的，他没带书。", "target_word": "空", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "抽屉打开后，里面是空的。", "target_word": "空", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个包裹寄走后，箱子就空了。", "target_word": "空", "complexity_tier": "T3", "furigana": "zhè ge bāo guǒ jì zǒu hòu, xiāng zi jiù kōng le.", "sentence_source": "generated"}], "morphological_forms": [{"form": "空空", "label": "重叠"}, {"form": "空了", "label": "体标"}, {"form": "空着", "label": "体标"}], "register": "中性", "sense_fingerprint": "空-形容词-里面什么也没有", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a375dcb8-ff9a-4a39-9db4-43a216043314') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91983, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "空", "is_correct": true, "explanation": "正确：空（kōng，第一声）表示里面什么也没有。"}, {"text": "控", "is_correct": false, "explanation": "kòng（第四声）与 kōng（第一声）声调不同，意思是控制。"}, {"text": "坑", "is_correct": false, "explanation": "kēng 与 kōng 韵母不同（-eng / -ong），意思是坑洞。"}, {"text": "公", "is_correct": false, "explanation": "gōng 与 kōng 声母不同（g / k），意思是公共。"}, {"text": "康", "is_correct": false, "explanation": "kāng 与 kōng 韵母不同（-ang / -ong），意思是健康。"}], "explanations": {"空": "正确：空（kōng，第一声）表示里面什么也没有。", "控": "kòng（第四声）与 kōng（第一声）声调不同，意思是控制。", "坑": "kēng 与 kōng 韵母不同（-eng / -ong），意思是坑洞。", "公": "gōng 与 kōng 声母不同（g / k），意思是公共。", "康": "kāng 与 kōng 韵母不同（-ang / -ong），意思是健康。"}, "sentence_index": null, "correct_answer": "空"}, "level_3": {"options": [{"text": "空", "is_correct": true, "explanation": "正确：空了表示杯中已没有水，所以需要再倒水。"}, {"text": "满", "is_correct": false, "explanation": "语义：“满了”说明杯子已装满，与“快倒点水吧”矛盾。"}, {"text": "瘦", "is_correct": false, "explanation": "搭配：“瘦”形容人或动物的体形，不能用来形容杯子。"}, {"text": "破", "is_correct": false, "explanation": "语义：“破了”说明杯子已经坏了、无法盛水，与“倒点水”矛盾。"}], "explanations": {"空": "正确：空了表示杯中已没有水，所以需要再倒水。", "满": "语义：“满了”说明杯子已装满，与“快倒点水吧”矛盾。", "瘦": "搭配：“瘦”形容人或动物的体形，不能用来形容杯子。", "破": "语义：“破了”说明杯子已经坏了、无法盛水，与“倒点水”矛盾。"}, "sentence_index": 0, "correct_answer": "空"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个仓库的空很大，能堆很多货。", "explanation": "这里应该用〈空间〉，表示地方的大小；“空”单用不指空间。"}, {"text": "他对着空挥了挥手，像是在告别。", "explanation": "这里的“空”指天空、空中，是另一个义项（如“领空”“对空”），与“里面没有东西”无关。"}, {"text": "他空跑了一趟，什么也没办成。", "explanation": "这里的“空”是副词，表示白白地、徒劳地，是另一个义项，与“里面没有东西”无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f007e6e-add5-48b6-bbc7-edbd68d8d809') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91983, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "空", "is_correct": true, "explanation": "正确：空（kōng，第一声）表示里面什么也没有。"}, {"text": "孔", "is_correct": false, "explanation": "kǒng（第三声）与 kōng（第一声）声调不同，意思是孔洞。"}, {"text": "工", "is_correct": false, "explanation": "gōng 与 kōng 声母不同（g / k），意思是工作。"}, {"text": "烘", "is_correct": false, "explanation": "hōng 与 kōng 声母不同（h / k），意思是烘干。"}, {"text": "通", "is_correct": false, "explanation": "tōng 与 kōng 声母不同（t / k），意思是通过。"}], "explanations": {"空": "正确：空（kōng，第一声）表示里面什么也没有。", "孔": "kǒng（第三声）与 kōng（第一声）声调不同，意思是孔洞。", "工": "gōng 与 kōng 声母不同（g / k），意思是工作。", "烘": "hōng 与 kōng 声母不同（h / k），意思是烘干。", "通": "tōng 与 kōng 声母不同（t / k），意思是通过。"}, "sentence_index": null, "correct_answer": "空"}, "level_3": {"options": [{"text": "空", "is_correct": true, "explanation": "正确：空了表示碗里已没有饭，所以需要再盛。"}, {"text": "饱", "is_correct": false, "explanation": "搭配：“饱”用于人或动物吃饱，不能用来形容碗。"}, {"text": "胖", "is_correct": false, "explanation": "体貌：“胖”形容人或动物的体形，不能用来形容碗。"}, {"text": "重", "is_correct": false, "explanation": "语义：“重了”说明碗里已装得沉，与“再给你盛一点”矛盾。"}], "explanations": {"空": "正确：空了表示碗里已没有饭，所以需要再盛。", "饱": "搭配：“饱”用于人或动物吃饱，不能用来形容碗。", "胖": "体貌：“胖”形容人或动物的体形，不能用来形容碗。", "重": "语义：“重了”说明碗里已装得沉，与“再给你盛一点”矛盾。"}, "sentence_index": 6, "correct_answer": "空"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的建议空得很，句句都说到点子上。", "explanation": "这里的“空”表示没有内容，与“句句都说到点子上”矛盾；应用〈实〉表示有内容。"}, {"text": "这份报告他空改了一下午，最后还是白忙一场。", "explanation": "这里的“空”是副词，表示白白地、徒劳地（如“空跑”“空忙”），是另一个义项，与“里面没有东西”无关。"}, {"text": "他对空讲了好久，没有一个人听。", "explanation": "这里的“对空”指朝着空中、空气，是另一个义项，与“里面没有东西”无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f007e6e-add5-48b6-bbc7-edbd68d8d809') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91983, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈把冰箱里的剩菜空了，正好可以放新的。", "corrected_sentence": "妈妈把冰箱里的剩菜吃空了，正好可以放新的。", "error_description": "错误：“把剩菜空了”缺少结果补语“吃”。应说“吃空了”，“空”作结果补语要与“吃”这类动作动词连用，表示把东西吃到没有。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f007e6e-add5-48b6-bbc7-edbd68d8d809') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91983, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那个纸箱是空，你可以拿去用。", "corrected_sentence": "那个纸箱是空的，你可以拿去用。", "error_description": "错误：“是空”缺少“的”。“是”后面作谓语的形容词要带“的”，应说“是空的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f007e6e-add5-48b6-bbc7-edbd68d8d809') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
