INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91993, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea50f9b6-3a44-4278-abbe-9c85b78917e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91993, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "很多人一起去，请大官答应一件事。", "primary_collocate": null, "pronunciation": "qǐng yuàn", "ipa": "tɕʰiŋ˨˩˦ ɥɛn˥˩", "syllable_count": 2, "sentences": [{"text": "很多人一起去市长家门口请愿。", "target_word": "请愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里人去找县长请愿，想要一条路。", "target_word": "请愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家决定明天去政府请愿。", "target_word": "请愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们请愿，请市长让孩子上好学校。", "target_word": "请愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们一起请愿，想多拿一点钱。", "target_word": "请愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老百姓请愿，希望官员答应他们的要求。", "target_word": "请愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们昨天去请愿了，今天还在等回答。", "target_word": "请愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去请愿的人排了很长的队。", "target_word": "请愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们为什么要去请愿？因为水很脏。", "target_word": "请愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村民们到县政府请愿，要求修学校。", "target_word": "请愿", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "请愿了", "label": "体标"}, {"form": "请愿过", "label": "体标"}, {"form": "请愿书", "label": "复合"}, {"form": "请愿者", "label": "复合"}], "register": "中性", "sense_fingerprint": "许多人一起去找官员，请他答应一个要求", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75fd202e-20bb-4aa3-a2f5-79e25091db51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91993, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "请愿", "is_correct": true, "explanation": "“请愿”指很多人一起去，请有关的大官答应一件事。"}, {"text": "情愿", "is_correct": false, "explanation": "qíng（第二声）与 qǐng（第三声）声调不同，意思是心甘情愿。"}, {"text": "情缘", "is_correct": false, "explanation": "两个音节的声调都不同（qíng 与 qǐng，yuán 与 yuàn），意思是感情上的缘分。"}, {"text": "请援", "is_correct": false, "explanation": "yuán（第二声）与 yuàn（第四声）声调不同，意思是请求援助。"}, {"text": "亲缘", "is_correct": false, "explanation": "qīn（第一声）与 qǐng（第三声）韵母不同（n 与 ng），yuán 与 yuàn 声调不同，意思是血缘关系。"}], "explanations": {"请愿": "“请愿”指很多人一起去，请有关的大官答应一件事。", "情愿": "qíng（第二声）与 qǐng（第三声）声调不同，意思是心甘情愿。", "情缘": "两个音节的声调都不同（qíng 与 qǐng，yuán 与 yuàn），意思是感情上的缘分。", "请援": "yuán（第二声）与 yuàn（第四声）声调不同，意思是请求援助。", "亲缘": "qīn（第一声）与 qǐng（第三声）韵母不同（n 与 ng），yuán 与 yuàn 声调不同，意思是血缘关系。"}, "sentence_index": null, "correct_answer": "请愿"}, "level_3": {"options": [{"text": "请愿", "is_correct": true, "explanation": "这里要用“请愿”：很多人一起去，请市长答应一件事，与句意一致。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：“游泳”与请求无关，市长家门口不适合游泳，句子说不通。"}, {"text": "发呆", "is_correct": false, "explanation": "语义：“发呆”是呆坐不动，与一起去请求的行为不符。"}, {"text": "举办", "is_correct": false, "explanation": "配价：“举办”需要宾语，如“举办活动”，此处不能只说“去市长家门口举办”。"}], "explanations": {"请愿": "这里要用“请愿”：很多人一起去，请市长答应一件事，与句意一致。", "游泳": "语义：“游泳”与请求无关，市长家门口不适合游泳，句子说不通。", "发呆": "语义：“发呆”是呆坐不动，与一起去请求的行为不符。", "举办": "配价：“举办”需要宾语，如“举办活动”，此处不能只说“去市长家门口举办”。"}, "sentence_index": 0, "correct_answer": "请愿"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他向同事请愿，请对方帮忙换班。", "explanation": "这里应该用〈请求〉。请愿指群众集体向政府或有关机构提出请求；个人向同事提出请求要用“请求”。"}, {"text": "我迷路了，向路人请愿帮忙。", "explanation": "这里应该用〈求助〉。请愿用于群众向政府集体请求；向陌生人请求帮忙要用“求助”。"}, {"text": "他替弟弟向爸爸请愿，求爸爸别生气。", "explanation": "这里应该用〈求情〉。请愿是集体向政府提出要求；替人向长辈为别人说情要用“求情”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea50f9b6-3a44-4278-abbe-9c85b78917e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91993, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "请愿", "is_correct": true, "explanation": "这里要用“请愿”：去有关部门提出请求，与后文“还在等回答”相呼应。"}, {"text": "旅游", "is_correct": false, "explanation": "语义：“旅游”不是提出请求，与“还在等回答”对不上。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：“唱歌”与等待回答无关，句子意思不通。"}, {"text": "出差", "is_correct": false, "explanation": "搭配：“出差”指因工作外出，学生不适用，与后文也对不上。"}], "explanations": {"请愿": "这里要用“请愿”：去有关部门提出请求，与后文“还在等回答”相呼应。", "旅游": "语义：“旅游”不是提出请求，与“还在等回答”对不上。", "唱歌": "语义：“唱歌”与等待回答无关，句子意思不通。", "出差": "搭配：“出差”指因工作外出，学生不适用，与后文也对不上。"}, "sentence_index": 6, "correct_answer": "请愿"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老板请愿员工准时上班。", "explanation": "这里应该用〈呼吁〉。请愿是向政府或机构提出请求，不用于对员工发出号召；号召员工要用呼吁。"}, {"text": "她向银行请愿贷款，希望能买一套房子。", "explanation": "这里应该用〈申请〉。请愿指群众集体请求；个人向银行争取贷款要用申请。"}, {"text": "我向朋友请愿借一本书。", "explanation": "这里应该用〈恳求〉。请愿不用于朋友之间的私人请托；请朋友帮忙要用恳求。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea50f9b6-3a44-4278-abbe-9c85b78917e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91993, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "村民们向县长请愿了一个，希望修一座桥。", "corrected_sentence": "村民们向县长请愿了一次，希望修一座桥。", "error_description": "错误形式：请愿了一个；正确形式：请愿了一次。“请愿”是动作，计量时要用动量词“次”，不能用量词“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea50f9b6-3a44-4278-abbe-9c85b78917e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91993, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "居民们向政府请愿了一个，要求修好电梯。", "corrected_sentence": "居民们向政府请愿了一次，要求修好电梯。", "error_description": "错误形式：请愿了一个；正确形式：请愿了一次。“请愿”是动作，计量时要用动量词“次”，不能用量词“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea50f9b6-3a44-4278-abbe-9c85b78917e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
