INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91994, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "群众向政府或有关机构提出请求，要求予以答应。", "primary_collocate": null, "pronunciation": "qǐng yuàn", "ipa": "tɕʰiŋ˨˩˦ ɥɛn˥˩", "syllable_count": 2, "sentences": [{"text": "市民们到市政府门口请愿，要求修一条新路。", "target_word": "请愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们聚在一起，向政府请愿，希望提高工资。", "target_word": "请愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村民们去县里请愿，要求政府解决污水问题。", "target_word": "请愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们在广场上请愿，希望学校降低学费。", "target_word": "请愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "居民们联名请愿，不想在小区旁边建工厂。", "target_word": "请愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民们每年都会去省政府请愿。", "target_word": "请愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们已经请愿三次了，政府还没有回答。", "target_word": "请愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司机们为了保护自己的工作，一起去请愿。", "target_word": "请愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请愿的人很多，广场上站满了人。", "target_word": "请愿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人们请愿，希望政府多建几个公园。", "target_word": "请愿", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "请愿了", "label": "体标"}, {"form": "请愿过", "label": "体标"}, {"form": "请愿书", "label": "复合"}, {"form": "请愿者", "label": "复合"}], "register": "中性", "sense_fingerprint": "群众向政府或机构正式提出请求", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75fd202e-20bb-4aa3-a2f5-79e25091db51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91994, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "请愿", "is_correct": true, "explanation": "“请愿”指群众向政府或有关机构集体提出请求，要求答应。"}, {"text": "情愿", "is_correct": false, "explanation": "qíng（第二声）与 qǐng（第三声）声调不同，意思是心甘情愿。"}, {"text": "情缘", "is_correct": false, "explanation": "两个音节的声调都不同（qíng 与 qǐng，yuán 与 yuàn），意思是感情上的缘分。"}, {"text": "请援", "is_correct": false, "explanation": "yuán（第二声）与 yuàn（第四声）声调不同，意思是请求援助。"}, {"text": "亲缘", "is_correct": false, "explanation": "qīn（第一声）与 qǐng（第三声）韵母不同（n 与 ng），yuán 与 yuàn 声调不同，意思是血缘关系。"}], "explanations": {"请愿": "“请愿”指群众向政府或有关机构集体提出请求，要求答应。", "情愿": "qíng（第二声）与 qǐng（第三声）声调不同，意思是心甘情愿。", "情缘": "两个音节的声调都不同（qíng 与 qǐng，yuán 与 yuàn），意思是感情上的缘分。", "请援": "yuán（第二声）与 yuàn（第四声）声调不同，意思是请求援助。", "亲缘": "qīn（第一声）与 qǐng（第三声）韵母不同（n 与 ng），yuán 与 yuàn 声调不同，意思是血缘关系。"}, "sentence_index": null, "correct_answer": "请愿"}, "level_3": {"options": [{"text": "请愿", "is_correct": true, "explanation": "这里要用“请愿”：群众到政府门口集体提出要求，正好接“要求修一条新路”。"}, {"text": "散步", "is_correct": false, "explanation": "语义：“散步”不表示向政府提出要求，与后文“要求修路”矛盾。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“睡觉”与“要求修路”没有关系，句子说不通。"}, {"text": "举办", "is_correct": false, "explanation": "配价：“举办”需要宾语，如“举办活动”，此处没有宾语，不能只说“到门口举办”。"}], "explanations": {"请愿": "这里要用“请愿”：群众到政府门口集体提出要求，正好接“要求修一条新路”。", "散步": "语义：“散步”不表示向政府提出要求，与后文“要求修路”矛盾。", "睡觉": "语义：“睡觉”与“要求修路”没有关系，句子说不通。", "举办": "配价：“举办”需要宾语，如“举办活动”，此处没有宾语，不能只说“到门口举办”。"}, "sentence_index": 0, "correct_answer": "请愿"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他向老师请愿，希望能延长一周的作业时间。", "explanation": "这里应该用〈请求〉。请愿指群众集体向政府或有关机构提出请求；个人向老师提出请求要用“请求”。"}, {"text": "他遇到困难，向朋友请愿帮忙。", "explanation": "这里应该用〈求助〉。请愿用于群众向政府集体请求；朋友之间请对方帮忙要用“求助”。"}, {"text": "他替朋友向法官请愿，希望从轻处罚。", "explanation": "这里应该用〈求情〉。请愿是集体向政府提出要求；替人向法官为别人说情要用“求情”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea50f9b6-3a44-4278-abbe-9c85b78917e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91994, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "请愿", "is_correct": true, "explanation": "这里要用“请愿”：他们多次向政府提出要求，与“政府还没有回答”相呼应。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：“游泳”与向政府提要求无关，后文“政府还没回答”也对不上。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：“唱歌”不是向政府提出请求，句子意思不通。"}, {"text": "点菜", "is_correct": false, "explanation": "搭配：“点菜”是餐馆里的点餐动作，不能与“政府还没有回答”搭配。"}], "explanations": {"请愿": "这里要用“请愿”：他们多次向政府提出要求，与“政府还没有回答”相呼应。", "游泳": "语义：“游泳”与向政府提要求无关，后文“政府还没回答”也对不上。", "唱歌": "语义：“唱歌”不是向政府提出请求，句子意思不通。", "点菜": "搭配：“点菜”是餐馆里的点餐动作，不能与“政府还没有回答”搭配。"}, "sentence_index": 6, "correct_answer": "请愿"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师请愿大家按时交作业。", "explanation": "这里应该用〈呼吁〉。请愿是向政府或机构提出请求，不用于对大家发出号召；号召大家要用呼吁。"}, {"text": "他向学校请愿奖学金，希望能减轻家里的负担。", "explanation": "这里应该用〈申请〉。请愿指群众集体请求；个人为自己争取奖学金要用申请。"}, {"text": "我向妈妈请愿多给点零花钱。", "explanation": "这里应该用〈恳求〉。请愿不用于家人之间的私人请托；请家人答应要用恳求。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea50f9b6-3a44-4278-abbe-9c85b78917e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91994, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "市民们向市政府请愿了一个，要求修路灯。", "corrected_sentence": "市民们向市政府请愿了一次，要求修路灯。", "error_description": "错误形式：请愿了一个；正确形式：请愿了一次。“请愿”是动作，计量时要用动量词“次”，不能用量词“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea50f9b6-3a44-4278-abbe-9c85b78917e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91994, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们向政府请愿了一个，要求政府回应。", "corrected_sentence": "他们向政府请愿了一次，要求政府回应。", "error_description": "错误形式：请愿了一个；正确形式：请愿了一次。“请愿”是动作，计量时要用动量词“次”，不能用量词“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea50f9b6-3a44-4278-abbe-9c85b78917e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
