INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92000, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "连续使用；接连使用。", "primary_collocate": null, "pronunciation": "lián yòng", "ipa": "ljɛn˧˥ jʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这个药不能连用三天以上。", "target_word": "连用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他连用了三个比喻来说明。", "target_word": "连用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台机器连用十个小时就会很热。", "target_word": "连用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作者在文章里连用几个“啊”。", "target_word": "连用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机连用一整天，电池就没电了。", "target_word": "连用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种眼药水不要连用太久。", "target_word": "连用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一支笔连用两年，他还不想换。", "target_word": "连用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个软件连用一个月，就要付钱。", "target_word": "连用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在演讲里连用了几个问句。", "target_word": "连用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "空调连用一晚上，电费会很高。", "target_word": "连用", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "连用了", "label": "体标"}], "register": "中性", "sense_fingerprint": "连用：一段时间内不间断地使用，或接连使用多次", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '010817e2-98c0-49e8-8874-0f3dd93b1418') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92000, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "连用", "is_correct": true, "explanation": "正确：“连用”表示连续使用，与“三天以上”搭配。"}, {"text": "跑步", "is_correct": false, "explanation": "语义：“跑步”与用药无关，句意不通。"}, {"text": "唱歌", "is_correct": false, "explanation": "搭配：“唱歌”不能与“药”搭配。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“睡觉”与用药无关，句意不通。"}], "explanations": {"连用": "正确：“连用”表示连续使用，与“三天以上”搭配。", "跑步": "语义：“跑步”与用药无关，句意不通。", "唱歌": "搭配：“唱歌”不能与“药”搭配。", "睡觉": "语义：“睡觉”与用药无关，句意不通。"}, "sentence_index": 0, "correct_answer": "连用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "“很”和“太”连用，语气更重。", "explanation": "这里的“连用”指两个词紧挨着一起用，是另一个义项，与本词“连续使用”的意思不同。"}, {"text": "这两个词连用了三遍。", "explanation": "这里的“连用”指两个词紧挨着用，是另一个义项，与本词“连续使用某物”的意思不同。"}, {"text": "“吗”和“呢”连用，语气很重。", "explanation": "这里的“连用”指两个词紧挨着一起用，是另一个义项，与本词“连续使用”的意思不同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bc8d629-ae1c-4edc-ba37-b7f4bba02d3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92000, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "连用", "is_correct": true, "explanation": "正确：“连用”表示连续使用两年，与“两年”搭配。"}, {"text": "生病", "is_correct": false, "explanation": "语义：“生病”的主体是人或动物，笔不会生病。"}, {"text": "发烧", "is_correct": false, "explanation": "语义：“发烧”与笔无关，句意不通。"}, {"text": "失业", "is_correct": false, "explanation": "配价：“失业”的主语只能是人，不能说笔失业。"}], "explanations": {"连用": "正确：“连用”表示连续使用两年，与“两年”搭配。", "生病": "语义：“生病”的主体是人或动物，笔不会生病。", "发烧": "语义：“发烧”与笔无关，句意不通。", "失业": "配价：“失业”的主语只能是人，不能说笔失业。"}, "sentence_index": 6, "correct_answer": "连用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "“的”和“地”连用，句子会很别扭。", "explanation": "这里的“连用”指两个词紧挨着一起用，是另一个义项，与本词“连续使用”的意思不同。"}, {"text": "“也”和“都”连用，意思会变。", "explanation": "这里的“连用”指两个词紧挨着一起用，是另一个义项，与本词“连续使用”的意思不同。"}, {"text": "“就”和“才”连用，语气很怪。", "explanation": "这里的“连用”指两个词紧挨着一起用，是另一个义项，与本词“连续使用”的意思不同。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bc8d629-ae1c-4edc-ba37-b7f4bba02d3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92000, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这盏灯把连用一晚上就会热。", "corrected_sentence": "这盏灯连用一晚上就会热。", "error_description": "错误形式：“把连用一晚上”。正确形式：“连用一晚上”。原因：“把”字后须带受事宾语，“连用”后接的是时段，不能用“把”引出，多出的“把”应删去。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bc8d629-ae1c-4edc-ba37-b7f4bba02d3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92000, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台冰箱连用得一个星期就会坏。", "corrected_sentence": "这台冰箱连用一个星期就会坏。", "error_description": "错误形式：“连用得一个星期”。正确形式：“连用一个星期”。原因：“连用”后直接接时段补语，不能加“得”，多出的“得”应删去。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bc8d629-ae1c-4edc-ba37-b7f4bba02d3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
