INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92013, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "被迫是你不想做，可是别人让你一定要做。", "primary_collocate": null, "pronunciation": "bèi pò", "ipa": "pei˥˩ pʰo˥˩", "syllable_count": 2, "sentences": [{"text": "我不想去，可是妈妈让我去，我被迫去了。", "target_word": "被迫", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不喜欢唱歌，今天被迫唱了一首。", "target_word": "被迫", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板要我加班，我被迫留了下来。", "target_word": "被迫", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟不爱吃菜，妈妈说一定要吃，他被迫吃了几口。", "target_word": "被迫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不喜欢跑步，老师让我跑，我被迫跑了。", "target_word": "被迫", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她不想结婚，家里人一直说，她被迫同意了。", "target_word": "被迫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不想道歉，可是大家都看着他，他被迫说了对不起。", "target_word": "被迫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不想借钱给他，他一直问，我被迫答应了。", "target_word": "被迫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子不想学琴，爸爸一定要他练，他被迫坐到钢琴前。", "target_word": "被迫", "complexity_tier": "T3", "furigana": "hái zi bù xiǎng xué qín, bà ba yí dìng yào tā liàn, tā bèi pò zuò dào gāng qín qián.", "sentence_source": "generated"}, {"text": "同学们不想打扫，老师说必须做，大家被迫动手。", "target_word": "被迫", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "自己不想做，但别人要求一定要做", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d8816a-ffa1-49a0-9ada-6b37d3a396e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92013, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "被迫", "is_correct": true, "explanation": "被迫（bèi pò）：自己不想做，却被别人要求一定要做。"}, {"text": "北坡", "is_correct": false, "explanation": "北坡（běi pō）与被迫（bèi pò）第一个音节声调不同（第三声与第四声），意思是山的北面。"}, {"text": "被派", "is_correct": false, "explanation": "被派（bèi pài）与被迫（bèi pò）第二个音节韵母不同（ai 与 o），意思是被派遣。"}, {"text": "被泡", "is_correct": false, "explanation": "被泡（bèi pào）与被迫（bèi pò）第二个音节韵母不同（ao 与 o），意思是被水浸泡。"}], "explanations": {"被迫": "被迫（bèi pò）：自己不想做，却被别人要求一定要做。", "北坡": "北坡（běi pō）与被迫（bèi pò）第一个音节声调不同（第三声与第四声），意思是山的北面。", "被派": "被派（bèi pài）与被迫（bèi pò）第二个音节韵母不同（ai 与 o），意思是被派遣。", "被泡": "被泡（bèi pào）与被迫（bèi pò）第二个音节韵母不同（ao 与 o），意思是被水浸泡。"}, "sentence_index": null, "correct_answer": "被迫"}, "level_3": {"options": [{"text": "被迫", "is_correct": true, "explanation": "被迫：我不想去，但妈妈要求去，符合“不愿意却不得不做”的意思。"}, {"text": "乐意", "is_correct": false, "explanation": "语义：“乐意”表示愿意，与“我不想去”矛盾。"}, {"text": "自愿", "is_correct": false, "explanation": "语义：“自愿”表示出于本意，与“我不想去”矛盾。"}, {"text": "允许", "is_correct": false, "explanation": "配价：“允许”需要允许者，“我”不能允许自己去。"}], "explanations": {"被迫": "被迫：我不想去，但妈妈要求去，符合“不愿意却不得不做”的意思。", "乐意": "语义：“乐意”表示愿意，与“我不想去”矛盾。", "自愿": "语义：“自愿”表示出于本意，与“我不想去”矛盾。", "允许": "配价：“允许”需要允许者，“我”不能允许自己去。"}, "sentence_index": 0, "correct_answer": "被迫"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "弟弟不爱吃菜，妈妈说一定要吃，他被迫自愿吃了几口。", "explanation": "这里〈被迫〉用错了：被迫表示不得不做、并非本愿，与出于本愿、情愿去做的意思相反，不能用来修饰同一个动作。"}, {"text": "弟弟不爱吃菜，妈妈说一定要吃，他被迫主动吃了几口。", "explanation": "这里〈被迫〉用错了：被迫表示吃是不得已，与自发、积极去做的态度相反，不能用来修饰同一个动作。"}, {"text": "弟弟不爱吃菜，妈妈说一定要吃，他被迫吃了几口，这是他自己的主意。", "explanation": "这里〈被迫〉用错了：被迫表示勉强、并非出于本意，与“这是他自己的主意”相反，不能用来修饰同一个动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b844e9bd-cc6b-467a-85db-712830f152f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92013, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "被迫", "is_correct": true, "explanation": "被迫：大家都看着他，他不得不说对不起，符合句意。"}, {"text": "乐于", "is_correct": false, "explanation": "语义：“乐于”表示乐意，与“他不想道歉”矛盾。"}, {"text": "愿意", "is_correct": false, "explanation": "语义：“愿意”表示乐意，与“他不想道歉”矛盾。"}, {"text": "习惯", "is_correct": false, "explanation": "语义：“习惯”表示平日惯常如此，与“他不想道歉”“被迫”的情境矛盾。"}], "explanations": {"被迫": "被迫：大家都看着他，他不得不说对不起，符合句意。", "乐于": "语义：“乐于”表示乐意，与“他不想道歉”矛盾。", "愿意": "语义：“愿意”表示乐意，与“他不想道歉”矛盾。", "习惯": "语义：“习惯”表示平日惯常如此，与“他不想道歉”“被迫”的情境矛盾。"}, "sentence_index": 6, "correct_answer": "被迫"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "同学们不想打扫，大家被迫都抢着动手。", "explanation": "这里〈被迫〉用错了：被迫表示不情愿、受压而做，却接着描述争先恐后的积极态度，两者意思相反。"}, {"text": "同学们不想打扫，大家被迫很喜欢动手。", "explanation": "这里〈被迫〉用错了：被迫表示勉强、不情愿，与发自内心的喜爱相反，不能说被迫却同时表示喜爱。"}, {"text": "同学们不想打扫，大家被迫积极主动地动手。", "explanation": "这里〈被迫〉用错了：被迫表示出于无奈、并非本意，却接着描述出于自身热情、自发去做的态度，前后意思相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b844e9bd-cc6b-467a-85db-712830f152f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92013, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大家不想去，却被迫了排队。", "corrected_sentence": "大家不想去，却被迫排了队。", "error_description": "错误：“了”放在“被迫”后面，变成“被迫了排队”。正确应为“被迫排了队”，“了”放在动词后表示完成。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b844e9bd-cc6b-467a-85db-712830f152f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92013, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他不愿意搬家，可是房东一直催，他被被迫搬走了。", "corrected_sentence": "他不愿意搬家，可是房东一直催，他被迫搬走了。", "error_description": "错误：多写了一个“被”。被迫本身已含被动意思，前面不能再加“被”。正确应为“他被迫搬走了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b844e9bd-cc6b-467a-85db-712830f152f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
