INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92014, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "被外力或形势所逼而不得不做某事。", "primary_collocate": null, "pronunciation": "bèi pò", "ipa": "pei˥˩ pʰo˥˩", "syllable_count": 2, "sentences": [{"text": "因为下大雨，比赛被迫停止。", "target_word": "被迫", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司没有钱，被迫关门了。", "target_word": "被迫", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "因为生病，他被迫离开了学校。", "target_word": "被迫", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "路上堵得太厉害，我们被迫下车走路。", "target_word": "被迫", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工厂太旧，老板被迫卖掉了它。", "target_word": "被迫", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "因为工作不好找，他被迫回了老家。", "target_word": "被迫", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大雪封了山，游客被迫留在山下。", "target_word": "被迫", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "价格越来越高，商店被迫少进货。", "target_word": "被迫", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "飞机晚点，我们被迫在机场过夜。", "target_word": "被迫", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "家里没钱，哥哥被迫放弃了学习。", "target_word": "被迫", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "受外力或形势所逼而不得不做", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d8816a-ffa1-49a0-9ada-6b37d3a396e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92014, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "被迫", "is_correct": true, "explanation": "被迫（bèi pò）：被外力所逼而不得不做某事。"}, {"text": "北坡", "is_correct": false, "explanation": "北坡（běi pō）与被迫（bèi pò）第一个音节声调不同（第三声与第四声），意思是山的北面。"}, {"text": "被派", "is_correct": false, "explanation": "被派（bèi pài）与被迫（bèi pò）第二个音节韵母不同（ai 与 o），意思是被派遣。"}, {"text": "被泡", "is_correct": false, "explanation": "被泡（bèi pào）与被迫（bèi pò）第二个音节韵母不同（ao 与 o），意思是被水浸泡。"}], "explanations": {"被迫": "被迫（bèi pò）：被外力所逼而不得不做某事。", "北坡": "北坡（běi pō）与被迫（bèi pò）第一个音节声调不同（第三声与第四声），意思是山的北面。", "被派": "被派（bèi pài）与被迫（bèi pò）第二个音节韵母不同（ai 与 o），意思是被派遣。", "被泡": "被泡（bèi pào）与被迫（bèi pò）第二个音节韵母不同（ao 与 o），意思是被水浸泡。"}, "sentence_index": null, "correct_answer": "被迫"}, "level_3": {"options": [{"text": "被迫", "is_correct": true, "explanation": "被迫：因下大雨这一外力，比赛不得不停止，与句意相符。"}, {"text": "自愿", "is_correct": false, "explanation": "语义：“自愿”表示出于本意，与“因为下大雨”的外力矛盾。"}, {"text": "愿意", "is_correct": false, "explanation": "语义：“愿意”表示乐意，与“因为下大雨”的外力不符。"}, {"text": "拒绝", "is_correct": false, "explanation": "配价：“拒绝”需要有意志的施事，比赛不能拒绝停止。"}], "explanations": {"被迫": "被迫：因下大雨这一外力，比赛不得不停止，与句意相符。", "自愿": "语义：“自愿”表示出于本意，与“因为下大雨”的外力矛盾。", "愿意": "语义：“愿意”表示乐意，与“因为下大雨”的外力不符。", "拒绝": "配价：“拒绝”需要有意志的施事，比赛不能拒绝停止。"}, "sentence_index": 0, "correct_answer": "被迫"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "路上堵得太厉害，我们被迫自愿下车走路。", "explanation": "这里〈被迫〉用错了：被迫表示并非出于本愿而不得不做，与出于本愿、情愿去做的意思相反，不能用来修饰同一个动作。"}, {"text": "路上堵得太厉害，我们被迫主动下车走路。", "explanation": "这里〈被迫〉用错了：被迫表示不是出于本意的不得已，与自发、积极去做的态度相反，不能用来修饰同一个动作。"}, {"text": "路上堵得太厉害，我们被迫下车走路，这是我们自己的主意。", "explanation": "这里〈被迫〉用错了：被迫表示受外力所逼、并非本意，与“自己的主意”相反，不能用来修饰同一个动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b844e9bd-cc6b-467a-85db-712830f152f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92014, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "被迫", "is_correct": true, "explanation": "被迫：大雪封山，游客不得不留在山下，符合句意。"}, {"text": "允许", "is_correct": false, "explanation": "配价：“允许”需要允许者和被允许的人，游客不能允许自己留下。"}, {"text": "主动", "is_correct": false, "explanation": "语义：“主动”表示出于自身意愿，与“大雪封了山”的外力处境矛盾。"}, {"text": "乐于", "is_correct": false, "explanation": "语义：“乐于”表示乐意，与“大雪封了山”的外力处境矛盾。"}], "explanations": {"被迫": "被迫：大雪封山，游客不得不留在山下，符合句意。", "允许": "配价：“允许”需要允许者和被允许的人，游客不能允许自己留下。", "主动": "语义：“主动”表示出于自身意愿，与“大雪封了山”的外力处境矛盾。", "乐于": "语义：“乐于”表示乐意，与“大雪封了山”的外力处境矛盾。"}, "sentence_index": 6, "correct_answer": "被迫"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "家里没钱，哥哥被迫心甘情愿放弃了学习。", "explanation": "这里〈被迫〉用错了：被迫表示受外力所逼、并非本愿，与出于本愿的情愿态度相反，不能用来修饰同一个行为。"}, {"text": "哥哥被迫放弃了学习，因为他一心想去国外深造。", "explanation": "这里〈被迫〉用错了：被迫的原因必须是外力或形势，而这里的原因是本人的强烈愿望，两者不相符。"}, {"text": "哥哥被迫放弃了学习，这是他自己主动要求的。", "explanation": "这里〈被迫〉用错了：被迫表示出于无奈、受外力所逼，与“自己主动要求”的意愿相反，两者不能用来修饰同一件事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b844e9bd-cc6b-467a-85db-712830f152f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92014, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "因为公司亏钱，他被迫卖掉着房子。", "corrected_sentence": "因为公司亏钱，他被迫卖掉了房子。", "error_description": "错误：“卖掉”后面应用“了”表示动作完成，这里写成了“着”。正确应说“他被迫卖掉了房子”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b844e9bd-cc6b-467a-85db-712830f152f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92014, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "由于天气很冷，我们被被迫留在家里。", "corrected_sentence": "由于天气很冷，我们被迫留在家里。", "error_description": "错误：多写了一个“被”。被迫本身已含被动意思，前面不能再加“被”。正确应为“我们被迫留在家里”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b844e9bd-cc6b-467a-85db-712830f152f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
