INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92039, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '016eec18-bb05-45a9-b2ba-daff39320fe3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92039, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "事情做完了以后。", "primary_collocate": null, "pronunciation": "guò hòu", "ipa": "kwo⁵¹ xoʊ⁵¹", "syllable_count": 2, "sentences": [{"text": "暴雨过后，空气变得很清新。", "target_word": "过后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "考试过后，同学们都去玩了。", "target_word": "过后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "吵架过后，他们谁也没说话。", "target_word": "过后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "节日过后，街上又安静了。", "target_word": "过后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛过后，球员们互相拥抱。", "target_word": "过后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大扫除过后，教室变得干干净净。", "target_word": "过后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "搬家过后，她花了一周整理东西。", "target_word": "过后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地震过后，大家一起重建了村子。", "target_word": "过后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "手术过后，病人需要好好休息。", "target_word": "过后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "演出过后，观众慢慢走出了剧场。", "target_word": "过后", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "过后-某件事结束以后", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9582f388-ac0e-48fb-946b-de35c9fd115a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92039, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "首先", "is_correct": false, "explanation": "语义：“首先”表示开始、第一步，与“暴雨停止之后”的时间关系不合。"}, {"text": "始终", "is_correct": false, "explanation": "语义：“始终”表示一直持续，与“暴雨之后”这个时间点的含义矛盾。"}, {"text": "过后", "is_correct": true, "explanation": "正确：“过后”表示暴雨之后，与“空气变得很清新”的因果语境相符。"}, {"text": "偶尔", "is_correct": false, "explanation": "搭配：“偶尔”修饰动作的频率，不能用来修饰“暴雨”这样的事件。"}], "explanations": {"首先": "语义：“首先”表示开始、第一步，与“暴雨停止之后”的时间关系不合。", "始终": "语义：“始终”表示一直持续，与“暴雨之后”这个时间点的含义矛盾。", "过后": "正确：“过后”表示暴雨之后，与“空气变得很清新”的因果语境相符。", "偶尔": "搭配：“偶尔”修饰动作的频率，不能用来修饰“暴雨”这样的事件。"}, "sentence_index": 0, "correct_answer": "过后"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一边看书，过后一边听音乐。", "explanation": "这里应该用〈同时〉。过后表示事情做完之后，不能表示两件事同时进行。"}, {"text": "现在过后，我们马上开始工作。", "explanation": "这里应该用〈以后〉。过后要接事情做完之后的情况，不能指“现在”这样的当下时点。"}, {"text": "他还没做完作业，过后就去玩了。", "explanation": "这里应该用〈完成之后〉。过后要求前面的事情已经结束，作业还没完成时不能用过后。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '016eec18-bb05-45a9-b2ba-daff39320fe3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92039, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "立刻", "is_correct": false, "explanation": "语义：“立刻”指马上，与“花了一周”的长时段矛盾。"}, {"text": "忽然", "is_correct": false, "explanation": "语义：“忽然”指突然发生，与搬家之后有计划地整理东西的语境不合。"}, {"text": "过后", "is_correct": true, "explanation": "正确：“过后”表示搬家之后，与“花了一周整理东西”的先后顺序相符。"}, {"text": "从来", "is_correct": false, "explanation": "搭配：“从来”通常与否定词搭配表示一贯如此，不能用于这样的陈述句。"}], "explanations": {"立刻": "语义：“立刻”指马上，与“花了一周”的长时段矛盾。", "忽然": "语义：“忽然”指突然发生，与搬家之后有计划地整理东西的语境不合。", "过后": "正确：“过后”表示搬家之后，与“花了一周整理东西”的先后顺序相符。", "从来": "搭配：“从来”通常与否定词搭配表示一贯如此，不能用于这样的陈述句。"}, "sentence_index": 6, "correct_answer": "过后"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他过后出生在北京。", "explanation": "这里应该用〈在…时〉。过后要接事情做完之后的情况，“出生”是一个时间点，不能用过后。"}, {"text": "他一开始过后就很努力。", "explanation": "这里应该用〈起初〉。过后表示事情做完之后，不能指事情的开始。"}, {"text": "演出前过后，我们走出了剧场。", "explanation": "这里“前”与“过后”的先后关系矛盾。过后表示事情做完之后，不能与“前”同时使用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '016eec18-bb05-45a9-b2ba-daff39320fe3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92039, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "台风过后的，树叶上挂满了水珠。", "corrected_sentence": "台风过后，树叶上挂满了水珠。", "error_description": "错误形式“过后的”，正确形式“过后”。“过后”作状语时后面不加“的”，否则句子不完整。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '016eec18-bb05-45a9-b2ba-daff39320fe3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92039, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他搬家很过后，再整理房间。", "corrected_sentence": "他搬家过后，再整理房间。", "error_description": "错误形式“很过后”。“过后”是时间词，不能被程度副词“很”修饰，应直接用“过后”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '016eec18-bb05-45a9-b2ba-daff39320fe3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
