INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92040, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "过了一段时间以后；事后。", "primary_collocate": null, "pronunciation": "guò hòu", "ipa": "kwo⁵¹ xoʊ⁵¹", "syllable_count": 2, "sentences": [{"text": "这件事过后，大家都不再提起。", "target_word": "过后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "先别急，过后我再给你打电话。", "target_word": "过后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他当时没说什么，过后才生气。", "target_word": "过后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "过后我才发现，钥匙放在包里了。", "target_word": "过后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个问题太复杂，过后再讨论吧。", "target_word": "过后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他嘴上答应了，过后却忘得一干二净。", "target_word": "过后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在人太多，过后你再来拿吧。", "target_word": "过后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "开会时他没提意见，过后才告诉我。", "target_word": "过后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她当时很生气，过后就慢慢好了。", "target_word": "过后", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这笔钱过后再算，现在先吃饭。", "target_word": "过后", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "过后-过一段时间以后，事后", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9582f388-ac0e-48fb-946b-de35c9fd115a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92040, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "事先", "is_correct": false, "explanation": "语义：“事先”指事情发生之前，与句中“这件事过后”的先后顺序相反。"}, {"text": "过后", "is_correct": true, "explanation": "正确：“过后”表示某件事之后，与“大家都不再提起”的时间关系相符。"}, {"text": "首先", "is_correct": false, "explanation": "语义：“首先”表示开始、第一步，与“这件事结束之后”的时间关系不合。"}, {"text": "正在", "is_correct": false, "explanation": "搭配：“正在”表示动作进行中，不能用于已经结束的“这件事”。"}], "explanations": {"事先": "语义：“事先”指事情发生之前，与句中“这件事过后”的先后顺序相反。", "过后": "正确：“过后”表示某件事之后，与“大家都不再提起”的时间关系相符。", "首先": "语义：“首先”表示开始、第一步，与“这件事结束之后”的时间关系不合。", "正在": "搭配：“正在”表示动作进行中，不能用于已经结束的“这件事”。"}, "sentence_index": 0, "correct_answer": "过后"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他一边吃饭，过后一边看书。", "explanation": "这里应该用〈同时〉。过后表示先后顺序，指一件事结束之后，不能与表示同时进行的“一边”搭配。"}, {"text": "现在过后，我们马上开始工作。", "explanation": "这里应该用〈以后〉。过后要接一段时间之后的情况，不能指“现在”这样的当下时点。"}, {"text": "这件事过后已经发生了。", "explanation": "这里应该用〈以前〉。过后指之后，与“已经发生”这种已完成的时间搭配矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '016eec18-bb05-45a9-b2ba-daff39320fe3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92040, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "同时", "is_correct": false, "explanation": "语义：“同时”表示同一时间进行，与“过后再来拿”的先后安排矛盾。"}, {"text": "过后", "is_correct": true, "explanation": "正确：“过后”表示之后再做，与“现在人太多”的语境相符。"}, {"text": "立即", "is_correct": false, "explanation": "语义：“立即”表示马上做，与“过后再来”的安排冲突。"}, {"text": "一直", "is_correct": false, "explanation": "搭配：“一直”表示持续不断，不能与“你再来拿”这样的一次性动作搭配。"}], "explanations": {"同时": "语义：“同时”表示同一时间进行，与“过后再来拿”的先后安排矛盾。", "过后": "正确：“过后”表示之后再做，与“现在人太多”的语境相符。", "立即": "语义：“立即”表示马上做，与“过后再来”的安排冲突。", "一直": "搭配：“一直”表示持续不断，不能与“你再来拿”这样的一次性动作搭配。"}, "sentence_index": 6, "correct_answer": "过后"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他过后出生在北京。", "explanation": "这里应该用〈在…时〉。过后要接一段时间之后的情况，“出生”是一个时间点，不能用过后。"}, {"text": "他一开始过后就很努力。", "explanation": "这里应该用〈起初〉。过后表示之后，不能指事情的开始。"}, {"text": "演出前过后，我们走出了剧场。", "explanation": "这里“前”与“过后”的先后关系矛盾。过后表示事情做完之后，不能与“前”同时使用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '016eec18-bb05-45a9-b2ba-daff39320fe3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92040, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "吃完饭过后以后，我们去看了场电影。", "corrected_sentence": "吃完饭过后，我们去看了场电影。", "error_description": "错误形式“过后以后”，正确形式“过后”。“过后”本身已表示之后，再加“以后”语义重复，只用“过后”即可。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '016eec18-bb05-45a9-b2ba-daff39320fe3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92040, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那件事很过后，他再也没提过。", "corrected_sentence": "那件事过后，他再也没提过。", "error_description": "错误形式“很过后”。“过后”是时间词，不能被程度副词“很”修饰，应直接用“过后”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '016eec18-bb05-45a9-b2ba-daff39320fe3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
