INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92043, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "关系到是这件事会影响另一件事。", "primary_collocate": null, "pronunciation": "guān xì dào", "ipa": "kwan˥ ɕi˥˩ tau˥˩", "syllable_count": 3, "sentences": [{"text": "睡觉好不好关系到第二天的精神。", "target_word": "关系到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你吃什么关系到你的身体健康。", "target_word": "关系到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次考试关系到你能不能上大学。", "target_word": "关系到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "空气好不好关系到大家的健康。", "target_word": "关系到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天气怎么样关系到明天的比赛。", "target_word": "关系到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今天的决定关系到公司以后的发展。", "target_word": "关系到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子的习惯关系到他以后的生活。", "target_word": "关系到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "水干净不是小事，关系到全家人的健康。", "target_word": "关系到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次工作做得怎么样，关系到你能不能留下来。", "target_word": "关系到", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "价格的高低关系到买的人多不多。", "target_word": "关系到", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "一件事会影响另一件事（日常因果影响）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d8816a-ffa1-49a0-9ada-6b37d3a396e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92043, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "关系到", "is_correct": true, "explanation": "正确。“关系到”表示睡觉好不好会影响第二天的精神，符合句意。"}, {"text": "喜欢", "is_correct": false, "explanation": "语义：“喜欢”的主语应是人，句中主语“睡觉好不好”是事情，句子说不通。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”的对象是场所或物品，不能说“打扫第二天的精神”。"}, {"text": "研究", "is_correct": false, "explanation": "语义：“研究”要求有人去探究对象，“睡觉好不好”是一件事，不能“研究”精神。"}], "explanations": {"关系到": "正确。“关系到”表示睡觉好不好会影响第二天的精神，符合句意。", "喜欢": "语义：“喜欢”的主语应是人，句中主语“睡觉好不好”是事情，句子说不通。", "打扫": "搭配：“打扫”的对象是场所或物品，不能说“打扫第二天的精神”。", "研究": "语义：“研究”要求有人去探究对象，“睡觉好不好”是一件事，不能“研究”精神。"}, "sentence_index": 0, "correct_answer": "关系到"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我关系到这份报告的结果。", "explanation": "这里应该用〈关心〉。“关系到”表示一件事影响另一件事，主语必须是事情；人对事情的在意要用“关心”，不能说“我关系到……”。"}, {"text": "我关系到老板的想法。", "explanation": "这里应该用〈了解〉。“关系到”说事情之间的影响，不表示人知道别人的想法；了解对方的想法要用“了解”。"}, {"text": "妈妈关系到我的生活。", "explanation": "这里应该用〈照顾〉。“照顾”是人主动的行为，可以用人作主语；“关系到”只说事情的影响，不能用人作主语来表示照料。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b844e9bd-cc6b-467a-85db-712830f152f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92043, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "关系到", "is_correct": true, "explanation": "正确。习惯会影响他以后的生活，“关系到”表示的正是这种影响。"}, {"text": "参加", "is_correct": false, "explanation": "语义：“参加”需要以人或活动为施事，“孩子的习惯”不能“参加”生活。"}, {"text": "讨论", "is_correct": false, "explanation": "语义：“讨论”要求以人为主语，习惯无法讨论他以后的生活。"}, {"text": "相信", "is_correct": false, "explanation": "搭配：“相信”后面接人或事实，不接“生活”，说“相信他以后的生活”不通。"}], "explanations": {"关系到": "正确。习惯会影响他以后的生活，“关系到”表示的正是这种影响。", "参加": "语义：“参加”需要以人或活动为施事，“孩子的习惯”不能“参加”生活。", "讨论": "语义：“讨论”要求以人为主语，习惯无法讨论他以后的生活。", "相信": "搭配：“相信”后面接人或事实，不接“生活”，说“相信他以后的生活”不通。"}, "sentence_index": 6, "correct_answer": "关系到"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我请大家关系到这份名单。", "explanation": "这里应该用〈通知〉。“关系到”表示事情的影响，不能表示告知别人；告诉大家要用“通知”。"}, {"text": "这件事关系到了一个小时。", "explanation": "这里应该用〈持续〉。“关系到”表示影响，不表示时间的延续；说事情持续了多久要用“持续”。"}, {"text": "我关系到这次活动。", "explanation": "这里应该用〈参与〉。“关系到”说的是一件事对另一件事的影响，不用来表示人参加某件事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b844e9bd-cc6b-467a-85db-712830f152f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92043, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次谈判的结果关系到到两国的未来。", "corrected_sentence": "这次谈判的结果关系到两国的未来。", "error_description": "错误：“关系到”后面多写了一个“到”，变成“关系到到”。正确应删去多余的“到”，说“关系到两国的未来”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b844e9bd-cc6b-467a-85db-712830f152f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92043, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这项技术的突破被关系到国家的安全。", "corrected_sentence": "这项技术的突破关系到国家的安全。", "error_description": "错误：“关系到”表示事物之间的影响，一般不与“被”构成被动，句中多加了“被”。正确应说“这项技术的突破关系到国家的安全”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b844e9bd-cc6b-467a-85db-712830f152f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
