INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92044, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "牵涉到；对某事物有重要影响。", "primary_collocate": null, "pronunciation": "guān xì dào", "ipa": "kwan˥ ɕi˥˩ tau˥˩", "syllable_count": 3, "sentences": [{"text": "这件事关系到整个公司的未来。", "target_word": "关系到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "环境问题关系到每个人的生活。", "target_word": "关系到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个问题关系到国家的大事，不能马虎。", "target_word": "关系到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新办法关系到很多老人的生活。", "target_word": "关系到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个决定关系到一千人的工作。", "target_word": "关系到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "食品安全关系到千家万户。", "target_word": "关系到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这次会议要谈的事关系到学校的未来。", "target_word": "关系到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的话关系到我们的生意，你要听清楚。", "target_word": "关系到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这笔钱关系到孩子能不能上学。", "target_word": "关系到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "教育关系到一个国家的未来。", "target_word": "关系到", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "牵涉到重大事物，对其有重要影响", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d8816a-ffa1-49a0-9ada-6b37d3a396e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92044, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "关系到", "is_correct": true, "explanation": "正确。“关系到”表示这件事会对公司的未来产生重大影响，符合句意。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：“欣赏”的对象是作品或景物等，不能说欣赏“公司的未来”。"}, {"text": "欺骗", "is_correct": false, "explanation": "语义：“欺骗”的施事应是人，“这件事”不能欺骗“公司的未来”。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”的对象是场所或物品，不能用于“公司的未来”。"}], "explanations": {"关系到": "正确。“关系到”表示这件事会对公司的未来产生重大影响，符合句意。", "欣赏": "语义：“欣赏”的对象是作品或景物等，不能说欣赏“公司的未来”。", "欺骗": "语义：“欺骗”的施事应是人，“这件事”不能欺骗“公司的未来”。", "打扫": "搭配：“打扫”的对象是场所或物品，不能用于“公司的未来”。"}, "sentence_index": 0, "correct_answer": "关系到"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我关系到这份名单。", "explanation": "这里应该用〈记住〉。“关系到”表示事情对另一件事的影响，不表示记忆；记住名单要用“记住”。"}, {"text": "我关系到老人的生活。", "explanation": "这里应该用〈陪伴〉。“陪伴”是人主动的行为，可以用人作主语；“关系到”只说事情的影响，不能用人作主语来表示陪同。"}, {"text": "这张桌子关系到很多地方。", "explanation": "这里应该用〈分布〉。“分布”说事物散布在某些地方；“关系到”表示影响，不能用来说明范围或位置。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b844e9bd-cc6b-467a-85db-712830f152f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92044, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "关系到", "is_correct": true, "explanation": "正确。这次会议要谈的事会对学校的未来产生重大影响，“关系到”符合句意。"}, {"text": "批评", "is_correct": false, "explanation": "语义：“批评”的对象是人或人的言行，“要谈的事”不能批评“学校的未来”。"}, {"text": "喂养", "is_correct": false, "explanation": "搭配：“喂养”的对象是人或动物，不能用于“学校的未来”。"}, {"text": "照顾", "is_correct": false, "explanation": "语义：“照顾”要求以人为对象，“要谈的事”不能照顾“学校的未来”。"}], "explanations": {"关系到": "正确。这次会议要谈的事会对学校的未来产生重大影响，“关系到”符合句意。", "批评": "语义：“批评”的对象是人或人的言行，“要谈的事”不能批评“学校的未来”。", "喂养": "搭配：“喂养”的对象是人或动物，不能用于“学校的未来”。", "照顾": "语义：“照顾”要求以人为对象，“要谈的事”不能照顾“学校的未来”。"}, "sentence_index": 6, "correct_answer": "关系到"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这篇文章关系到很长的篇幅。", "explanation": "这里应该用〈占〉。“关系到”表示影响，不表示占据的范围；说占了多少篇幅要用“占”。"}, {"text": "他的声音关系到很大。", "explanation": "这里应该用〈响亮〉。“关系到”表示影响，不能用来形容声音的程度；说声音大要用“响亮”。"}, {"text": "我的朋友关系到了一本书。", "explanation": "这里应该用〈借〉。“关系到”表示影响，不表示借用物品；向别人借书要用“借”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b844e9bd-cc6b-467a-85db-712830f152f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
