INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92045, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "近", "is_correct": true, "explanation": "反义：“近”与“遥远”构成反义，指距离很近。"}, {"text": "清楚", "is_correct": false, "explanation": "无关：“清楚”说明晰，与距离远近无关，不是“遥远”的反义词。"}, {"text": "热闹", "is_correct": false, "explanation": "无关：“热闹”说场面喧闹，与距离远近无关。"}, {"text": "干净", "is_correct": false, "explanation": "无关：“干净”说没有污物，与距离远近无关。"}], "correct_answer": "近", "explanations": {"近": "反义：“近”与“遥远”构成反义，指距离很近。", "清楚": "无关：“清楚”说明晰，与距离远近无关，不是“遥远”的反义词。", "热闹": "无关：“热闹”说场面喧闹，与距离远近无关。", "干净": "无关：“干净”说没有污物，与距离远近无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea50f9b6-3a44-4278-abbe-9c85b78917e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92045, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "近", "is_correct": true, "explanation": "反义：“近”与“遥远”构成反义，指距离很近。"}, {"text": "冰冷", "is_correct": false, "explanation": "无关：“冰冷”说温度低，与距离远近无关。"}, {"text": "迟缓", "is_correct": false, "explanation": "无关：“迟缓”说速度慢，与距离远近无关。"}, {"text": "精彩", "is_correct": false, "explanation": "无关：“精彩”说表演或内容好，与距离远近无关。"}], "correct_answer": "近", "explanations": {"近": "反义：“近”与“遥远”构成反义，指距离很近。", "冰冷": "无关：“冰冷”说温度低，与距离远近无关。", "迟缓": "无关：“迟缓”说速度慢，与距离远近无关。", "精彩": "无关：“精彩”说表演或内容好，与距离远近无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea50f9b6-3a44-4278-abbe-9c85b78917e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92045, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "离得很远很远。", "primary_collocate": null, "pronunciation": "yáo yuǎn", "ipa": "jɑʊ˧˥ ɥɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "那颗星星离我们非常遥远。", "target_word": "遥远", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的家乡在遥远的北方。", "target_word": "遥远", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从这里到那座山，路途很遥远。", "target_word": "遥远", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想去一个遥远的国家看看。", "target_word": "遥远", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机飞向遥远的天边。", "target_word": "遥远", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "遥远的星星在夜里一闪一闪。", "target_word": "遥远", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他走了很久，才到那个遥远的小村子。", "target_word": "遥远", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈住在遥远的南方，我很少见到她。", "target_word": "遥远", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对孩子来说，月亮看起来既美丽又遥远。", "target_word": "遥远", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这封信从遥远的地方寄来。", "target_word": "遥远", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "相隔非常远，远得几乎够不着", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75fd202e-20bb-4aa3-a2f5-79e25091db51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92045, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "遥远", "is_correct": true, "explanation": "正确：遥远说距离很远，与“离我们非常”相合。"}, {"text": "明亮", "is_correct": false, "explanation": "体貌：“明亮”形容光线或外观，不能说离我们的距离，与“离我们非常”不合。"}, {"text": "巨大", "is_correct": false, "explanation": "搭配：“离……非常”后面要接表示距离的形容词，“巨大”说体积，不能说离我们巨大。"}, {"text": "柔软", "is_correct": false, "explanation": "语义：“柔软”说质地，与星星和距离无关，句子讲不通。"}], "explanations": {"遥远": "正确：遥远说距离很远，与“离我们非常”相合。", "明亮": "体貌：“明亮”形容光线或外观，不能说离我们的距离，与“离我们非常”不合。", "巨大": "搭配：“离……非常”后面要接表示距离的形容词，“巨大”说体积，不能说离我们巨大。", "柔软": "语义：“柔软”说质地，与星星和距离无关，句子讲不通。"}, "sentence_index": 0, "correct_answer": "遥远"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他对我的态度很遥远，好像不想理我。", "explanation": "这里应该用〈疏远〉。遥远只指空间或时间上的距离，人与人之间的冷淡要用疏远。"}, {"text": "这件事对我们的影响很遥远。", "explanation": "这里应该用〈深远〉。遥远说距离，说影响广泛而持久要用深远。"}, {"text": "教室离这里只有两步遥远。", "explanation": "这里应该用〈近〉。遥远表示距离很远，不能用来说“只有两步”这样很近的距离；很近的距离要说近。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea50f9b6-3a44-4278-abbe-9c85b78917e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92045, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "遥远", "is_correct": true, "explanation": "正确：遥远说距离很远，与“走了很久，才到”相合。"}, {"text": "近", "is_correct": false, "explanation": "语义：“近”与“走了很久，才到”矛盾，走很久才到说明路途远。"}, {"text": "繁华", "is_correct": false, "explanation": "搭配：“繁华”形容城镇热闹，不能用来修饰“小村子”。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容人或建筑的形体，与“小”矛盾，村子不说高大。"}], "explanations": {"遥远": "正确：遥远说距离很远，与“走了很久，才到”相合。", "近": "语义：“近”与“走了很久，才到”矛盾，走很久才到说明路途远。", "繁华": "搭配：“繁华”形容城镇热闹，不能用来修饰“小村子”。", "高大": "体貌：“高大”形容人或建筑的形体，与“小”矛盾，村子不说高大。"}, "sentence_index": 6, "correct_answer": "遥远"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这杯水很遥远，喝不得。", "explanation": "这里应该用〈烫〉。遥远只说距离，说水温高要用烫。"}, {"text": "我们签订了遥远的合作协议。", "explanation": "这里应该用〈长期〉。遥远不用来修饰合作、协议的持续时间，那要用长期。"}, {"text": "他遥远地完成了那项工作。", "explanation": "这里应该用〈远程〉。遥远只描述距离，不能修饰“完成工作”这类动作；通过网络远程完成要说远程。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea50f9b6-3a44-4278-abbe-9c85b78917e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92045, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的老家在遥远南方。", "corrected_sentence": "他的老家在遥远的南方。", "error_description": "错误：遥远是双音节形容词，修饰名词时后面要加“的”；应为“遥远的南方”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea50f9b6-3a44-4278-abbe-9c85b78917e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92045, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那个村子离城里是遥远。", "corrected_sentence": "那个村子离城里很遥远。", "error_description": "错误：遥远前要用程度副词“很”，不能用判断动词“是”；应为“很遥远”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea50f9b6-3a44-4278-abbe-9c85b78917e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
