INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92046, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "距离很远。", "primary_collocate": null, "pronunciation": "yáo yuǎn", "ipa": "jɑʊ˧˥ ɥɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "他的学校路途遥远，每天要坐一个小时车。", "target_word": "遥远", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个城市非常遥远，见面不容易。", "target_word": "遥远", "complexity_tier": "T3", "furigana": "zhè liǎng gè chéng shì fēi cháng yáo yuǎn, jiàn miàn bù róng yì.", "sentence_source": "generated"}, {"text": "火星离地球十分遥远。", "target_word": "遥远", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个地方太遥远了，我不想去。", "target_word": "遥远", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们之间的距离非常遥远。", "target_word": "遥远", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在遥远的山里有一所小学校。", "target_word": "遥远", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路太遥远，我们决定坐火车去。", "target_word": "遥远", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的朋友在遥远的海边工作。", "target_word": "遥远", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路遥远又难走，大家都很累。", "target_word": "遥远", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不管多遥远，我都会去看你。", "target_word": "遥远", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "两地之间的距离很大", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '75fd202e-20bb-4aa3-a2f5-79e25091db51') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors 