INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92056, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "伊了走，屋里很安静。", "corrected_sentence": "伊走了，屋里很安静。", "error_description": "“了”放错了位置。完成的“了”要放在动词后，应说“伊走了，屋里很安静。”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc2b2ba6-9230-4fbc-942c-da63e836e657') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92056, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妹妹病了，哥哥一直守在伊们身边。", "corrected_sentence": "妹妹病了，哥哥一直守在伊身边。", "error_description": "“伊们”不能指单个的妹妹，“们”是复数词尾，应去掉，说“守在伊身边”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc2b2ba6-9230-4fbc-942c-da63e836e657') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
