INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92058, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "开始吃。", "primary_collocate": null, "pronunciation": "kāi chī", "ipa": "kʰaɪ̯˥ ʈʂʰɻ̩˥", "syllable_count": 2, "sentences": [{"text": "十二点整，大赛选手一起开吃。", "target_word": "开吃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面一端上来，他就低头开吃。", "target_word": "开吃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这碗面太烫了，别急着开吃。", "target_word": "开吃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "螃蟹蒸好了，我们戴上手套开吃。", "target_word": "开吃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜市的小吃摊前，他们一坐下就开吃。", "target_word": "开吃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你们先开吃，我等一下就来。", "target_word": "开吃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "拍完照片再开吃，菜就凉了。", "target_word": "开吃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到饺子上桌，弟弟拿起筷子就开吃。", "target_word": "开吃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到老板说“开吃”，大家都笑了。", "target_word": "开吃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "饿了一天，他一到家就开吃。", "target_word": "开吃", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "开吃了", "label": "体标"}], "register": "口语", "sense_fingerprint": "食物上桌后动筷子开始吃", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f19cc6b-20fc-4f99-ba3d-a7392ff67aec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnin