INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92062, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b844e9bd-cc6b-467a-85db-712830f152f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92062, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人的内部思想、感情和精神世界。", "primary_collocate": null, "pronunciation": "nèi xīn", "ipa": "nei˥˩ ɕin˥", "syllable_count": 2, "sentences": [{"text": "她的内心很复杂。", "target_word": "内心", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他把内心的想法写在了日记里。", "target_word": "内心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个人的内心都有一个小世界。", "target_word": "内心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听了这些话，他的内心很感动。", "target_word": "内心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师看不到孩子内心的想法。", "target_word": "内心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他笑着，可是内心很难过。", "target_word": "内心", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "音乐能让人的内心安静下来。", "target_word": "内心", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她从内心感谢大家。", "target_word": "内心", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "内心强大的人不怕失败。", "target_word": "内心", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这本书写出了老人内心的孤独。", "target_word": "内心", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "内心世界", "label": "复合"}, {"form": "内心深处", "label": "复合"}], "register": "中性", "sense_fingerprint": "人的思想、感情和精神世界", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d8816a-ffa1-49a0-9ada-6b37d3a396e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92062, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "内心", "is_correct": true, "explanation": "正确。“内心”指人的思想感情和精神世界，与“很复杂”搭配，符合句意。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“复杂”形容事情、关系或结构，不用来形容“天气”，“她的天气”也说不通。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“很复杂”一般不修饰“年龄”，“她的年龄很复杂”不自然。"}, {"text": "脚步", "is_correct": false, "explanation": "语义：“脚步”是走路的动作，不能“很复杂”，句子说不通。"}], "explanations": {"内心": "正确。“内心”指人的思想感情和精神世界，与“很复杂”搭配，符合句意。", "天气": "语义：“复杂”形容事情、关系或结构，不用来形容“天气”，“她的天气”也说不通。", "年龄": "搭配：“很复杂”一般不修饰“年龄”，“她的年龄很复杂”不自然。", "脚步": "语义：“脚步”是走路的动作，不能“很复杂”，句子说不通。"}, "sentence_index": 0, "correct_answer": "内心"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "箱子内心放着很多书。", "explanation": "这里应该用〈里面〉。“内心”指人的精神世界，不指箱子的内部；说箱子里面要用“里面”。"}, {"text": "他跑完步，内心跳得很快。", "explanation": "这里应该用〈心〉（指器官）。“内心”指思想感情，不指心脏的跳动；说心跳要用“心”。"}, {"text": "这本书的内心很精彩。", "explanation": "这里应该用〈内容〉。“内心”不指书的内容；说书的内容要用“内容”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b844e9bd-cc6b-467a-85db-712830f152f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92062, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "内心", "is_correct": true, "explanation": "正确。音乐能让人的精神世界平静下来，“内心”符合句意。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“安静下来”形容声音、环境或情绪，不能形容“体重”。"}, {"text": "饭菜", "is_correct": false, "explanation": "搭配：“安静下来”一般不用于“饭菜”，“人的饭菜安静下来”不自然。"}, {"text": "书包", "is_correct": false, "explanation": "语义：“书包”是物品，不会“安静下来”，句子说不通。"}], "explanations": {"内心": "正确。音乐能让人的精神世界平静下来，“内心”符合句意。", "体重": "语义：“安静下来”形容声音、环境或情绪，不能形容“体重”。", "饭菜": "搭配：“安静下来”一般不用于“饭菜”，“人的饭菜安静下来”不自然。", "书包": "语义：“书包”是物品，不会“安静下来”，句子说不通。"}, "sentence_index": 6, "correct_answer": "内心"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "车厢的内心挤满了人。", "explanation": "这里应该用〈里面〉。“内心”指人的精神世界，不指车厢的内部；说车厢里面要用“里面”。"}, {"text": "这座山的内心很高。", "explanation": "这里应该用〈高度〉。“内心”指人的精神世界，不指山的高矮；说山的高度要用“高度”。"}, {"text": "医生量了病人的内心。", "explanation": "这里应该用〈体温〉。“内心”指精神世界，不能用“量”来测；量病人的体温要用“体温”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b844e9bd-cc6b-467a-85db-712830f152f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92062, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她从内心地感到一阵温暖。", "corrected_sentence": "她从内心深处感到一阵温暖。", "error_description": "错误：“内心”是名词，后面不能直接加结构助词“地”修饰动词。正确：用“从内心深处”作状语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b844e9bd-cc6b-467a-85db-712830f152f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92062, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他被内心很平静。", "corrected_sentence": "他的内心很平静。", "error_description": "错误：“他的内心”中的“的”被写成了“被”，“被”不能修饰名词“内心”。正确应说“他的内心很平静”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b844e9bd-cc6b-467a-85db-712830f152f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
