INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92077, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "另外多出来的。", "primary_collocate": null, "pronunciation": "é wài", "ipa": "ɤ˧˥ wai˥˩", "syllable_count": 2, "sentences": [{"text": "朋友要来，我们还需要一张额外的票。", "target_word": "额外", "complexity_tier": "T3", "furigana": "péngyou yào lái, wǒmen hái xūyào yì zhāng éwài de piào.", "sentence_source": "generated"}, {"text": "桌子旁边有一把额外的椅子。", "target_word": "额外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给了我一份额外的练习。", "target_word": "额外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个包里还有一个额外的口袋。", "target_word": "额外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我带了一件额外的衣服，以防下雨。", "target_word": "额外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请给我一双额外的筷子。", "target_word": "额外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的房间里有一张额外的床。", "target_word": "额外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每人可以拿一张额外的纸。", "target_word": "额外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们准备了一些额外的饭菜。", "target_word": "额外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机旁边放着一块额外的电池。", "target_word": "额外", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "額外", "label": "繁体"}], "register": "中性", "sense_fingerprint": "另外多出来的（修饰名词，如额外的票）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ee16441-0431-43df-88c5-2c1ecd454501') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92077, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "额外", "is_correct": true, "explanation": "正确：“额外”指另外多出来的，与“还需要一张”相合。"}, {"text": "多余", "is_correct": false, "explanation": "语义：“多余”指多出而没用，与“还需要”相矛盾。"}, {"text": "大型", "is_correct": false, "explanation": "搭配：“大型”修饰设备、活动，不修饰票。"}, {"text": "过期", "is_correct": false, "explanation": "语义：过期的票不能使用，朋友来了也用不上。"}], "explanations": {"额外": "正确：“额外”指另外多出来的，与“还需要一张”相合。", "多余": "语义：“多余”指多出而没用，与“还需要”相矛盾。", "大型": "搭配：“大型”修饰设备、活动，不修饰票。", "过期": "语义：过期的票不能使用，朋友来了也用不上。"}, "sentence_index": 0, "correct_answer": "额外"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台机器的额外功率是三千瓦。", "explanation": "这里应该用〈额定〉。“额定”指机器规定的标准数值；“额外”表示另外多出来的，不能表示规定的标准。"}, {"text": "这件衣服很额外。", "explanation": "这里应该用〈特别〉。“额外”通常只作定语，不能作谓语或受“很”修饰；表示“与众不同”应说“特别”。"}, {"text": "他听到这个消息后，额外地兴奋。", "explanation": "这里应该用〈非常〉。“额外”是形容词，不能加“地”作状语修饰“兴奋”；表示程度应说“非常兴奋”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e8ac8a2-35e0-433f-81a2-bc7c511da4fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92077, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "额外", "is_correct": true, "explanation": "正确：“额外”指另外多出来的，房间里多出一张床，与句意相合。"}, {"text": "公共", "is_correct": false, "explanation": "语义：房间是他个人的，不会是公共的，与“他的房间里”矛盾。"}, {"text": "室外", "is_correct": false, "explanation": "语义：“室外”与“房间里”位置相反，句意不通。"}, {"text": "透明", "is_correct": false, "explanation": "搭配：“透明”通常修饰玻璃、液体，不修饰床。"}], "explanations": {"额外": "正确：“额外”指另外多出来的，房间里多出一张床，与句意相合。", "公共": "语义：房间是他个人的，不会是公共的，与“他的房间里”矛盾。", "室外": "语义：“室外”与“房间里”位置相反，句意不通。", "透明": "搭配：“透明”通常修饰玻璃、液体，不修饰床。"}, "sentence_index": 6, "correct_answer": "额外"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这张信用卡的额外用完了。", "explanation": "这里应该用〈额度〉。“额外”是形容词，不能作中心语指可用的数额；这里应说“额度”。"}, {"text": "他的成绩额外好。", "explanation": "这里应该用〈特别〉。“额外”表示超出规定或正常的数量，不表示程度，不能说“额外好”。"}, {"text": "这台水泵的额外流量是每小时十吨。", "explanation": "这里应该用〈额定〉。“额定”指规定的标准数值，“额外”表示另外多出来的，不能说“额外流量”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e8ac8a2-35e0-433f-81a2-bc7c511da4fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92077, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他家还需要一台额外地电视。", "corrected_sentence": "他家还需要一台额外的电视。", "error_description": "“额外”修饰名词时后面用“的”，不用“地”（“地”用于修饰动词）。正确的说法是“额外的电视”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e8ac8a2-35e0-433f-81a2-bc7c511da4fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92077, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈还给我买了一块很额外的电池。", "corrected_sentence": "妈妈还给我买了一块额外的电池。", "error_description": "“额外”作定语表示另外多出来的，不能受“很”修饰，应删去“很”。正确的说法是“一块额外的电池”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e8ac8a2-35e0-433f-81a2-bc7c511da4fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
