INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92078, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "超出规定或正常数量地。", "primary_collocate": null, "pronunciation": "é wài", "ipa": "ɤ˧˥ wai˥˩", "syllable_count": 2, "sentences": [{"text": "在这家酒店住，不用额外付钱。", "target_word": "额外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板额外给了他一千块钱奖金。", "target_word": "额外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个活动要额外收费吗？", "target_word": "额外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我常常额外加班。", "target_word": "额外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为他工作努力，公司额外奖励了他。", "target_word": "额外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "寄大箱子要额外交十块钱。", "target_word": "额外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈额外给了我一些零花钱。", "target_word": "额外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超过一百斤的行李要额外收钱。", "target_word": "额外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这道菜加肉的话，需要额外花钱。", "target_word": "额外", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天额外练习半小时。", "target_word": "额外", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "額外", "label": "繁体"}], "register": "中性", "sense_fingerprint": "超出规定或正常数量地（修饰动词，如额外收费）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ee16441-0431-43df-88c5-2c1ecd454501') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92078, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "额外", "is_correct": true, "explanation": "正确：副词“额外”表示超出正常的收费，“不用额外付钱”即不用多付。"}, {"text": "突然", "is_correct": false, "explanation": "语义：“突然”表示事情忽然发生，与“不用付钱”的预先安排不合。"}, {"text": "极力", "is_correct": false, "explanation": "搭配：“极力”修饰争取、阻止之类的行为，不修饰付钱。"}, {"text": "偷偷", "is_correct": false, "explanation": "语义：“偷偷”表示暗中做，与酒店公开收费的语境不合。"}], "explanations": {"额外": "正确：副词“额外”表示超出正常的收费，“不用额外付钱”即不用多付。", "突然": "语义：“突然”表示事情忽然发生，与“不用付钱”的预先安排不合。", "极力": "搭配：“极力”修饰争取、阻止之类的行为，不修饰付钱。", "偷偷": "语义：“偷偷”表示暗中做，与酒店公开收费的语境不合。"}, "sentence_index": 0, "correct_answer": "额外"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台发动机的额外功率是五千瓦。", "explanation": "这里应该用〈额定〉。“额定”指机器规定的标准数值，“额外”表示超出的部分，不能说“额外功率”。"}, {"text": "我们换个额外的地方聚会。", "explanation": "这里应该用〈另外〉。此处“额外的”是形容词，表示“另外多出来的”，不是本题的副词义“超出正常数量地”；换地方应说“另外”。"}, {"text": "我们先额外住在这儿。", "explanation": "这里应该用〈暂时〉。“额外”表示超出规定或正常的数量，不表示短期、临时，“额外住”不是这个意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e8ac8a2-35e0-433f-81a2-bc7c511da4fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92078, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "额外", "is_correct": true, "explanation": "正确：副词“额外”表示超出正常的数量，与“给了我”相合。"}, {"text": "将", "is_correct": false, "explanation": "语义：“将”表示将来，与“给了”的已然事件相矛盾。"}, {"text": "极力", "is_correct": false, "explanation": "搭配：“极力”修饰努力、争取类的行为，不修饰给予。"}, {"text": "兀自", "is_correct": false, "explanation": "语域：“兀自”是书面语，口语中说妈妈给我钱不用此词。"}], "explanations": {"额外": "正确：副词“额外”表示超出正常的数量，与“给了我”相合。", "将": "语义：“将”表示将来，与“给了”的已然事件相矛盾。", "极力": "搭配：“极力”修饰努力、争取类的行为，不修饰给予。", "兀自": "语域：“兀自”是书面语，口语中说妈妈给我钱不用此词。"}, "sentence_index": 6, "correct_answer": "额外"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这道题额外难。", "explanation": "这里应该用〈特别〉。“额外”表示超出正常的量，不表示程度，不能说“额外难”。"}, {"text": "他收到礼物后额外地高兴。", "explanation": "这里应该用〈非常〉。“额外”表示超出规定或正常的数量，不用来形容心理状态，应说“非常高兴”。"}, {"text": "他额外迟到了。", "explanation": "这里应该用〈总是〉。“额外”表示超出正常的量，不表示经常、每次都发生，不能说“额外迟到”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e8ac8a2-35e0-433f-81a2-bc7c511da4fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92078, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公司额外的支付了三天的工资。", "corrected_sentence": "公司额外支付了三天的工资。", "error_description": "“额外”作状语修饰动词时后面不加“的”，应为“额外支付”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e8ac8a2-35e0-433f-81a2-bc7c511da4fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92078, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他很额外买了两本书。", "corrected_sentence": "他额外买了两本书。", "error_description": "“额外”作状语表示超出正常的数量，修饰动词时不能受“很”修饰，应删去“很”。正确的说法是“他额外买了两本书”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e8ac8a2-35e0-433f-81a2-bc7c511da4fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92083, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "服从", "is_correct": true, "explanation": "服从：听从、不对抗，与“反抗”的意思相对。"}, {"text": "欣赏", "is_correct": false, "explanation": "欣赏：表示认为好而喜爱，与“反抗”没有反义关系。"}, {"text": "思考", "is_correct": false, "explanation": "思考：表示用脑子考虑问题，与“反抗”没有反义关系。"}, {"text": "散步", "is_correct": false, "explanation": "散步：表示随意走动，与“反抗”没有反义关系。"}], "correct_answer": "服从", "explanations": {"服从": "服从：听从、不对抗，与“反抗”的意思相对。", "欣赏": "欣赏：表示认为好而喜爱，与“反抗”没有反义关系。", "思考": "思考：表示用脑子考虑问题，与“反抗”没有反义关系。", "散步": "散步：表示随意走动，与“反抗”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bd0453e-b39e-4aac-817e-e61ec63def76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92083, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "服从", "is_correct": true, "explanation": "服从：听从、不对抗，与“反抗”的意思相对。"}, {"text": "学习", "is_correct": false, "explanation": "学习：表示获得知识或技能，与“反抗”没有反义关系。"}, {"text": "旅行", "is_correct": false, "explanation": "旅行：表示到外地游览，与“反抗”没有反义关系。"}, {"text": "唱歌", "is_correct": false, "explanation": "唱歌：表示用声音表达曲调，与“反抗”没有反义关系。"}], "correct_answer": "服从", "explanations": {"服从": "服从：听从、不对抗，与“反抗”的意思相对。", "学习": "学习：表示获得知识或技能，与“反抗”没有反义关系。", "旅行": "旅行：表示到外地游览，与“反抗”没有反义关系。", "唱歌": "唱歌：表示用声音表达曲调，与“反抗”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bd0453e-b39e-4aac-817e-e61ec63def76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92083, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "反抗是别人欺负你，你不听，还要对着干。", "primary_collocate": null, "pronunciation": "fǎn kàng", "ipa": "fan˨˩ kʰɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "同学总欺负他，他不再忍了，开始反抗。", "target_word": "反抗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥打我，我大声反抗。", "target_word": "反抗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板总是骂他，他终于反抗了。", "target_word": "反抗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别人欺负你，你要敢于反抗。", "target_word": "反抗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟太小，不会反抗大孩子。", "target_word": "反抗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从来不反抗，所以总有人欺负她。", "target_word": "反抗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们欺负新同学，新同学反抗过。", "target_word": "反抗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家一起反抗，坏人就不敢欺负了。", "target_word": "反抗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师骂得太凶，他不服气，反抗了几句。", "target_word": "反抗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直忍着，没有反抗。", "target_word": "反抗", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "反抗了", "label": "体标"}, {"form": "反抗过", "label": "体标"}, {"form": "反抗着", "label": "体标"}], "register": "中性", "sense_fingerprint": "被人欺负时不服从并对着干", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a39b3718-fe59-4628-a5c2-d2e3e12e9e82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92083, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "反抗", "is_correct": true, "explanation": "句中“欺负他”的人让他“不再忍了”，“反抗”指对欺负进行对抗，符合语境。"}, {"text": "忍耐", "is_correct": false, "explanation": "语义：“忍耐”是克制、不发作，与“他不再忍了”的句意相矛盾。"}, {"text": "感谢", "is_correct": false, "explanation": "配价：“感谢”需要带感谢的对象或内容，“开始感谢”缺少宾语，不能成句。"}, {"text": "妥协", "is_correct": false, "explanation": "语义：“妥协”是让步，与“他不再忍了”的态度相矛盾。"}], "explanations": {"反抗": "句中“欺负他”的人让他“不再忍了”，“反抗”指对欺负进行对抗，符合语境。", "忍耐": "语义：“忍耐”是克制、不发作，与“他不再忍了”的句意相矛盾。", "感谢": "配价：“感谢”需要带感谢的对象或内容，“开始感谢”缺少宾语，不能成句。", "妥协": "语义：“妥协”是让步，与“他不再忍了”的态度相矛盾。"}, "sentence_index": 0, "correct_answer": "反抗"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用力反抗寒冷。", "explanation": "这里应该用〈抵抗〉。反抗针对压迫或欺凌的人和事，抵御寒冷、疾病等要用抵抗。"}, {"text": "他反抗了老师的邀请。", "explanation": "这里应该用〈拒绝〉。反抗指用行动对抗压迫，对邀请表示不接受要用拒绝。"}, {"text": "他反抗了我的观点。", "explanation": "这里应该用〈反驳〉。反抗指对压迫或欺凌进行对抗，对别人的观点提出不同意见要用反驳。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bd0453e-b39e-4aac-817e-e61ec63def76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92083, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "反抗", "is_correct": true, "explanation": "句中“他们欺负新同学”，“新同学反抗过”指新同学对欺负进行过对抗，符合语境。"}, {"text": "关心", "is_correct": false, "explanation": "语义：“关心”是照顾、挂念，与“他们欺负新同学”的语境相反。"}, {"text": "迟到", "is_correct": false, "explanation": "语义：“迟到”指未按时到达，与“他们欺负新同学”的语境无关，不能表示新同学的反应。"}, {"text": "感激", "is_correct": false, "explanation": "语义：“感激”表示感谢，与被欺负的语境不符，不能表示新同学的反应。"}], "explanations": {"反抗": "句中“他们欺负新同学”，“新同学反抗过”指新同学对欺负进行过对抗，符合语境。", "关心": "语义：“关心”是照顾、挂念，与“他们欺负新同学”的语境相反。", "迟到": "语义：“迟到”指未按时到达，与“他们欺负新同学”的语境无关，不能表示新同学的反应。", "感激": "语义：“感激”表示感谢，与被欺负的语境不符，不能表示新同学的反应。"}, "sentence_index": 6, "correct_answer": "反抗"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他反抗了朋友送的生日礼物。", "explanation": "这里应该用〈收下〉。反抗针对压迫或欺凌，对朋友的好意表示接受要用收下，不能说反抗。"}, {"text": "他每天都反抗工作的辛苦。", "explanation": "这里应该用〈抱怨〉。反抗指对压迫进行对抗，对工作辛苦表示不满要用抱怨。"}, {"text": "他深刻地反抗了自己的错误。", "explanation": "这里应该用〈反省〉。反抗的对象是压迫或不公平的事，检查自己的错误要用反省。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bd0453e-b39e-4aac-817e-e61ec63def76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92083, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他反抗地很勇敢，大家都佩服他。", "corrected_sentence": "他反抗得很勇敢，大家都佩服他。", "error_description": "错误：“反抗地很勇敢”。正确：“反抗得很勇敢”。补语标记应用“得”，不能用“地”，“地”只用于动词前的修饰。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bd0453e-b39e-4aac-817e-e61ec63def76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92083, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新同学以前常常受欺负，却从来没有反抗过了。", "corrected_sentence": "新同学以前常常受欺负，却从来没有反抗过。", "error_description": "错误：“没有反抗过了”。正确：“没有反抗过”。表示否定经历时，“过”后不加“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bd0453e-b39e-4aac-817e-e61ec63def76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92084, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "服从", "is_correct": true, "explanation": "服从：听从、不对抗，与“反抗”的意思相对。"}, {"text": "写作", "is_correct": false, "explanation": "写作：表示写文章，与“反抗”没有反义关系。"}, {"text": "游泳", "is_correct": false, "explanation": "游泳：表示在水中运动，与“反抗”没有反义关系。"}, {"text": "观察", "is_correct": false, "explanation": "观察：表示仔细看、研究，与“反抗”没有反义关系。"}], "correct_answer": "服从", "explanations": {"服从": "服从：听从、不对抗，与“反抗”的意思相对。", "写作": "写作：表示写文章，与“反抗”没有反义关系。", "游泳": "游泳：表示在水中运动，与“反抗”没有反义关系。", "观察": "观察：表示仔细看、研究，与“反抗”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bd0453e-b39e-4aac-817e-e61ec63def76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
