INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92084, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用行动抵抗压迫、欺凌或不合理的事物。", "primary_collocate": null, "pronunciation": "fǎn kàng", "ipa": "fan˨˩ kʰɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "人民起来反抗不合理的制度。", "target_word": "反抗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们反抗老板降低工资。", "target_word": "反抗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民反抗不合理的税。", "target_word": "反抗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用行动反抗不公平的规定。", "target_word": "反抗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奴隶们反抗主人的压迫。", "target_word": "反抗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们一起反抗学校的坏规定。", "target_word": "反抗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的人民反抗了外国的统治。", "target_word": "反抗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们不怕危险，勇敢地反抗压迫。", "target_word": "反抗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村民们反抗着不合理的收费。", "target_word": "反抗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了自由，人们一直在反抗。", "target_word": "反抗", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "反抗了", "label": "体标"}, {"form": "反抗过", "label": "体标"}, {"form": "反抗着", "label": "体标"}], "register": "中性", "sense_fingerprint": "用行动抵抗压迫或不合理的制度和规定", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a39b3718-fe59-4628-a5c2-d2e3e12e9e82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92084, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "反抗", "is_correct": true, "explanation": "句中“不合理的制度”是被反对的对象，“人民起来反抗”符合语境。"}, {"text": "支持", "is_correct": false, "explanation": "语义：“支持”表示赞成、维护，与“起来”和“不合理”的语境相矛盾。"}, {"text": "抵达", "is_correct": false, "explanation": "配价：“抵达”后接地点，不能接“制度”作宾语。"}, {"text": "歌颂", "is_correct": false, "explanation": "语义：“歌颂”表示赞美，与批评“不合理的制度”的语境相反。"}], "explanations": {"反抗": "句中“不合理的制度”是被反对的对象，“人民起来反抗”符合语境。", "支持": "语义：“支持”表示赞成、维护，与“起来”和“不合理”的语境相矛盾。", "抵达": "配价：“抵达”后接地点，不能接“制度”作宾语。", "歌颂": "语义：“歌颂”表示赞美，与批评“不合理的制度”的语境相反。"}, "sentence_index": 0, "correct_answer": "反抗"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们反抗了美味的晚饭。", "explanation": "这里应该用〈享用〉。反抗指对压迫或不合理的事物进行对抗，享受美味的饭菜要用享用。"}, {"text": "他反抗了世界纪录。", "explanation": "这里应该用〈挑战〉。反抗指对压迫或不合理的事物进行对抗，向纪录发起冲击要用挑战。"}, {"text": "大家反抗老人。", "explanation": "这里应该用〈尊重〉。反抗指对压迫或不合理的事物进行对抗，对老人应该表示尊重。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bd0453e-b39e-4aac-817e-e61ec63def76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92084, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "反抗", "is_correct": true, "explanation": "句中“外国的统治”是被对抗的对象，“人民反抗了统治”符合语境。"}, {"text": "欢迎", "is_correct": false, "explanation": "语义：“欢迎”表示乐于接受，与人民对外国统治的对抗相反。"}, {"text": "参观", "is_correct": false, "explanation": "搭配：“参观”多用于场所、展览，不能接“统治”作宾语。"}, {"text": "提倡", "is_correct": false, "explanation": "语义：“提倡”表示主张推行，与“反抗外国的统治”的意思相反。"}], "explanations": {"反抗": "句中“外国的统治”是被对抗的对象，“人民反抗了统治”符合语境。", "欢迎": "语义：“欢迎”表示乐于接受，与人民对外国统治的对抗相反。", "参观": "搭配：“参观”多用于场所、展览，不能接“统治”作宾语。", "提倡": "语义：“提倡”表示主张推行，与“反抗外国的统治”的意思相反。"}, "sentence_index": 6, "correct_answer": "反抗"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他经常反抗自己的错误。", "explanation": "这里应该用〈反省〉。反抗针对压迫或不合理的事物，检查自己的错误要用反省。"}, {"text": "他反抗了对方的说法。", "explanation": "这里应该用〈反驳〉。反抗指对压迫或不合理的事物进行对抗，对别人的说法提出不同意见要用反驳。"}, {"text": "我们反抗老师的帮助。", "explanation": "这里应该用〈感激〉。反抗指对压迫进行对抗，接受别人的帮助并表示谢意要用感激。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bd0453e-b39e-4aac-817e-e61ec63def76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92084, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们曾经反抗地很坚决，后来失败了。", "corrected_sentence": "他们曾经反抗得很坚决，后来失败了。", "error_description": "错误：“反抗地很坚决”。正确：“反抗得很坚决”。补语标记应用“得”，不能用“地”，“地”只用于动词前的修饰。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bd0453e-b39e-4aac-817e-e61ec63def76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92084, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人们正在反抗了不公平的待遇。", "corrected_sentence": "工人们正在反抗不公平的待遇。", "error_description": "错误：“正在反抗了”。正确：“正在反抗”。“正在”表示动作进行，与表示完成的“了”不能同用，去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7bd0453e-b39e-4aac-817e-e61ec63def76') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
