INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92102, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "客套话，主人对离去的客人表示不再远送。", "primary_collocate": null, "pronunciation": "bú sòng", "ipa": "pu˧˥ sʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "您慢走，我就不送了。", "target_word": "不送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请慢走，不送！", "target_word": "不送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人要走了，主人在门口说：“不送。”", "target_word": "不送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外面下雨，我不下楼了，不送！", "target_word": "不送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板忙着开会，只在办公室里说了声不送。", "target_word": "不送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你们走好，我腿不方便，就不送了。", "target_word": "不送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶坐在椅子上说：“慢走，不送啊！”", "target_word": "不送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说了声“不送”，就关上了门。", "target_word": "不送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请代我向您爸爸问好，恕我不送了。", "target_word": "不送", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友告辞时，我只在屋里挥手说不送。", "target_word": "不送", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "礼貌用语", "sense_fingerprint": "主人对离去客人说的客套话，表示不再远送", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f19cc6b-20fc-4f99-ba3d-a7392ff67aec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92102, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "不送", "is_correct": true, "explanation": "正确。“您慢走，我就不送了”是主人送客时的客套话，语境吻合。"}, {"text": "不喝", "is_correct": false, "explanation": "语义：“您慢走”是送别语，接“我就不喝了”没有逻辑，说不通。"}, {"text": "不吃", "is_correct": false, "explanation": "语义：“您慢走”之后说“我就不吃了”，与送客的语境不符。"}, {"text": "不走", "is_correct": false, "explanation": "搭配：“不走”与“您慢走”的意思对立，在这里不能搭配。"}], "explanations": {"不送": "正确。“您慢走，我就不送了”是主人送客时的客套话，语境吻合。", "不喝": "语义：“您慢走”是送别语，接“我就不喝了”没有逻辑，说不通。", "不吃": "语义：“您慢走”之后说“我就不吃了”，与送客的语境不符。", "不走": "搭配：“不走”与“您慢走”的意思对立，在这里不能搭配。"}, "sentence_index": 0, "correct_answer": "不送"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "客人走了，主人说：“您不送。”", "explanation": "这里应该用〈慢走〉。慢走是主人对离开客人的祝福；“不送”是主人不再远送的客套话，不能对客人说“您不送”。"}, {"text": "周五晚上朋友们来火车站不送我，我一个人上车。", "explanation": "这里应该用〈送别〉。送别指到场为人送行；“不送”是主人不再远送的客套话，不能用来说朋友来车站却不到场送我。"}, {"text": "明天我去机场不送，祝你一路平安。", "explanation": "这里应该用〈送行〉。送行指到场送别；“不送”是主人表示不再远送的客套话，不能说“去机场不送”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21cdcb65-e3a9-4523-9818-738ef373d62c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92102, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "不送", "is_correct": true, "explanation": "正确。“慢走，不送啊”是主人送客时的客套话，与奶奶的说话语境相符。"}, {"text": "不去", "is_correct": false, "explanation": "语义：“慢走，不去啊”没有送别的意思，与告别语境不符。"}, {"text": "不看", "is_correct": false, "explanation": "语义：“慢走”之后接“不看”，与送客的语境不符。"}, {"text": "不睡", "is_correct": false, "explanation": "搭配：“慢走”是送别语，与“不睡”搭配不当。"}], "explanations": {"不送": "正确。“慢走，不送啊”是主人送客时的客套话，与奶奶的说话语境相符。", "不去": "语义：“慢走，不去啊”没有送别的意思，与告别语境不符。", "不看": "语义：“慢走”之后接“不看”，与送客的语境不符。", "不睡": "搭配：“慢走”是送别语，与“不睡”搭配不当。"}, "sentence_index": 6, "correct_answer": "不送"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我起身告辞时，对主人说：“不送。”", "explanation": "这里是告辞的客人对主人说，把“不送”当成了告辞者的回应，应改用〈再见〉。"}, {"text": "客人还没坐下，主人就说：“不送。”", "explanation": "这里是客人还没走就说，把“不送”当成了迎客的招呼，应改用〈请进〉。"}, {"text": "老师上课时对学生说：“不送。”", "explanation": "这里是老师对上课的学生说，把“不送”当成了告别的话，应改用〈下课〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21cdcb65-e3a9-4523-9818-738ef373d62c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92102, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "天黑了，你们慢走，我就没不送了。", "corrected_sentence": "天黑了，你们慢走，我就不送了。", "error_description": "错误：“不送”前面多加了“没”，成了“没不送”，双重否定，不成话。这里应说“不送了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21cdcb65-e3a9-4523-9818-738ef373d62c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92102, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈站在门口说：“慢走，不送过啊！”", "corrected_sentence": "妈妈站在门口说：“慢走，不送啊！”", "error_description": "错误：“不送”后面加了“过”。“过”表示经历，“不送过”不成立；这里是客人离开时的客套话，应说“不送啊”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21cdcb65-e3a9-4523-9818-738ef373d62c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
