INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92125, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "导弹是能飞得很远、会自己找到目标的武器。", "primary_collocate": null, "pronunciation": "dǎo dàn", "ipa": "taʊ˨˩˦ tan˥˩", "syllable_count": 2, "sentences": [{"text": "这枚导弹能飞很远。", "target_word": "导弹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军人正在检查那枚导弹。", "target_word": "导弹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家有很多导弹。", "target_word": "导弹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "导弹飞向了远处的目标。", "target_word": "导弹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人把导弹放在大车上。", "target_word": "导弹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视上有一枚导弹的图片。", "target_word": "导弹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "导弹的速度比飞机快。", "target_word": "导弹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在博物馆看过一枚导弹。", "target_word": "导弹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "导弹会自己找到目标。", "target_word": "导弹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种导弹可以飞几千公里。", "target_word": "导弹", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "枚", "label": "量词"}, {"form": "颗", "label": "量词"}, {"form": "洲际导弹", "label": "复合词"}, {"form": "巡航导弹", "label": "复合词"}], "register": "中性", "sense_fingerprint": "能飞很远、自己找目标的武器", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a375dcb8-ff9a-4a39-9db4-43a216043314') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92125, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "导弹", "is_correct": true, "explanation": "导弹是能自己飞行的武器，符合“能飞很远”的语境。"}, {"text": "戒指", "is_correct": false, "explanation": "语义：戒指是戴在手指上的饰品，不会飞，说它“能飞很远”与词义相反。"}, {"text": "邮票", "is_correct": false, "explanation": "语义：邮票是贴在信封上的小纸片，不能飞行，句子的描述不成立。"}, {"text": "徽章", "is_correct": false, "explanation": "搭配：“能飞很远”一般用于有动力的物体，徽章是别在衣服上的标志，不这样搭配。"}], "explanations": {"导弹": "导弹是能自己飞行的武器，符合“能飞很远”的语境。", "戒指": "语义：戒指是戴在手指上的饰品，不会飞，说它“能飞很远”与词义相反。", "邮票": "语义：邮票是贴在信封上的小纸片，不能飞行，句子的描述不成立。", "徽章": "搭配：“能飞很远”一般用于有动力的物体，徽章是别在衣服上的标志，不这样搭配。"}, "sentence_index": 0, "correct_answer": "导弹"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈用导弹做了红烧肉。", "explanation": "这里应该用〈猪肉〉。做红烧肉要用能吃的食材，导弹不是食材，不能用来做菜。"}, {"text": "我们坐导弹去了上海。", "explanation": "这里应该用〈飞机〉。“坐”用于载人的交通工具，导弹不能载人，不能说“坐导弹”。"}, {"text": "我买了一只导弹。", "explanation": "这里应该用〈枚〉或〈颗〉。导弹不用“只”计数，“只”一般用于动物、成对物品中的一个等。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f007e6e-add5-48b6-bbc7-edbd68d8d809') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92125, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "导弹", "is_correct": true, "explanation": "导弹是速度很快的武器，符合“速度比飞机快”的描述。"}, {"text": "蜗牛", "is_correct": false, "explanation": "语义：蜗牛行动很慢，说它的速度比飞机快与常识相反。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“速度”说的是能移动的物体，冰箱是固定的家电，不说它的速度。"}, {"text": "大象", "is_correct": false, "explanation": "语义：大象行动缓慢，句子说它的速度比飞机快，与事实不符。"}], "explanations": {"导弹": "导弹是速度很快的武器，符合“速度比飞机快”的描述。", "蜗牛": "语义：蜗牛行动很慢，说它的速度比飞机快与常识相反。", "冰箱": "搭配：“速度”说的是能移动的物体，冰箱是固定的家电，不说它的速度。", "大象": "语义：大象行动缓慢，句子说它的速度比飞机快，与事实不符。"}, "sentence_index": 6, "correct_answer": "导弹"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "院子里种着一棵导弹。", "explanation": "这里应该用〈枚〉或〈颗〉。导弹不用“棵”计数，“棵”用于树木、植物。"}, {"text": "导弹在马路上行驶了一个小时。", "explanation": "这里应该用〈汽车〉。“行驶”用于汽车等车辆，导弹不在马路上行驶。"}, {"text": "导弹在水里游。", "explanation": "这里应该用〈鱼〉。“游”是鱼等生物的动作，导弹不会游。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f007e6e-add5-48b6-bbc7-edbd68d8d809') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92125, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们把一个导弹运到了基地。", "corrected_sentence": "他们把一枚导弹运到了基地。", "error_description": "错误：导弹不用量词“个”，应用“枚”或“颗”。应说“一枚导弹”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f007e6e-add5-48b6-bbc7-edbd68d8d809') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92125, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那天军方在沙漠里试射了一只导弹。", "corrected_sentence": "那天军方在沙漠里试射了一颗导弹。", "error_description": "错误：“只”不能用于导弹，应改为“颗”或“枚”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4f007e6e-add5-48b6-bbc7-edbd68d8d809') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
