INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92130, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用询问的方式寻求意见或支持。", "primary_collocate": null, "pronunciation": "zhēng qiú", "ipa": "ʈʂɤŋ˥ tɕʰjoʊ˧˥", "syllable_count": 2, "sentences": [{"text": "他到处征求朋友的支持。", "target_word": "征求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "候选人向市民征求支持。", "target_word": "征求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司征求股东的同意。", "target_word": "征求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在做决定以前，请先征求领导的意见。", "target_word": "征求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想征求你对这个计划的看法。", "target_word": "征求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她征求了几位专家的建议。", "target_word": "征求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们征求过老人的意见。", "target_word": "征求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理正在征求各部门的意见。", "target_word": "征求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板征求员工的意见，大家都说好。", "target_word": "征求", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者征求了读者的看法。", "target_word": "征求", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "征求了", "label": "体标"}, {"form": "征求过", "label": "体标"}, {"form": "征求意见", "label": "复合"}], "register": "书面", "sense_fingerprint": "征求:询问并寻求意见、同意或支持", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71448ad7-633e-46ca-9bd3-7ed98c22466a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92130, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "征求", "is_correct": true, "explanation": "征求：用询问的方式寻求朋友的支持，与“到处”相符。"}, {"text": "扔", "is_correct": false, "explanation": "搭配：“扔”搭配的是实物，支持不能被扔。"}, {"text": "煮", "is_correct": false, "explanation": "搭配：“煮”搭配食物，支持不能被煮。"}, {"text": "散布", "is_correct": false, "explanation": "语义：“散布”指传播消息、谣言，不能用于支持。"}], "explanations": {"征求": "征求：用询问的方式寻求朋友的支持，与“到处”相符。", "扔": "搭配：“扔”搭配的是实物，支持不能被扔。", "煮": "搭配：“煮”搭配食物，支持不能被煮。", "散布": "语义：“散布”指传播消息、谣言，不能用于支持。"}, "sentence_index": 0, "correct_answer": "征求"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "下级应该先向领导征求工作。", "explanation": "这里应该用〈请示〉。请示是向上级请求指示，征求的对象是意见，不能说“征求工作”。"}, {"text": "他征求自己的理想。", "explanation": "这里应该用〈追求〉。追求指争取理想，征求的对象是意见，不能用于理想。"}, {"text": "他被征求入伍了。", "explanation": "这里应该用〈征召〉。征召指国家召集人员入伍，征求是询问意见，不能用于入伍。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cef4533-bad1-442c-84f2-5363d49f7e0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92130, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "征求", "is_correct": true, "explanation": "征求：询问老人的意见，符合句意。"}, {"text": "喂", "is_correct": false, "explanation": "搭配：“喂”的对象是动物或婴儿，意见不能被喂。"}, {"text": "碾", "is_correct": false, "explanation": "搭配：“碾”用于碾压物体，意见不能被碾。"}, {"text": "观察", "is_correct": false, "explanation": "语义：“观察”针对现象、事物，不能观察意见。"}], "explanations": {"征求": "征求：询问老人的意见，符合句意。", "喂": "搭配：“喂”的对象是动物或婴儿，意见不能被喂。", "碾": "搭配：“碾”用于碾压物体，意见不能被碾。", "观察": "语义：“观察”针对现象、事物，不能观察意见。"}, "sentence_index": 6, "correct_answer": "征求"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校正在征求新生。", "explanation": "这里应该用〈招生〉。招生指招收学生，征求的对象是意见，不能用于新生。"}, {"text": "他在森林里征求失踪的孩子。", "explanation": "这里应该用〈寻找〉。寻找指找人或物，征求是询问意见，不能用于找人。"}, {"text": "医生征求了病人的身体。", "explanation": "这里应该用〈检查〉。检查指查看身体状况，征求的对象是意见，不能用于身体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9cef4533-bad1-442c-84f2-5363d49f7e0f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
