INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92131, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "差不多是两样东西几乎一样。", "primary_collocate": null, "pronunciation": "chà bu duō", "ipa": "ʈʂʰa˥˩ pu tuo˥", "syllable_count": 3, "sentences": [{"text": "这两件衣服颜色大小差不多。", "target_word": "差不多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "双胞胎长得差不多。", "target_word": "差不多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个手机差不多，只是颜色不同。", "target_word": "差不多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐姐的字和妹妹的差不多。", "target_word": "差不多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两家超市的东西差不多，价钱也差不多。", "target_word": "差不多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两本书的内容差不多。", "target_word": "差不多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的包和你的包差不多，别拿错了。", "target_word": "差不多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两种水果的味道差不多。", "target_word": "差不多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的想法差不多。", "target_word": "差不多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两张画看起来差不多。", "target_word": "差不多", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "差不多：两样东西几乎一样", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d5693c-26b2-4f0a-ad61-6ebde57a6292') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92131, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "差不多", "is_correct": true, "explanation": "“差不多”表示两样东西几乎一样，与“颜色大小”搭配，符合语境。"}, {"text": "鲜艳", "is_correct": false, "explanation": "搭配：“鲜艳”形容颜色，不能说“颜色大小鲜艳”。"}, {"text": "截然不同", "is_correct": false, "explanation": "语义：“截然不同”强调差别很大，与“几乎一样”的意思相反。"}, {"text": "结实", "is_correct": false, "explanation": "搭配：“结实”描写质地，不能用来描述“颜色大小”。"}], "explanations": {"差不多": "“差不多”表示两样东西几乎一样，与“颜色大小”搭配，符合语境。", "鲜艳": "搭配：“鲜艳”形容颜色，不能说“颜色大小鲜艳”。", "截然不同": "语义：“截然不同”强调差别很大，与“几乎一样”的意思相反。", "结实": "搭配：“结实”描写质地，不能用来描述“颜色大小”。"}, "sentence_index": 0, "correct_answer": "差不多"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这两个班的成绩差不多，可是一个班的平均分比另一个高了三十分。", "explanation": "这里“差不多”取“两样东西几乎一样”的义项，后句说平均分相差三十分，前后矛盾。"}, {"text": "这两台电脑的价格差不多，一台是一千元，一台是一万元。", "explanation": "这里“差不多”取“两样东西几乎一样”的义项，后句说价格相差十倍，与之矛盾。"}, {"text": "他俩的个子差不多，他却比对方矮了一大截。", "explanation": "这里“差不多”取“两样东西几乎一样”的义项，后句说矮了一大截，相差很大，前后矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f43cda89-a885-4652-871f-f2ed34a5d6e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92131, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "差不多", "is_correct": true, "explanation": "“差不多”表示两样东西几乎一样，与“别拿错了”的语境相符。"}, {"text": "截然不同", "is_correct": false, "explanation": "语域：“截然不同”偏书面，且强调差别很大，与“别拿错了”的相似性语境矛盾。"}, {"text": "高", "is_correct": false, "explanation": "搭配：“高”描写高度，不能用来形容两个包的相似程度。"}, {"text": "厚", "is_correct": false, "explanation": "语义：“厚”描写厚度，与句中强调两个包相似、容易拿错的意思不符。"}], "explanations": {"差不多": "“差不多”表示两样东西几乎一样，与“别拿错了”的语境相符。", "截然不同": "语域：“截然不同”偏书面，且强调差别很大，与“别拿错了”的相似性语境矛盾。", "高": "搭配：“高”描写高度，不能用来形容两个包的相似程度。", "厚": "语义：“厚”描写厚度，与句中强调两个包相似、容易拿错的意思不符。"}, "sentence_index": 6, "correct_answer": "差不多"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这两家餐厅的菜差不多，一家是素食，一家是烧烤，完全不一样。", "explanation": "这里“差不多”取“两样东西几乎一样”的义项，后句说完全不一样，前后矛盾。"}, {"text": "他们俩的性格差不多，一个外向，一个内向，没有一点相同。", "explanation": "这里“差不多”取“两样东西几乎一样”的义项，后句说没有一点相同，与之矛盾。"}, {"text": "这两件大衣颜色差不多，一件是黑的，一件是白的。", "explanation": "这里“差不多”取“两样东西几乎一样”的义项，后句说一黑一白，颜色差别明显，前后矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f43cda89-a885-4652-871f-f2ed34a5d6e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92131, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这两个杯子大小很差不多。", "corrected_sentence": "这两个杯子大小差不多。", "error_description": "错误：“很”放在了“差不多”前面。正确：“差不多”前不能加“很”，直接说“大小差不多”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f43cda89-a885-4652-871f-f2ed34a5d6e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92131, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这两张画看起来了差不多吧。", "corrected_sentence": "这两张画看起来差不多吧。", "error_description": "错误：“了”放在了“看起来”后、“差不多”前。正确：“看起来差不多”，“了”不能插在“看起来”与“差不多”之间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f43cda89-a885-4652-871f-f2ed34a5d6e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
