INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92133, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "句子后面用“但是”开头加上的话，说明有例外。", "primary_collocate": null, "pronunciation": "dàn shū", "ipa": "tan˥˩ ʂu˥", "syllable_count": 2, "sentences": [{"text": "他写了一句话，后面加了但书。", "target_word": "但书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这句话的但书是“下雨除外”。", "target_word": "但书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的话有一个但书：上课不能玩手机。", "target_word": "但书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈同意我去玩，但书是十点要回家。", "target_word": "但书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个但书说明了例外的情况。", "target_word": "但书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你写这句话时，别忘了加但书。", "target_word": "但书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的但书是“下雨就不去了”。", "target_word": "但书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个计划有个但书，天气好才去。", "target_word": "但书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去掉这个但书，句子意思就变了。", "target_word": "但书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这句话没有但书，所以没有例外。", "target_word": "但书", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个但书", "label": "量词"}, {"form": "但書", "label": "繁体"}], "register": "通用", "sense_fingerprint": "句子后面用“但是”加上的、说明例外的话", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f19cc6b-20fc-4f99-ba3d-a7392ff67aec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92133, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "零钱", "is_correct": false, "explanation": "语义：零钱不是句子的组成部分，句子后面不能加零钱。"}, {"text": "花朵", "is_correct": false, "explanation": "搭配：“加”不能用来表示在句子后面加上花朵。"}, {"text": "但书", "is_correct": true, "explanation": "但书指句子后面用“但是”加上的、说明有例外的话，与“后面加了”相符。"}, {"text": "咖啡", "is_correct": false, "explanation": "语义：咖啡是饮料，与句子的说明无关，句意不通。"}], "explanations": {"零钱": "语义：零钱不是句子的组成部分，句子后面不能加零钱。", "花朵": "搭配：“加”不能用来表示在句子后面加上花朵。", "但书": "但书指句子后面用“但是”加上的、说明有例外的话，与“后面加了”相符。", "咖啡": "语义：咖啡是饮料，与句子的说明无关，句意不通。"}, "sentence_index": 0, "correct_answer": "但书"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这句话每页下面都有但书。", "explanation": "这里应该用〈脚注〉。但书指句子后面加的例外说明，不指页下的注释。"}, {"text": "这句话的但书是一个逗号。", "explanation": "这里误把〈但书〉当作标点。但书指句子后面用“但是”加的说明，不是一个标点符号。"}, {"text": "这句话后面的但书是一座桥。", "explanation": "这里误把〈但书〉当作建筑。但书指句子后面用“但是”加的说明，不是一座桥。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21cdcb65-e3a9-4523-9818-738ef373d62c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92133, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "颜色", "is_correct": false, "explanation": "语义：颜色不是说明例外的话，句意不通。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格不能作为例外的说明，与“下雨就不去了”不搭。"}, {"text": "但书", "is_correct": true, "explanation": "但书指句子后面用“但是”加的例外说明，“下雨就不去了”正是这样的说明。"}, {"text": "座位", "is_correct": false, "explanation": "搭配：“是”后面接的引文只能是话语，不能和“座位”搭配。"}], "explanations": {"颜色": "语义：颜色不是说明例外的话，句意不通。", "价格": "语义：价格不能作为例外的说明，与“下雨就不去了”不搭。", "但书": "但书指句子后面用“但是”加的例外说明，“下雨就不去了”正是这样的说明。", "座位": "搭配：“是”后面接的引文只能是话语，不能和“座位”搭配。"}, "sentence_index": 6, "correct_answer": "但书"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这篇文章的但书是一位朋友的名字。", "explanation": "这里误把〈但书〉当作人名。但书指句子后面用“但是”加的例外说明，不是人名。"}, {"text": "这句话后面加了一个但书，说明出处。", "explanation": "这里应该用〈括号〉。但书用来说明例外，不用来说明出处。"}, {"text": "这句话后面加了一个但书，也就是一位朋友的手机。", "explanation": "这里误把〈但书〉当作物件。但书指句子后面用“但是”加的例外说明，不是具体的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21cdcb65-e3a9-4523-9818-738ef373d62c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92133, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在这句话后面加了一本但书。", "corrected_sentence": "他在这句话后面加了一个但书。", "error_description": "错误：“一本但书”，正确：“一个但书”。句子后面加的说明不能用“本”来数，应用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21cdcb65-e3a9-4523-9818-738ef373d62c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92133, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的但书是一座“下雨就不去了”。", "corrected_sentence": "他的但书是一个“下雨就不去了”。", "error_description": "错误：“一座但书”，正确：“一个但书”。“座”用于山、建筑等大型固定物；但书是抽象的说明，应用“个”来计量。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21cdcb65-e3a9-4523-9818-738ef373d62c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
