INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92134, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "法律条文中以“但是”引出的、说明例外情况的部分。", "primary_collocate": null, "pronunciation": "dàn shū", "ipa": "tan˥˩ ʂu˥", "syllable_count": 2, "sentences": [{"text": "这条法律有一条但书，说明了例外。", "target_word": "但书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条法律的但书规定了例外情形。", "target_word": "但书", "complexity_tier": "T3", "furigana": "zhè tiáo fǎlǜ de dànshū guīdìng le lìwài qíngxíng。", "sentence_source": "generated"}, {"text": "法官仔细读了这条但书。", "target_word": "但书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条规定后面加了一个但书。", "target_word": "但书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "但书的意思是，有例外的时候可以不这样做。", "target_word": "但书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "律师问这条法律有没有但书。", "target_word": "但书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有但书，这条法律就太严了。", "target_word": "但书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "但书让法律更有弹性。", "target_word": "但书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了法律中的但书。", "target_word": "但书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他认为这部法律的但书很有必要。", "target_word": "但书", "complexity_tier": "T3", "furigana": "tā rènwéi zhè bù fǎlǜ de dànshū hěn yǒu bìyào。", "sentence_source": "generated"}], "morphological_forms": [{"form": "一条但书", "label": "量词"}, {"form": "但書", "label": "繁体"}], "register": "书面", "sense_fingerprint": "法律条文里用“但是”引出例外情况的部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f19cc6b-20fc-4f99-ba3d-a7392ff67aec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92134, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "河流", "is_correct": false, "explanation": "语义：河流不能用来说明例外，与“这条法律”不搭。"}, {"text": "但书", "is_correct": true, "explanation": "但书指法律条文中以“但是”引出、说明例外情况的部分，与句意相符。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“一条”不能用来数颜色，颜色也不能说明例外。"}, {"text": "味道", "is_correct": false, "explanation": "语义：味道不能说明例外，句意与法律条文不符。"}], "explanations": {"河流": "语义：河流不能用来说明例外，与“这条法律”不搭。", "但书": "但书指法律条文中以“但是”引出、说明例外情况的部分，与句意相符。", "颜色": "搭配：“一条”不能用来数颜色，颜色也不能说明例外。", "味道": "语义：味道不能说明例外，句意与法律条文不符。"}, "sentence_index": 0, "correct_answer": "但书"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本小说后面附有一个但书。", "explanation": "这里应该用〈注释〉。但书只用于法律条文，表示例外，不用于小说的注释。"}, {"text": "这条规定的但书是一个老师的名字。", "explanation": "这里误把〈但书〉当作人名。但书指法律条文中说明例外的部分，不是人的名字。"}, {"text": "我们把这条但书吃掉了。", "explanation": "这里误把〈但书〉当作食物。但书是法律条文中说明例外的部分，不能吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21cdcb65-e3a9-4523-9818-738ef373d62c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92134, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "重量", "is_correct": false, "explanation": "搭配：“重量”不能与“没有……就太严了”搭配，句意不通。"}, {"text": "花朵", "is_correct": false, "explanation": "语义：花朵与法律的严格程度无关，句子说不通。"}, {"text": "但书", "is_correct": true, "explanation": "但书指法律中说明例外的部分，没有它，法律就没有例外，显得太严。"}, {"text": "气味", "is_correct": false, "explanation": "语义：气味与法律条文无关，句子说不通。"}], "explanations": {"重量": "搭配：“重量”不能与“没有……就太严了”搭配，句意不通。", "花朵": "语义：花朵与法律的严格程度无关，句子说不通。", "但书": "但书指法律中说明例外的部分，没有它，法律就没有例外，显得太严。", "气味": "语义：气味与法律条文无关，句子说不通。"}, "sentence_index": 6, "correct_answer": "但书"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本书的但书很有用。", "explanation": "这里应该用〈附录〉。但书只指法律条文中说明例外的部分，不指书后的附录。"}, {"text": "这部法律的但书是一首流行歌。", "explanation": "这里误把〈但书〉当作歌曲。但书是法律条文中说明例外的部分，不是歌曲。"}, {"text": "这部法律的但书，就是整部法律的名字。", "explanation": "这里误把〈但书〉当作标题。但书指条文中说明例外的部分，不是法律的标题。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21cdcb65-e3a9-4523-9818-738ef373d62c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92134, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条法规中有一本但书写得很清楚。", "corrected_sentence": "这条法规中有一条但书写得很清楚。", "error_description": "错误：“一本但书”，正确：“一条但书”。法律条文的量词用“条”，“本”用于书册。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21cdcb65-e3a9-4523-9818-738ef373d62c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92134, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们已经删掉了这本但书。", "corrected_sentence": "我们已经删掉了这条但书。", "error_description": "错误：“这本但书”，正确：“这条但书”。法律条文的量词用“条”，“本”用于书册。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21cdcb65-e3a9-4523-9818-738ef373d62c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
