INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92137, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "年岁是一个人活了多少年。", "primary_collocate": null, "pronunciation": "nián suì", "ipa": "njɛn˧˥ swei˥˩", "syllable_count": 2, "sentences": [{"text": "他的年岁比我大两岁。", "target_word": "年岁", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "外婆的年岁已经七十多了。", "target_word": "年岁", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "年岁越大，睡觉的时间越短。", "target_word": "年岁", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别问女士的年岁，这样不太礼貌。", "target_word": "年岁", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他虽然年岁不小，但是爱运动。", "target_word": "年岁", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位老人的年岁没有人知道。", "target_word": "年岁", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个孩子年岁还小，不能一个人出门。", "target_word": "年岁", "complexity_tier": "T3", "furigana": "zhè gè hái zi nián suì hái xiǎo, bù néng yí gè rén chū mén", "sentence_source": "generated"}, {"text": "看他的白头发，年岁一定不小了。", "target_word": "年岁", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "年岁大了以后，她很少出远门。", "target_word": "年岁", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生问了老人的年岁和名字。", "target_word": "年岁", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "年歲", "label": "繁体"}], "register": "中性", "sense_fingerprint": "年岁：名词，一个人活了多少年", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d8816a-ffa1-49a0-9ada-6b37d3a396e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92137, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "年岁", "is_correct": true, "explanation": "正确：年岁指年龄，“他的年岁比我大两岁”表示年龄相差两岁。"}, {"text": "寿命", "is_correct": false, "explanation": "搭配：“大两岁”用来比较年龄，寿命不这样比较。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：身高用“高几厘米”来比较，不说“大两岁”。"}, {"text": "学历", "is_correct": false, "explanation": "语义：学历指受教育的程度，不是年龄。"}], "explanations": {"年岁": "正确：年岁指年龄，“他的年岁比我大两岁”表示年龄相差两岁。", "寿命": "搭配：“大两岁”用来比较年龄，寿命不这样比较。", "身高": "搭配：身高用“高几厘米”来比较，不说“大两岁”。", "学历": "语义：学历指受教育的程度，不是年龄。"}, "sentence_index": 0, "correct_answer": "年岁"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的年岁很好。", "explanation": "这里应该用〈成绩〉。年岁指年龄，不用来说成绩好坏。"}, {"text": "他的年岁是六十公斤。", "explanation": "这里应该用〈体重〉。年岁是年龄，不用来表示重量。"}, {"text": "他的年岁是三十七度。", "explanation": "这里应该用〈体温〉。年岁是年龄，不用来表示温度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b844e9bd-cc6b-467a-85db-712830f152f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92137, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "年岁", "is_correct": true, "explanation": "正确：“这个孩子年岁还小”指年龄小，不能一个人出门。"}, {"text": "体重", "is_correct": false, "explanation": "语义：句中“不能一个人出门”的原因是年龄小，体重说明不了这一点。"}, {"text": "学费", "is_correct": false, "explanation": "语义：学费是钱的数额，不能描述孩子的大小。"}, {"text": "成绩", "is_correct": false, "explanation": "搭配：成绩用“好”“差”描述，不用“还小”。"}], "explanations": {"年岁": "正确：“这个孩子年岁还小”指年龄小，不能一个人出门。", "体重": "语义：句中“不能一个人出门”的原因是年龄小，体重说明不了这一点。", "学费": "语义：学费是钱的数额，不能描述孩子的大小。", "成绩": "搭配：成绩用“好”“差”描述，不用“还小”。"}, "sentence_index": 6, "correct_answer": "年岁"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的年岁在北京。", "explanation": "这里应该用〈住址〉。年岁指年龄，不能表示地点。"}, {"text": "这朵花的年岁很红。", "explanation": "这里应该用〈颜色〉。年岁指年龄，不能描述颜色。"}, {"text": "他的年岁是一串数字。", "explanation": "这里应该用〈电话号码〉。年岁是人的年龄，不是号码。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b844e9bd-cc6b-467a-85db-712830f152f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92137, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的年岁是三十个。", "corrected_sentence": "他的年岁是三十岁。", "error_description": "错误：“三十个”；正确：“三十岁”。年龄的单位是“岁”，不能用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b844e9bd-cc6b-467a-85db-712830f152f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92137, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她年岁不小着。", "corrected_sentence": "她年岁不小了。", "error_description": "错误：“年岁不小着”；正确：“年岁不小了”。表示年龄已经达到某种状态、出现变化时要用句末“了”，“着”表示持续，这里不能用。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b844e9bd-cc6b-467a-85db-712830f152f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
