INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92138, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "年龄；也指年代。", "primary_collocate": null, "pronunciation": "nián suì", "ipa": "njɛn˧˥ swei˥˩", "syllable_count": 2, "sentences": [{"text": "爷爷的年岁很大了。", "target_word": "年岁", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的年岁不大，却懂很多事。", "target_word": "年岁", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人的年岁大了，走路很慢。", "target_word": "年岁", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "随着年岁变大，他越来越爱安静。", "target_word": "年岁", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "在那个艰难的年岁里，大家互相帮助。", "target_word": "年岁", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她看起来比实际年岁年轻很多。", "target_word": "年岁", "complexity_tier": "T3", "furigana": "tā kàn qǐ lái bǐ shí jì nián suì nián qīng hěn duō", "sentence_source": "generated"}, {"text": "那些年岁里，我们住在小村子里。", "target_word": "年岁", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "年岁大的人应该多休息。", "target_word": "年岁", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个年岁的孩子都爱玩游戏。", "target_word": "年岁", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "奶奶虽然年岁大了，身体还很好。", "target_word": "年岁", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "年歲", "label": "繁体"}], "register": "中性", "sense_fingerprint": "年岁：名词，年龄；也指某个年代", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d8816a-ffa1-49a0-9ada-6b37d3a396e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92138, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "年岁", "is_correct": true, "explanation": "正确：年岁指年龄，爷爷的年岁大，即年纪大了。"}, {"text": "寿命", "is_correct": false, "explanation": "搭配：“很大了”描写年纪，寿命通常说“长”，不说“很大”。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：身高说“高”，不说“很大了”，也不能表示年龄。"}, {"text": "学历", "is_correct": false, "explanation": "语义：学历指受教育的程度，不是年龄。"}], "explanations": {"年岁": "正确：年岁指年龄，爷爷的年岁大，即年纪大了。", "寿命": "搭配：“很大了”描写年纪，寿命通常说“长”，不说“很大”。", "身高": "搭配：身高说“高”，不说“很大了”，也不能表示年龄。", "学历": "语义：学历指受教育的程度，不是年龄。"}, "sentence_index": 0, "correct_answer": "年岁"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这把椅子的年岁很硬。", "explanation": "这里应该用〈硬度〉。年岁指年龄或年代，不能用来描述椅子的软硬。"}, {"text": "他的年岁是一米八。", "explanation": "这里应该用〈身高〉。年岁指年龄，不能用来表示身高。"}, {"text": "他的年岁很帅。", "explanation": "这里应该用〈长相〉。年岁是年龄，不能用来描述外貌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b844e9bd-cc6b-467a-85db-712830f152f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92138, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "年岁", "is_correct": true, "explanation": "正确：“那些年岁”指一段时期，句子表示在那段岁月里住在村子里。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：“那些体重里”不能表示时间段，体重与“里”不搭配。"}, {"text": "学费", "is_correct": false, "explanation": "语义：学费指上学要交的钱，不能表示一段时期。"}, {"text": "成绩", "is_correct": false, "explanation": "语义：成绩指学习或工作的表现，不能表示一段时期。"}], "explanations": {"年岁": "正确：“那些年岁”指一段时期，句子表示在那段岁月里住在村子里。", "体重": "搭配：“那些体重里”不能表示时间段，体重与“里”不搭配。", "学费": "语义：学费指上学要交的钱，不能表示一段时期。", "成绩": "语义：成绩指学习或工作的表现，不能表示一段时期。"}, "sentence_index": 6, "correct_answer": "年岁"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的年岁在北京。", "explanation": "这里应该用〈住址〉。年岁指年龄，不能表示地点。"}, {"text": "这朵花的年岁很红。", "explanation": "这里应该用〈颜色〉。年岁指年龄，不能描述颜色。"}, {"text": "他的年岁叫小明。", "explanation": "这里应该用〈名字〉。年岁指年龄，不能用来指人的名字。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b844e9bd-cc6b-467a-85db-712830f152f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92138, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他年岁大了很，走路还很稳。", "corrected_sentence": "他年岁大了，走路还很稳。", "error_description": "错误：“大了很”；正确：“大了”。“很”是修饰形容词的程度副词，不能放在“了”之后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b844e9bd-cc6b-467a-85db-712830f152f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92138, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他年岁不小着，记性也变差了。", "corrected_sentence": "他年岁不小了，记性也变差了。", "error_description": "错误：“年岁不小着”；正确：“年岁不小了”。表示状态出现变化要用句末“了”，“着”表示动作或状态的持续，这里不能用。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b844e9bd-cc6b-467a-85db-712830f152f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
