INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92139, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用掉一部分。", "primary_collocate": null, "pronunciation": "zhàn qù", "ipa": "ʈʂan˥˩ tɕʰy˥˩", "syllable_count": 2, "sentences": [{"text": "写作业占去了我两个小时。", "target_word": "占去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次搬家占去了我一整个周末。", "target_word": "占去", "complexity_tier": "T3", "furigana": "zhè cì bān jiā zhàn qù le wǒ yì zhěng gè zhōu mò", "sentence_source": "generated"}, {"text": "开会占去了今天一半时间。", "target_word": "占去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买房子占去了他大部分钱。", "target_word": "占去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路上堵车占去不少时间。", "target_word": "占去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的补习班占去了家里大半的积蓄。", "target_word": "占去", "complexity_tier": "T3", "furigana": "hái zi de bǔ xí bān zhàn qù le jiā lǐ dà bàn de jī xù", "sentence_source": "generated"}, {"text": "上网占去了孩子很多学习时间。", "target_word": "占去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些照片占去了手机一半的空间。", "target_word": "占去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做饭占去我一个晚上。", "target_word": "占去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的工作占去了生活的大部分。", "target_word": "占去", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "占去了", "label": "体标"}], "register": "中性", "sense_fingerprint": "占去：用掉时间、空间、钱等的一部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d5693c-26b2-4f0a-ad61-6ebde57a6292') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92139, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "占去", "is_correct": true, "explanation": "“占去”表示用掉一部分时间，与“两个小时”搭配，符合语境。"}, {"text": "增加", "is_correct": false, "explanation": "语义：“增加”表示变多，与“用掉一部分”的意思相反。"}, {"text": "退还", "is_correct": false, "explanation": "语义：“退还”表示把东西还回去，不是用掉时间。"}, {"text": "赔偿", "is_correct": false, "explanation": "搭配：“赔偿”多用于物品或损失，不能说“赔偿了两个小时”。"}], "explanations": {"占去": "“占去”表示用掉一部分时间，与“两个小时”搭配，符合语境。", "增加": "语义：“增加”表示变多，与“用掉一部分”的意思相反。", "退还": "语义：“退还”表示把东西还回去，不是用掉时间。", "赔偿": "搭配：“赔偿”多用于物品或损失，不能说“赔偿了两个小时”。"}, "sentence_index": 0, "correct_answer": "占去"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "买房子占去了他大部分钱，他却一分钱也没花。", "explanation": "这里“占去”取“用掉一部分”的义项，后句说一分钱也没花，与之矛盾。"}, {"text": "写作业占去了我两个小时，我却完全没有写作业。", "explanation": "这里“占去”取“用掉时间”的义项，后句说完全没写作业，与之矛盾。"}, {"text": "玩游戏占去了他很多时间，他却说从没玩过游戏。", "explanation": "这里“占去”取“用掉时间”的义项，后句说从没玩过，与之矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f43cda89-a885-4652-871f-f2ed34a5d6e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92139, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "占去", "is_correct": true, "explanation": "“占去”表示用掉时间，与“很多学习时间”搭配，说明学习时间被上网用掉了。"}, {"text": "节省", "is_correct": false, "explanation": "语义：“节省”表示少用，与句中“很多学习时间被用掉”的意思相反。"}, {"text": "补充", "is_correct": false, "explanation": "搭配：“补充”用于补足不够的东西，不能说“补充了学习时间”。"}, {"text": "腾出", "is_correct": false, "explanation": "语义：“腾出”表示空出来，与“被用掉”的意思相反。"}], "explanations": {"占去": "“占去”表示用掉时间，与“很多学习时间”搭配，说明学习时间被上网用掉了。", "节省": "语义：“节省”表示少用，与句中“很多学习时间被用掉”的意思相反。", "补充": "搭配：“补充”用于补足不够的东西，不能说“补充了学习时间”。", "腾出": "语义：“腾出”表示空出来，与“被用掉”的意思相反。"}, "sentence_index": 6, "correct_answer": "占去"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次出差占去了他一半的工资，他却说一分钱都没花。", "explanation": "这里“占去”取“用掉一部分”的义项，后句说一分钱都没花，与之矛盾。"}, {"text": "这顿饭占去了我一个月的生活费，我却一口也没吃。", "explanation": "这里“占去”取“用掉一部分”的义项，后句说一口也没吃，与之矛盾。"}, {"text": "这本书占去了他两个小时的阅读，他却一页也没翻。", "explanation": "这里“占去”取“用掉时间”的义项，后句说一页也没翻，与之矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f43cda89-a885-4652-871f-f2ed34a5d6e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92139, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "抄作业占去着他一个晚上。", "corrected_sentence": "抄作业占去了他一个晚上。", "error_description": "错误：“占去”后面加了“着”。正确：“占去了”，表示已经用掉一段时间，要用“了”而不是“着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f43cda89-a885-4652-871f-f2ed34a5d6e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92139, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次旅行很占去了他一半的积蓄。", "corrected_sentence": "这次旅行占去了他一半的积蓄。", "error_description": "错误：“很”放在了“占去”前面。正确：“很”只能修饰形容词，“占去了”前面不能加“很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f43cda89-a885-4652-871f-f2ed34a5d6e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
