INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92144, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "援引他人的话语、文字或事例来作为自己说话、写作的依据。", "primary_collocate": null, "pronunciation": "yǐn yòng", "ipa": "in˨˩ jʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "写论文时，要引用可靠的材料。", "target_word": "引用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他引用了一个例子来说明自己的看法。", "target_word": "引用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这篇文章引用了很多历史书里的内容。", "target_word": "引用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "律师在法庭上引用了一条法律。", "target_word": "引用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "论文最后要写出引用过的书名。", "target_word": "引用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者在报道中引用了专家的数据。", "target_word": "引用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她引用古诗来证明自己的话是对的。", "target_word": "引用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师要求我们引用资料时写明来源。", "target_word": "引用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他没有引用任何材料，所以大家不相信他。", "target_word": "引用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作者引用了几个事例，让道理更清楚。", "target_word": "引用", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "引用了", "label": "体标"}, {"form": "引用过", "label": "体标"}], "register": "书面语", "sense_fingerprint": "引用：动词，援引话语、文字或事例作为说话、写作的依据", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d8816a-ffa1-49a0-9ada-6b37d3a396e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92144, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "引用", "is_correct": true, "explanation": "引用：援引可靠的材料作为论文的依据，符合句意。"}, {"text": "丢弃", "is_correct": false, "explanation": "语义：“丢弃”与写论文需要可靠材料的要求相悖。"}, {"text": "隐瞒", "is_correct": false, "explanation": "语义：“隐瞒”与写论文需要可靠依据的要求相悖。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能接“材料”作宾语，这里语义不通。"}], "explanations": {"引用": "引用：援引可靠的材料作为论文的依据，符合句意。", "丢弃": "语义：“丢弃”与写论文需要可靠材料的要求相悖。", "隐瞒": "语义：“隐瞒”与写论文需要可靠依据的要求相悖。", "吃": "搭配：“吃”不能接“材料”作宾语，这里语义不通。"}, "sentence_index": 0, "correct_answer": "引用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学生把生词引用在本子上。", "explanation": "这里应该用〈抄写〉。引用是援引作为依据用于说话或写作，把生词原样誊写要用抄写。"}, {"text": "律师在法庭上引用了一瓶水。", "explanation": "这里把〈引用〉误用为“拿来用”的泛用义；引用只针对事例、话语或文字，实物不能被援引。"}, {"text": "律师在法庭上引用了一阵风。", "explanation": "这里把〈引用〉误用为“提到、说起”的泛用义；引用只针对事例、话语或文字，风这类自然现象不能被援引。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b844e9bd-cc6b-467a-85db-712830f152f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92144, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "引用", "is_correct": true, "explanation": "引用：援引古诗作为证明，符合句意。"}, {"text": "烧", "is_correct": false, "explanation": "搭配：“烧”不能与“古诗”作为证明的依据搭配，这里语义不通。"}, {"text": "撕", "is_correct": false, "explanation": "语义：撕毁古诗与用古诗证明自己的话相悖，不能作为依据。"}, {"text": "丢", "is_correct": false, "explanation": "搭配：“丢”不能用来表示用古诗作为证明，这里不通。"}], "explanations": {"引用": "引用：援引古诗作为证明，符合句意。", "烧": "搭配：“烧”不能与“古诗”作为证明的依据搭配，这里语义不通。", "撕": "语义：撕毁古诗与用古诗证明自己的话相悖，不能作为依据。", "丢": "搭配：“丢”不能用来表示用古诗作为证明，这里不通。"}, "sentence_index": 6, "correct_answer": "引用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "作者引用了几个打火机，让道理更清楚。", "explanation": "这里把〈引用〉误用为“拿来用”的泛用义；引用只针对事例、话语或文字，器物不能被援引。"}, {"text": "作者引用了一个水杯，让道理更清楚。", "explanation": "这里把〈引用〉误用为“拿来用”的泛用义；引用只针对事例、话语或文字，器物不能被援引。"}, {"text": "作者引用了一杯咖啡，让道理更清楚。", "explanation": "这里把〈引用〉误用为“拿来用”的泛用义；引用只针对事例、话语或文字，饮品这类实物不能被援引。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b844e9bd-cc6b-467a-85db-712830f152f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92144, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们在论文中引用几句权威报告。", "corrected_sentence": "我们在论文中引用几份权威报告。", "error_description": "错误：“报告”的量词应为“份”，不用“句”。“几句权威报告”应改为“几份权威报告”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b844e9bd-cc6b-467a-85db-712830f152f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92144, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他引用很准确，没有改动原文。", "corrected_sentence": "他引用得很准确，没有改动原文。", "error_description": "错误：“引用”后漏了补语标记“得”，应说“引用得很准确”，用“得”连接动词与补语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b844e9bd-cc6b-467a-85db-712830f152f5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
