INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92158, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "暂时留在某处，不继续前进。", "primary_collocate": null, "pronunciation": "tíng liú", "ipa": "tʰiŋ˧˥ ljoʊ˧˥", "syllable_count": 2, "sentences": [{"text": "我们在路上停留，等朋友来。", "target_word": "停留", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在机场停留了三个小时。", "target_word": "停留", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "船在小岛停留一晚，明天再走。", "target_word": "停留", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旅行中，我们在每个城市停留两天。", "target_word": "停留", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公交车在站台停留了一会儿。", "target_word": "停留", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她只想在这里停留几天。", "target_word": "停留", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨太大，我们在山上停留着，没有下山。", "target_word": "停留", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在家乡停留了一个星期就走了。", "target_word": "停留", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火车今天在中间站停留较久。", "target_word": "停留", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "客人在门口停留了一下，才走进来。", "target_word": "停留", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "停留了", "label": "体标（了）"}, {"form": "停留过", "label": "体标（过）"}, {"form": "停留着", "label": "体标（着）"}], "register": "中性", "sense_fingerprint": "旅途中暂时停下、之后还要继续走", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9db54c0a-ae30-43eb-977b-2b2ba8aec6f3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92158, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "停留", "is_correct": true, "explanation": "正确：“停留”表示在途中暂时停下，与“等朋友来”的语境相合。"}, {"text": "前进", "is_correct": false, "explanation": "语义：“前进”表示继续向前走，与“等朋友来”的停下等候矛盾。"}, {"text": "加速", "is_correct": false, "explanation": "语义：“加速”是提速前行，与“等朋友来”的停下等候矛盾，句子不通。"}, {"text": "出发", "is_correct": false, "explanation": "语义：“出发”是动身开始走，与“等朋友来”的停下等候不合。"}], "explanations": {"停留": "正确：“停留”表示在途中暂时停下，与“等朋友来”的语境相合。", "前进": "语义：“前进”表示继续向前走，与“等朋友来”的停下等候矛盾。", "加速": "语义：“加速”是提速前行，与“等朋友来”的停下等候矛盾，句子不通。", "出发": "语义：“出发”是动身开始走，与“等朋友来”的停下等候不合。"}, "sentence_index": 0, "correct_answer": "停留"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这所学校因为台风停留了一周。", "explanation": "这里应该用〈停课〉。因故暂停上课应说停课，停留表示待在某处不走，不能用来指停止上课。"}, {"text": "他讲话时停留了一下，又接着说。", "explanation": "这里应该用〈停顿〉。讲话中间的短暂中断用停顿，停留不表示中断。"}, {"text": "工地因为下雨停留了一天。", "explanation": "这里应该用〈停工〉。因下雨停止施工应说停工，停留表示待在某处不走。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ce1bb74-2ee6-432f-8cae-6f30d9f5b5e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92158, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "停留", "is_correct": true, "explanation": "正确：“停留着”表示停在山上的状态，与“没有下山”搭配，句意通顺。"}, {"text": "停泊", "is_correct": false, "explanation": "搭配：“停泊”用于船只靠岸，不用于人在山上待着。"}, {"text": "冲刺", "is_correct": false, "explanation": "语义：“冲刺”是加速奔跑，与雨大、没有下山的状态不合。"}, {"text": "生长", "is_correct": false, "explanation": "语义：“生长”指生物长大，不用于人在山上待着，句子不通。"}], "explanations": {"停留": "正确：“停留着”表示停在山上的状态，与“没有下山”搭配，句意通顺。", "停泊": "搭配：“停泊”用于船只靠岸，不用于人在山上待着。", "冲刺": "语义：“冲刺”是加速奔跑，与雨大、没有下山的状态不合。", "生长": "语义：“生长”指生物长大，不用于人在山上待着，句子不通。"}, "sentence_index": 6, "correct_answer": "停留"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "比赛中途停留了十分钟。", "explanation": "这里应该用〈暂停〉。比赛中途暂时中断应说暂停，停留不表示中断进行。"}, {"text": "工厂因为停电停留了一天。", "explanation": "这里应该用〈停止〉。因停电而停止生产应说停止，停留表示待在某处。"}, {"text": "雨终于停留了。", "explanation": "这里应该用〈停歇〉。雨停止下落用停歇，不说停留。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ce1bb74-2ee6-432f-8cae-6f30d9f5b5e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92158, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们车站停留，等朋友来。", "corrected_sentence": "我们在车站停留，等朋友来。", "error_description": "错误：“停留”前缺少介词“在”，地点要用“在＋地点”引出。应说“我们在车站停留”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ce1bb74-2ee6-432f-8cae-6f30d9f5b5e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92158, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在外地停留着一个星期就走了。", "corrected_sentence": "他在外地停留了一个星期就走了。", "error_description": "错误：“停留”后的动态助词应用“了”表示动作已经完成，不能用“着”。应说“停留了一个星期”，不说“停留着一个星期”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ce1bb74-2ee6-432f-8cae-6f30d9f5b5e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
