INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92163, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "受了伤的人，和不在了的人。", "primary_collocate": null, "pronunciation": "shāng wáng", "ipa": "ʂɑŋ˥ wɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这次地震的伤亡已经超过了一百人。", "target_word": "伤亡", "complexity_tier": "T3", "furigana": "shāng wáng", "sentence_source": "generated"}, {"text": "救援队先从房子里找出伤亡的人。", "target_word": "伤亡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火灾中的伤亡名单已经出来了。", "target_word": "伤亡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者问政府有多少伤亡。", "target_word": "伤亡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察正在统计这次车祸的伤亡。", "target_word": "伤亡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争让两边都有很多伤亡。", "target_word": "伤亡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在名单上找家人的伤亡情况。", "target_word": "伤亡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场车祸的伤亡数字还没有确定。", "target_word": "伤亡", "complexity_tier": "T3", "furigana": "shāng wáng", "sentence_source": "generated"}, {"text": "这次火灾的伤亡都是附近的居民。", "target_word": "伤亡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府给伤亡家庭送去了钱。", "target_word": "伤亡", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "傷亡", "label": "繁体"}], "register": "书面", "sense_fingerprint": "事故或灾难中受伤和死亡的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f19cc6b-20fc-4f99-ba3d-a7392ff67aec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92163, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "伤亡", "is_correct": true, "explanation": "正确：伤亡指受伤和死亡的人，可以说“超过了一百人”。"}, {"text": "灾情", "is_correct": false, "explanation": "语义：灾情指灾害的状况，不是人，不能用人数来说“超过了一百人”。"}, {"text": "财产", "is_correct": false, "explanation": "语义：财产是钱和物，不能用人数计算，“超过了一百人”说不通。"}, {"text": "面积", "is_correct": false, "explanation": "搭配：“面积”用平方米、公顷等计量，不和“超过了一百人”搭配。"}], "explanations": {"伤亡": "正确：伤亡指受伤和死亡的人，可以说“超过了一百人”。", "灾情": "语义：灾情指灾害的状况，不是人，不能用人数来说“超过了一百人”。", "财产": "语义：财产是钱和物，不能用人数计算，“超过了一百人”说不通。", "面积": "搭配：“面积”用平方米、公顷等计量，不和“超过了一百人”搭配。"}, "sentence_index": 0, "correct_answer": "伤亡"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次洪水的伤亡是十万元。", "explanation": "这里应该用〈损失〉。伤亡只指受伤和死亡的人，钱财上的减少要说损失。"}, {"text": "这辆卡车的伤亡很严重。", "explanation": "这里应该用〈损坏〉。伤亡只用于人，车辆受到破坏要说损坏。"}, {"text": "这次事故的伤亡是两百万元。", "explanation": "这里应该用〈赔偿〉。伤亡指人的受伤和死亡，赔给受害者的钱要说赔偿。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21cdcb65-e3a9-4523-9818-738ef373d62c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92163, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "伤亡", "is_correct": true, "explanation": "正确：“伤亡情况”指受伤和死亡的状况，符合“找家人”的语境。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是天空的状况，不会出现在名单上，“找家人的天气情况”说不通。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重是身体的重量，不能在名单上查找，与“找家人”无关。"}, {"text": "产量", "is_correct": false, "explanation": "搭配：“产量”用于生产和农作物，不能说“找家人的产量”。"}], "explanations": {"伤亡": "正确：“伤亡情况”指受伤和死亡的状况，符合“找家人”的语境。", "天气": "语义：天气是天空的状况，不会出现在名单上，“找家人的天气情况”说不通。", "体重": "语义：体重是身体的重量，不能在名单上查找，与“找家人”无关。", "产量": "搭配：“产量”用于生产和农作物，不能说“找家人的产量”。"}, "sentence_index": 6, "correct_answer": "伤亡"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的左手受到了伤亡。", "explanation": "这里应该用〈损伤〉。伤亡指人群或事件中的伤亡，不用于身体的某一个部位，手的伤要说损伤。"}, {"text": "他的伤亡很重，医生让他住院。", "explanation": "这里应该用〈伤势〉。伤亡不用来形容一个人受伤的程度，描述伤情要说伤势。"}, {"text": "他的感情受到了伤亡。", "explanation": "这里应该用〈伤害〉。伤亡只指受伤和死亡，不用于感情，感情受到的损害要说伤害。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21cdcb65-e3a9-4523-9818-738ef373d62c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92163, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这场洪水的一个伤亡已经超过了八十人。", "corrected_sentence": "这场洪水的伤亡已经超过了八十人。", "error_description": "错误：“伤亡”前面加了量词“一个”。伤亡不能用“个”来计量，应直接说“这场洪水的伤亡”，或用“伤亡人数”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21cdcb65-e3a9-4523-9818-738ef373d62c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92163, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那场战争的伤亡得很惨重。", "corrected_sentence": "那场战争的伤亡很惨重。", "error_description": "错误：“伤亡”后面加了“得”。伤亡是名词，不能带程度补语，应直接说“伤亡很惨重”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21cdcb65-e3a9-4523-9818-738ef373d62c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92164, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21cdcb65-e3a9-4523-9818-738ef373d62c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92164, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21cdcb65-e3a9-4523-9818-738ef373d62c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92164, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "受伤和死亡；也指受伤和死亡的人。", "primary_collocate": null, "pronunciation": "shāng wáng", "ipa": "ʂɑŋ˥ wɑŋ˧˥", "syllable_count": 2, "sentences": [{"text": "这次事故没有造成伤亡。", "target_word": "伤亡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地震造成了很大的伤亡。", "target_word": "伤亡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂很注意安全，怕有伤亡。", "target_word": "伤亡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争会带来大量伤亡。", "target_word": "伤亡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大雨来了，政府怕出现伤亡。", "target_word": "伤亡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场火灾幸好没有伤亡。", "target_word": "伤亡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们想办法减少伤亡。", "target_word": "伤亡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司机开得很慢，所以没有伤亡。", "target_word": "伤亡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新闻说这次大火的伤亡不大。", "target_word": "伤亡", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了避免伤亡，大家都离开了山下。", "target_word": "伤亡", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "傷亡", "label": "繁体"}], "register": "书面", "sense_fingerprint": "事故或战争中受伤和死亡的情况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f19cc6b-20fc-4f99-ba3d-a7392ff67aec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92164, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "伤亡", "is_correct": true, "explanation": "正确：“造成伤亡”是固定说法，伤亡指受伤和死亡的情况。"}, {"text": "名字", "is_correct": false, "explanation": "语义：名字是称呼，不是事故造成的后果，不能说“造成名字”。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是天空的状况，不是事故的后果，不能说“造成天气”。"}, {"text": "节日", "is_correct": false, "explanation": "语义：节日是固定的日子，不会因为事故而产生，不能说“造成节日”。"}], "explanations": {"伤亡": "正确：“造成伤亡”是固定说法，伤亡指受伤和死亡的情况。", "名字": "语义：名字是称呼，不是事故造成的后果，不能说“造成名字”。", "天气": "语义：天气是天空的状况，不是事故的后果，不能说“造成天气”。", "节日": "语义：节日是固定的日子，不会因为事故而产生，不能说“造成节日”。"}, "sentence_index": 0, "correct_answer": "伤亡"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这场战争夺走了很多伤亡。", "explanation": "这里应该用〈生命〉。“夺走”接的是生命，伤亡是情况，不能被夺走。"}, {"text": "这次事故给环境带来了很大的伤亡。", "explanation": "这里应该用〈伤害〉。伤亡只指人的受伤和死亡，对环境的损害要说伤害。"}, {"text": "他们在伤亡途中被抓住了。", "explanation": "这里应该用〈逃亡〉。伤亡指受伤和死亡，没有逃走的意思，“逃亡途中”要说逃亡。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21cdcb65-e3a9-4523-9818-738ef373d62c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92164, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "伤亡", "is_correct": true, "explanation": "正确：“减少伤亡”是固定说法，伤亡指受伤和死亡的情况。"}, {"text": "名字", "is_correct": false, "explanation": "语义：名字不是可以“减少”的数量或程度，“减少名字”句意不通。"}, {"text": "身高", "is_correct": false, "explanation": "语义：身高是人的长度，不能用“减少”来说，这里说不通。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色是视觉上的属性，不能用“减少”来说。"}], "explanations": {"伤亡": "正确：“减少伤亡”是固定说法，伤亡指受伤和死亡的情况。", "名字": "语义：名字不是可以“减少”的数量或程度，“减少名字”句意不通。", "身高": "语义：身高是人的长度，不能用“减少”来说，这里说不通。", "颜色": "语义：颜色是视觉上的属性，不能用“减少”来说。"}, "sentence_index": 6, "correct_answer": "伤亡"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次撞击造成了机器的伤亡。", "explanation": "这里应该用〈损伤〉。伤亡指人的受伤和死亡，机器的毁坏要说损伤。"}, {"text": "他的伤亡很重，需要住院。", "explanation": "这里应该用〈伤势〉。伤亡不用来形容一个人受伤的程度，描述伤情要说伤势。"}, {"text": "这场火灾烧毁了很多伤亡。", "explanation": "这里应该用〈财产〉。伤亡只指人的受伤和死亡，烧毁的是财产。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21cdcb65-e3a9-4523-9818-738ef373d62c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92164, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这场大雨没有造成一座伤亡。", "corrected_sentence": "这场大雨没有造成伤亡。", "error_description": "错误：“伤亡”前面加了量词“一座”。“座”用于山、楼房等大型固定物，不能用来计量伤亡，应直接说“没有造成伤亡”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21cdcb65-e3a9-4523-9818-738ef373d62c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92164, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这场火灾造成了很多头伤亡。", "corrected_sentence": "这场火灾造成了很多伤亡。", "error_description": "错误：“伤亡”前面加了量词“头”。“头”用于牲畜等动物，不能用来计量伤亡，应直接说“造成了很多伤亡”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21cdcb65-e3a9-4523-9818-738ef373d62c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92173, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19390a79-ee61-422e-b23d-01f3660db1ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
