INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92173, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "桥是修在河上面，让人和车走过去的路。", "primary_collocate": null, "pronunciation": "qiáo", "ipa": "t͡ɕʰjɑʊ̯˧˥", "syllable_count": 1, "sentences": [{"text": "河上有一座新桥。", "target_word": "桥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们走过那座桥，就到学校了。", "target_word": "桥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥又长又宽，车可以开过去。", "target_word": "桥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桥下面有很多小鱼。", "target_word": "桥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他站在桥上看河水。", "target_word": "桥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过了桥，向左走就是我家。", "target_word": "桥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河上只有一座桥。", "target_word": "桥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在桥边玩水。", "target_word": "桥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下大雨时，河水快要到桥面了。", "target_word": "桥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人每天早上都在桥上走一走。", "target_word": "桥", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "座", "label": "量词"}, {"form": "橋", "label": "繁体"}], "register": "中性", "sense_fingerprint": "河上供人和车通行的桥", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e47ca02c-da77-46cf-8e0b-0a9f8df1a1a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92173, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "桥", "is_correct": true, "explanation": "桥（qiáo，第二声）指河上供人和车通行的建筑，是正确答案。"}, {"text": "敲", "is_correct": false, "explanation": "qiāo（第一声）与 qiáo（第二声）声调不同，意思是敲打。"}, {"text": "俏", "is_correct": false, "explanation": "qiào（第四声）与 qiáo（第二声）声调不同，意思是俊俏、好看。"}, {"text": "巧", "is_correct": false, "explanation": "qiǎo（第三声）与 qiáo（第二声）声调不同，意思是巧妙。"}, {"text": "嚼", "is_correct": false, "explanation": "jiáo（第二声）与 qiáo 声母不同（j 与 q），意思是咀嚼。"}], "explanations": {"桥": "桥（qiáo，第二声）指河上供人和车通行的建筑，是正确答案。", "敲": "qiāo（第一声）与 qiáo（第二声）声调不同，意思是敲打。", "俏": "qiào（第四声）与 qiáo（第二声）声调不同，意思是俊俏、好看。", "巧": "qiǎo（第三声）与 qiáo（第二声）声调不同，意思是巧妙。", "嚼": "jiáo（第二声）与 qiáo 声母不同（j 与 q），意思是咀嚼。"}, "sentence_index": null, "correct_answer": "桥"}, "level_3": {"options": [{"text": "桥", "is_correct": true, "explanation": "桥指架在河上供人和车通行的建筑，与“座”和“河上”搭配，是正确答案。"}, {"text": "船", "is_correct": false, "explanation": "搭配：“座”不用于船，船应该用“条”或“只”计量。"}, {"text": "树", "is_correct": false, "explanation": "搭配：树一般用“棵”计量，不能说“一座树”。"}, {"text": "鱼", "is_correct": false, "explanation": "语义：鱼是生物，不能在河上修建，“河上有一座新鱼”说不通。"}], "explanations": {"桥": "桥指架在河上供人和车通行的建筑，与“座”和“河上”搭配，是正确答案。", "船": "搭配：“座”不用于船，船应该用“条”或“只”计量。", "树": "搭配：树一般用“棵”计量，不能说“一座树”。", "鱼": "语义：鱼是生物，不能在河上修建，“河上有一座新鱼”说不通。"}, "sentence_index": 0, "correct_answer": "桥"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在这座桥里种了三年菜。", "explanation": "这里应该用〈田〉或〈菜园〉。种菜要有土地，桥是供人和车通过的建筑，里面没有可以种菜的土。"}, {"text": "他每天坐桥过河去上班。", "explanation": "这里应该用〈船〉。桥是固定的建筑，人是走过去的，不能说“坐桥”；坐着过河要用船。"}, {"text": "大船靠在桥上装货，很快就开走了。", "explanation": "这里应该用〈码头〉。船靠岸装卸货物要在码头；桥是架在水面或空中、供人车通行的建筑，不能用来停靠装货。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19390a79-ee61-422e-b23d-01f3660db1ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92173, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "桥", "is_correct": true, "explanation": "桥指横跨河面的建筑，与“座”和“这条河上”搭配，是正确答案。"}, {"text": "花", "is_correct": false, "explanation": "搭配：花一般用“朵”计量，不能说“一座花”。"}, {"text": "狗", "is_correct": false, "explanation": "搭配：狗用“只”或“条”计量，不能用“座”。"}, {"text": "云", "is_correct": false, "explanation": "语义：云不是固定的建筑，不能架在河上，“河上只有一座云”说不通。"}], "explanations": {"桥": "桥指横跨河面的建筑，与“座”和“这条河上”搭配，是正确答案。", "花": "搭配：花一般用“朵”计量，不能说“一座花”。", "狗": "搭配：狗用“只”或“条”计量，不能用“座”。", "云": "语义：云不是固定的建筑，不能架在河上，“河上只有一座云”说不通。"}, "sentence_index": 6, "correct_answer": "桥"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人们把那座桥扔进了垃圾桶。", "explanation": "这里应该用〈纸〉。桥是大型固定建筑，扔不进垃圾桶；能扔进垃圾桶的是纸、塑料袋这类小东西。"}, {"text": "为了早点到山那边，我们从桥穿过去。", "explanation": "这里应该用〈隧道〉。桥架在水面或空中，人只能走过去，不能“穿过”山；穿山要走隧道。"}, {"text": "这座桥把河水拦住了，船开不过去。", "explanation": "这里应该用〈大坝〉。拦住河水是大坝的作用；桥架在水面上，水可以从桥下流过，不能用来拦水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19390a79-ee61-422e-b23d-01f3660db1ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92173, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们在河上修了一只桥。", "corrected_sentence": "他们在河上修了一座桥。", "error_description": "量词错误：桥应该用“座”计量，说“一只桥”是错误的；“只”一般用于动物或小件物品。正确说法是“一座桥”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19390a79-ee61-422e-b23d-01f3660db1ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92173, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们在上桥拍了一张照片。", "corrected_sentence": "我们在桥上拍了一张照片。", "error_description": "方位词错误：表示位置要说“桥上”；“上桥”是动词短语，意思是走上桥，不能表示“在桥的位置”。正确说法是“在桥上”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19390a79-ee61-422e-b23d-01f3660db1ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
