INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92174, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "架在水面或空中，便于通行的建筑物。", "primary_collocate": null, "pronunciation": "qiáo", "ipa": "t͡ɕʰjɑʊ̯˧˥", "syllable_count": 1, "sentences": [{"text": "两座大楼中间有一座桥。", "target_word": "桥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥架在海上，有三十公里长。", "target_word": "桥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路口车太多，他们在空中修了一座桥。", "target_word": "桥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们正在江上造桥。", "target_word": "桥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥是去年修好的。", "target_word": "桥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "站在桥上能看到整个海湾。", "target_word": "桥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有了海上的桥，两个城市近多了。", "target_word": "桥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桥连着小岛和城市。", "target_word": "桥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桥上的灯晚上都亮着。", "target_word": "桥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车从高高的桥上开过去了。", "target_word": "桥", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "座", "label": "量词"}, {"form": "橋", "label": "繁体"}], "register": "中性", "sense_fingerprint": "架在水面或空中便于通行的建筑物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e47ca02c-da77-46cf-8e0b-0a9f8df1a1a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92174, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "桥", "is_correct": true, "explanation": "桥（qiáo，第二声）指架在水面或空中便于通行的建筑物，是正确答案。"}, {"text": "悄", "is_correct": false, "explanation": "qiāo（第一声）与 qiáo（第二声）声调不同，意思是安静、不出声。"}, {"text": "翘", "is_correct": false, "explanation": "qiào（第四声）与 qiáo（第二声）声调不同，意思是向上弯起。"}, {"text": "巧", "is_correct": false, "explanation": "qiǎo（第三声）与 qiáo（第二声）声调不同，意思是巧妙。"}, {"text": "嚼", "is_correct": false, "explanation": "jiáo（第二声）与 qiáo 声母不同（j 与 q），意思是咀嚼。"}], "explanations": {"桥": "桥（qiáo，第二声）指架在水面或空中便于通行的建筑物，是正确答案。", "悄": "qiāo（第一声）与 qiáo（第二声）声调不同，意思是安静、不出声。", "翘": "qiào（第四声）与 qiáo（第二声）声调不同，意思是向上弯起。", "巧": "qiǎo（第三声）与 qiáo（第二声）声调不同，意思是巧妙。", "嚼": "jiáo（第二声）与 qiáo 声母不同（j 与 q），意思是咀嚼。"}, "sentence_index": null, "correct_answer": "桥"}, "level_3": {"options": [{"text": "桥", "is_correct": true, "explanation": "桥指架在两座大楼之间或水面上方的建筑，与“座”和“中间有”搭配，是正确答案。"}, {"text": "人", "is_correct": false, "explanation": "语义：“人”不是建筑，不能横在两座大楼中间，也不能用“座”计量。"}, {"text": "狗", "is_correct": false, "explanation": "搭配：狗用“只”计量，不能说“一座狗”。"}, {"text": "云", "is_correct": false, "explanation": "搭配：云用“朵”计量，不能说“一座云”。"}], "explanations": {"桥": "桥指架在两座大楼之间或水面上方的建筑，与“座”和“中间有”搭配，是正确答案。", "人": "语义：“人”不是建筑，不能横在两座大楼中间，也不能用“座”计量。", "狗": "搭配：狗用“只”计量，不能说“一座狗”。", "云": "搭配：云用“朵”计量，不能说“一座云”。"}, "sentence_index": 0, "correct_answer": "桥"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人们在江边种了一座桥。", "explanation": "这里应该用〈造〉。“种”用于树木等植物；桥是人工建造的，要说“造”或“建”。"}, {"text": "他们每天在桥里游泳。", "explanation": "这里应该用〈湖〉。桥是架在水面上的建筑，人不能在桥里游泳；游泳的地方是湖或江。"}, {"text": "孩子们在桥里捉迷藏，玩得很开心。", "explanation": "这里应该用〈房间〉或〈树林〉。捉迷藏要找能藏人的地方；桥是架在水面或空中的通道，里面没有可以藏人的空间。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19390a79-ee61-422e-b23d-01f3660db1ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92174, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "桥", "is_correct": true, "explanation": "桥指架在海上连接两地的建筑，与“海上的”搭配，能让两城变近，是正确答案。"}, {"text": "花", "is_correct": false, "explanation": "语义：花不能连接两个城市，“有了海上的花，两个城市近多了”说不通。"}, {"text": "雨", "is_correct": false, "explanation": "语义：雨不是连接两地的设施，句子意思与“两城变近”不符。"}, {"text": "墙", "is_correct": false, "explanation": "搭配：“海上”后一般接“桥”“航线”等，“海上的墙”不成固定搭配。"}], "explanations": {"桥": "桥指架在海上连接两地的建筑，与“海上的”搭配，能让两城变近，是正确答案。", "花": "语义：花不能连接两个城市，“有了海上的花，两个城市近多了”说不通。", "雨": "语义：雨不是连接两地的设施，句子意思与“两城变近”不符。", "墙": "搭配：“海上”后一般接“桥”“航线”等，“海上的墙”不成固定搭配。"}, "sentence_index": 6, "correct_answer": "桥"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那座桥被打碎了，车过不去了。", "explanation": "这里应该用〈炸毁〉或〈拆除〉。“打碎”用于玻璃、花瓶等易碎的东西，如〈玻璃〉〈花瓶〉；桥是大型建筑，不能说“打碎”。"}, {"text": "渔船靠在桥上卸鱼，很快就走了。", "explanation": "这里应该用〈码头〉。渔船靠岸卸货要在码头；桥是供人车通行的建筑，不能用来停靠卸货。"}, {"text": "他把那座桥挂在墙上，当成装饰品。", "explanation": "这里应该用〈画〉。挂在墙上的一般是画或装饰品；桥是大型建筑，不能挂在墙上当装饰。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19390a79-ee61-422e-b23d-01f3660db1ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92174, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他骑车过了那只桥。", "corrected_sentence": "他骑车过了那座桥。", "error_description": "量词错误：桥应该用“座”计量，不能用“只”。正确说法是“他骑车过了那座桥”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19390a79-ee61-422e-b23d-01f3660db1ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92174, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "车子慢慢开过了一张桥。", "corrected_sentence": "车子慢慢开过了那座桥。", "error_description": "量词错误：桥应该用“座”计量，不能用“张”；“张”用于纸、桌子等平面的东西。正确说法是“开过了那座桥”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '19390a79-ee61-422e-b23d-01f3660db1ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
