INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92187, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一个国家所有的土地。", "primary_collocate": null, "pronunciation": "guó tǔ", "ipa": "kwo˧˥ tʰu˨˩˦", "syllable_count": 2, "sentences": [{"text": "中国的国土面积很大，有很多山和河。", "target_word": "国土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的国土很小，只有一座城市。", "target_word": "国土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "俄罗斯的国土从东到西非常长。", "target_word": "国土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我国的国土西高东低，有高山也有平原。", "target_word": "国土", "complexity_tier": "T3", "furigana": "wǒ guó de guó tǔ xī gāo dōng dī yǒu gāo shān yě yǒu píng yuán", "sentence_source": "generated"}, {"text": "国土辽阔的国家，气候往往不一样。", "target_word": "国土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府每年都在国土上种很多树。", "target_word": "国土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全国的国土一共有九百六十万平方公里。", "target_word": "国土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在地图上指出了我国的国土范围。", "target_word": "国土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的国土三面是海，一面是山。", "target_word": "国土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国土的东边靠海，西边有大沙漠。", "target_word": "国土", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "國土", "label": "繁体"}, {"form": "国土面积", "label": "复合"}, {"form": "国土资源", "label": "复合"}], "register": "正式", "sense_fingerprint": "一个国家全部的土地，常说面积大小、地形、辽阔", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77de9a14-9b0d-47dd-90ec-b14e6f01c7cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92187, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "国土", "is_correct": true, "explanation": "正确：“国土”指一个国家全部的土地，与“面积”“很大”搭配。"}, {"text": "人口", "is_correct": false, "explanation": "搭配：“面积”说土地、地区的大小，人口不能说“人口面积”。"}, {"text": "政府", "is_correct": false, "explanation": "语义：“政府”是国家机构，不是地域，没有面积可言。"}, {"text": "历史", "is_correct": false, "explanation": "搭配：“面积”只用于地域，不说“历史面积”。"}], "explanations": {"国土": "正确：“国土”指一个国家全部的土地，与“面积”“很大”搭配。", "人口": "搭配：“面积”说土地、地区的大小，人口不能说“人口面积”。", "政府": "语义：“政府”是国家机构，不是地域，没有面积可言。", "历史": "搭配：“面积”只用于地域，不说“历史面积”。"}, "sentence_index": 0, "correct_answer": "国土"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个县的国土很贫瘠，庄稼长不好。", "explanation": "这里应该用〈土地〉。“国土”指一个国家的全部土地，一个县的土地不能说“国土”。"}, {"text": "今天的国土很好，我们去公园吧。", "explanation": "这里应该用〈天气〉。“国土”指国家的全部土地，不能用来说天气好坏。"}, {"text": "这个湖的国土很大，岸边有很多树。", "explanation": "这里应该用〈面积〉。湖不是国家，不能说“国土很大”，应说湖的面积。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '877073eb-87a4-4b4c-8c72-a1ed6a80e827') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92187, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "国土", "is_correct": true, "explanation": "正确：“国土”是地域，可以用“平方公里”计量面积。"}, {"text": "人民", "is_correct": false, "explanation": "语义：“人民”指人，不是地域，不能用平方公里计量。"}, {"text": "语言", "is_correct": false, "explanation": "搭配：“平方公里”只用于计量地域，不说“语言一共有……平方公里”。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”是气象状况，没有面积，不能用平方公里计量。"}], "explanations": {"国土": "正确：“国土”是地域，可以用“平方公里”计量面积。", "人民": "语义：“人民”指人，不是地域，不能用平方公里计量。", "语言": "搭配：“平方公里”只用于计量地域，不说“语言一共有……平方公里”。", "天气": "语义：“天气”是气象状况，没有面积，不能用平方公里计量。"}, "sentence_index": 6, "correct_answer": "国土"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个省的国土有三千万，比很多国家都多。", "explanation": "这里应该用〈人口〉。“国土”只说地域的大小，不能用来计算人数。"}, {"text": "这座山的国土很陡，人很难爬上去。", "explanation": "这里应该用〈山坡〉。“国土”指国家的全部土地，不能用来形容一座山的陡峭，应说“山坡很陡”。"}, {"text": "这个公园的国土很大，有很多花。", "explanation": "公园不是国家，不能用“国土”来说它的面积。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '877073eb-87a4-4b4c-8c72-a1ed6a80e827') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92187, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个国家有一只很大的国土。", "corrected_sentence": "这个国家有一块很大的国土。", "error_description": "量词错误：“只”不能修饰“国土”，应改为“块”，即“一块很大的国土”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '877073eb-87a4-4b4c-8c72-a1ed6a80e827') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92187, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个国家的国土面比我想象的大得多。", "corrected_sentence": "这个国家的国土面积比我想象的大得多。", "error_description": "复合词错误：“国土面积”是固定说法，不能漏掉“积”，应说“国土面积”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '877073eb-87a4-4b4c-8c72-a1ed6a80e827') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
