INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92191, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "最开始要先学会的问题。", "primary_collocate": null, "pronunciation": "jī chǔ wèn tí", "ipa": "tɕi˥ ʈʂʰu˨˩˦ wən˥˩ tʰi˧˥", "syllable_count": 4, "sentences": [{"text": "学汉语先要弄懂基础问题。", "target_word": "基础问题", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师先回答了几个基础问题。", "target_word": "基础问题", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书只讲基础问题，很适合新手。", "target_word": "基础问题", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "考试里有很多基础问题，别丢分。", "target_word": "基础问题", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他是新来的，总问一些基础问题。", "target_word": "基础问题", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "初学者常常搞不懂这些基础问题。", "target_word": "基础问题", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "先把基础问题学好，再学难的内容。", "target_word": "基础问题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我复习了一遍课本上的基础问题。", "target_word": "基础问题", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学生问的基础问题，老师都耐心地讲过。", "target_word": "基础问题", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开课第一天，大家先练习基础问题。", "target_word": "基础问题", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "基礎問題", "label": "繁体"}, {"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "入门阶段必须先学会的简单问题", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '823356df-e298-42d6-83d2-7110f3829571') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92191, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "基础问题", "is_correct": true, "explanation": "正确：“基础问题”是学汉语时要先弄懂的入门问题，与“先要弄懂”的语境相符。"}, {"text": "早饭", "is_correct": false, "explanation": "语义：早饭是一餐饭，不是需要弄懂的学习内容，与“学汉语”的语境不符。"}, {"text": "景点", "is_correct": false, "explanation": "搭配：“弄懂”的对象是道理、意思一类，不能说弄懂景点。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，不是需要弄懂的学习内容，与“学汉语”的语境不符。"}], "explanations": {"基础问题": "正确：“基础问题”是学汉语时要先弄懂的入门问题，与“先要弄懂”的语境相符。", "早饭": "语义：早饭是一餐饭，不是需要弄懂的学习内容，与“学汉语”的语境不符。", "景点": "搭配：“弄懂”的对象是道理、意思一类，不能说弄懂景点。", "天气": "语义：天气是自然现象，不是需要弄懂的学习内容，与“学汉语”的语境不符。"}, "sentence_index": 0, "correct_answer": "基础问题"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的基础问题很扎实，老师很满意。", "explanation": "这里应该用〈基础知识〉。“扎实”形容知识、功底，“基础问题”是要先学会的问题，不能说扎实。"}, {"text": "我们已经打好了基础问题，可以开始盖楼了。", "explanation": "这里应该用〈根基〉。“打好根基”指打地基的根底，“基础问题”是问题，不能用来表示根基。"}, {"text": "我一直向基础问题请教，就学会了很多东西。", "explanation": "这里应该用〈老师〉。“请教”的对象应是人，“基础问题”是问题，不能被请教，应说向老师请教。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ee32d3a-f152-4aa3-805c-4fe650e9eb88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92191, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "基础问题", "is_correct": true, "explanation": "正确：“先把……学好”的对象是要学的基础内容，“基础问题”符合语境。"}, {"text": "景色", "is_correct": false, "explanation": "搭配：“学好”的对象是知识、技能，不能说学好景色。"}, {"text": "工资", "is_correct": false, "explanation": "搭配：工资是收入，不是可以学好的东西，“学好工资”不成立。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是场所，不是可以学好的内容，与“再学难的内容”的顺序不符。"}], "explanations": {"基础问题": "正确：“先把……学好”的对象是要学的基础内容，“基础问题”符合语境。", "景色": "搭配：“学好”的对象是知识、技能，不能说学好景色。", "工资": "搭配：工资是收入，不是可以学好的东西，“学好工资”不成立。", "厨房": "语义：厨房是场所，不是可以学好的内容，与“再学难的内容”的顺序不符。"}, "sentence_index": 6, "correct_answer": "基础问题"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "开课第一天，大家先参观基础问题。", "explanation": "搭配：“参观”的对象是地方或设施，“基础问题”是问题，不能被参观，应说参观教室。"}, {"text": "开课第一天，大家先搬基础问题。", "explanation": "搭配：“搬”多用于有形的东西，“基础问题”是抽象的问题，不能搬动。"}, {"text": "开课第一天，大家先上基础问题。", "explanation": "这里应该用〈基础课〉。“上”的对象是课，“基础问题”是问题，不能说上基础问题。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ee32d3a-f152-4aa3-805c-4fe650e9eb88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92191, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师布置了三本基础问题。", "corrected_sentence": "老师布置了三个基础问题。", "error_description": "量词错误：“基础问题”是问题，应配量词“个”，“本”多用于书籍等，不能用来数问题，应说“三个基础问题”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ee32d3a-f152-4aa3-805c-4fe650e9eb88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92191, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们一起复习那些的基础问题。", "corrected_sentence": "我们一起复习那些基础问题。", "error_description": "多余的“的”：“那些”直接修饰名词，中间不加“的”，应说“那些基础问题”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ee32d3a-f152-4aa3-805c-4fe650e9eb88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
