INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92208, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "因疏忽或水平不够而出的差错。", "primary_collocate": null, "pronunciation": "shī wù", "ipa": "ʂʅ˥ u˥˩", "syllable_count": 2, "sentences": [{"text": "这次失误是我们的责任。", "target_word": "失误", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的失误让球队输了比赛。", "target_word": "失误", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作中的小失误也要认真改。", "target_word": "失误", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个失误是因为水平不够。", "target_word": "失误", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理要求大家减少失误。", "target_word": "失误", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "由于一次失误，我们丢了客户。", "target_word": "失误", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他承认了自己的失误。", "target_word": "失误", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "数据录错是一个很大的失误。", "target_word": "失误", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "翻译里有几处失误。", "target_word": "失误", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球员的失误太多，教练很生气。", "target_word": "失误", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "次", "label": "量词"}], "register": "中性", "sense_fingerprint": "失误：因疏忽或水平不够造成的差错（名词）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '010817e2-98c0-49e8-8874-0f3dd93b1418') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92208, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "失误", "is_correct": true, "explanation": "「失误」指因疏忽或水平不够而出的差错，是正确答案。"}, {"text": "事物", "is_correct": false, "explanation": "shì（第四声）与 shī（第一声）声调不同，「事物」指事情和东西。"}, {"text": "失去", "is_correct": false, "explanation": "wù 与 qù 声母不同，「失去」指丢掉、失掉。"}, {"text": "失序", "is_correct": false, "explanation": "wù 与 xù 声母不同，「失序」指秩序被打乱。"}, {"text": "实务", "is_correct": false, "explanation": "shí（第二声）与 shī（第一声）声调不同，「实务」指实际的工作事务。"}], "explanations": {"失误": "「失误」指因疏忽或水平不够而出的差错，是正确答案。", "事物": "shì（第四声）与 shī（第一声）声调不同，「事物」指事情和东西。", "失去": "wù 与 qù 声母不同，「失去」指丢掉、失掉。", "失序": "wù 与 xù 声母不同，「失序」指秩序被打乱。", "实务": "shí（第二声）与 shī（第一声）声调不同，「实务」指实际的工作事务。"}, "sentence_index": null, "correct_answer": "失误"}, "level_3": {"options": [{"text": "失误", "is_correct": true, "explanation": "正确。「失误」是因疏忽或水平不够而出的差错，可以作为责任的内容。"}, {"text": "奖励", "is_correct": false, "explanation": "语义：「奖励」是表扬或报酬，不是需要担责的事情。"}, {"text": "天气", "is_correct": false, "explanation": "语义：「天气」不是人可以承担责任的对象。"}, {"text": "体貌", "is_correct": false, "explanation": "体貌：「体貌」指外形，与责任无关。"}], "explanations": {"失误": "正确。「失误」是因疏忽或水平不够而出的差错，可以作为责任的内容。", "奖励": "语义：「奖励」是表扬或报酬，不是需要担责的事情。", "天气": "语义：「天气」不是人可以承担责任的对象。", "体貌": "体貌：「体貌」指外形，与责任无关。"}, "sentence_index": 0, "correct_answer": "失误"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我犯了一只失误。", "explanation": "这里应该用〈个〉或〈次〉。「只」用于动物等，不用于失误。"}, {"text": "这次的失误很好，老板很满意。", "explanation": "这里应该用〈成绩〉。失误是负面的，不能用「很好」来评价。"}, {"text": "我在超市买了一个失误。", "explanation": "搭配：「买」的对象是商品，失误是做事时的差错，不能买。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bc8d629-ae1c-4edc-ba37-b7f4bba02d3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92208, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "失误", "is_correct": true, "explanation": "「失误」指因疏忽或水平不够而出的差错，是正确答案。"}, {"text": "事务", "is_correct": false, "explanation": "shì（第四声）与 shī（第一声）声调不同，「事务」指工作中的事情。"}, {"text": "失步", "is_correct": false, "explanation": "wù 与 bù 声母不同，「失步」指跟不上节拍。"}, {"text": "失速", "is_correct": false, "explanation": "wù 与 sù 声母不同，「失速」指速度下降或失控。"}, {"text": "诗句", "is_correct": false, "explanation": "wù 与 jù 声母不同，「诗句」指诗的句子。"}, {"text": "私物", "is_correct": false, "explanation": "shī 与 sī 声母不同（sh 与 s），「私物」指个人的东西。"}], "explanations": {"失误": "「失误」指因疏忽或水平不够而出的差错，是正确答案。", "事务": "shì（第四声）与 shī（第一声）声调不同，「事务」指工作中的事情。", "失步": "wù 与 bù 声母不同，「失步」指跟不上节拍。", "失速": "wù 与 sù 声母不同，「失速」指速度下降或失控。", "诗句": "wù 与 jù 声母不同，「诗句」指诗的句子。", "私物": "shī 与 sī 声母不同（sh 与 s），「私物」指个人的东西。"}, "sentence_index": null, "correct_answer": "失误"}, "level_3": {"options": [{"text": "失误", "is_correct": true, "explanation": "正确。「失误」是可以承认的差错，与句意相符。"}, {"text": "眼睛", "is_correct": false, "explanation": "体貌：「眼睛」是身体器官，不是可以承认的事情。"}, {"text": "座位", "is_correct": false, "explanation": "语义：「座位」不是需要承认的错误，与「承认」意思不合。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：「承认」后接的是事实或错误，「颜色」不能被承认。"}], "explanations": {"失误": "正确。「失误」是可以承认的差错，与句意相符。", "眼睛": "体貌：「眼睛」是身体器官，不是可以承认的事情。", "座位": "语义：「座位」不是需要承认的错误，与「承认」意思不合。", "颜色": "搭配：「承认」后接的是事实或错误，「颜色」不能被承认。"}, "sentence_index": 6, "correct_answer": "失误"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在比赛中取得了很多失误，教练很满意。", "explanation": "这里应该用〈成绩〉。「取得」搭配成绩、胜利，失误不能被取得。"}, {"text": "这次比赛的失误很香。", "explanation": "搭配：失误没有气味，不能用「香」来形容。"}, {"text": "我在食堂吃了一个失误。", "explanation": "搭配：「吃」的对象是食物，失误不能吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5bc8d629-ae1c-4edc-ba37-b7f4bba02d3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET con