INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92215, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "仔细问，仔细看。", "primary_collocate": null, "pronunciation": "shěn", "ipa": "ʂən˨˩˦", "syllable_count": 1, "sentences": [{"text": "老师把我的作文仔细审了一遍。", "target_word": "审", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你把这份合同再审一审，别有错。", "target_word": "审", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "编辑一页一页地审稿子，看得很慢。", "target_word": "审", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把每个数字都审了两遍才放心。", "target_word": "审", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把我审了半天，问我去了哪儿。", "target_word": "审", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生仔细地审那张检查单。", "target_word": "审", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份报告很重要，我想先自己审一下。", "target_word": "审", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐姐一边审图纸，一边提出修改意见。", "target_word": "审", "complexity_tier": "T3", "furigana": "jiě jie yì biān shěn tú zhǐ yì biān tí chū xiū gǎi yì jiàn", "sentence_source": "generated"}, {"text": "老板拿着合同审了很久，没有马上签字。", "target_word": "审", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拿着放大镜，把这幅画的每个细节都审了一遍。", "target_word": "审", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "審", "label": "繁体"}, {"form": "审了", "label": "体标"}, {"form": "审一审", "label": "重叠"}, {"form": "审视", "label": "复合"}], "register": "中性", "sense_fingerprint": "仔细地看或仔细地问，常说审一遍、审稿子、审合同", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77de9a14-9b0d-47dd-90ec-b14e6f01c7cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92215, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "审", "is_correct": true, "explanation": "正确：“审”读 shěn（第三声），意思是仔细问或仔细看。"}, {"text": "深", "is_correct": false, "explanation": "shēn（第一声）与 shěn（第三声）声调不同，意思是深。"}, {"text": "神", "is_correct": false, "explanation": "shén（第二声）与 shěn（第三声）声调不同，意思是神灵。"}, {"text": "省", "is_correct": false, "explanation": "shěng 与 shěn 韵母不同（-ng 与 -n），意思是省份。"}, {"text": "诊", "is_correct": false, "explanation": "zhěn 与 shěn 声母不同（zh 与 sh），意思是诊断。"}], "explanations": {"审": "正确：“审”读 shěn（第三声），意思是仔细问或仔细看。", "深": "shēn（第一声）与 shěn（第三声）声调不同，意思是深。", "神": "shén（第二声）与 shěn（第三声）声调不同，意思是神灵。", "省": "shěng 与 shěn 韵母不同（-ng 与 -n），意思是省份。", "诊": "zhěn 与 shěn 声母不同（zh 与 sh），意思是诊断。"}, "sentence_index": null, "correct_answer": "审"}, "level_3": {"options": [{"text": "审", "is_correct": true, "explanation": "正确：“审”表示仔细看或问，与“仔细”“一遍”搭配，指检查作文。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指把食物咽下去，作文不能吃。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”只说衣服、鞋袜，不能说穿作文。"}, {"text": "擦", "is_correct": false, "explanation": "语义：“擦”指用布抹掉污物，作文不能擦。"}], "explanations": {"审": "正确：“审”表示仔细看或问，与“仔细”“一遍”搭配，指检查作文。", "吃": "语义：“吃”指把食物咽下去，作文不能吃。", "穿": "搭配：“穿”只说衣服、鞋袜，不能说穿作文。", "擦": "语义：“擦”指用布抹掉污物，作文不能擦。"}, "sentence_index": 0, "correct_answer": "审"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "护士审了病人的血压。", "explanation": "这里应该用〈检查〉。“审”用于仔细看或问文字、材料，量血压要用“检查”。"}, {"text": "老师审了我的身高，记在本子上。", "explanation": "这里应该用〈量〉。“审”指仔细看或问，量身高要用“量”。"}, {"text": "医生给孩子审病。", "explanation": "这里应该用〈看〉。“看病”要用“看”，“审”不能用于治病。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '877073eb-87a4-4b4c-8c72-a1ed6a80e827') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92215, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "审", "is_correct": true, "explanation": "正确：“审”读 shěn（第三声），意思是仔细问或仔细看。"}, {"text": "肾", "is_correct": false, "explanation": "shèn（第四声）与 shěn（第三声）声调不同，意思是肾脏。"}, {"text": "身", "is_correct": false, "explanation": "shēn（第一声）与 shěn（第三声）声调不同，意思是身体。"}, {"text": "枕", "is_correct": false, "explanation": "zhěn 与 shěn 声母不同（zh 与 sh），意思是枕头。"}], "explanations": {"审": "正确：“审”读 shěn（第三声），意思是仔细问或仔细看。", "肾": "shèn（第四声）与 shěn（第三声）声调不同，意思是肾脏。", "身": "shēn（第一声）与 shěn（第三声）声调不同，意思是身体。", "枕": "zhěn 与 shěn 声母不同（zh 与 sh），意思是枕头。"}, "sentence_index": null, "correct_answer": "审"}, "level_3": {"options": [{"text": "审", "is_correct": true, "explanation": "正确：“审”表示仔细看或问，与“报告很重要”“先自己”的语境相合。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”搭配衣物、手、碗等，报告不能洗。"}, {"text": "砸", "is_correct": false, "explanation": "语义：“砸”指用力击打，与“报告很重要”的语境矛盾。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”的对象是歌曲，不能用于报告。"}], "explanations": {"审": "正确：“审”表示仔细看或问，与“报告很重要”“先自己”的语境相合。", "洗": "搭配：“洗”搭配衣物、手、碗等，报告不能洗。", "砸": "语义：“砸”指用力击打，与“报告很重要”的语境矛盾。", "唱": "语义：“唱”的对象是歌曲，不能用于报告。"}, "sentence_index": 6, "correct_answer": "审"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "厨师审了一口汤的味道，觉得太咸。", "explanation": "这里应该用〈尝〉。“尝”指用嘴辨别味道，“审”没有品尝的意思。"}, {"text": "工人审了房间的面积，记在本子上。", "explanation": "这里应该用〈测量〉。“审”指仔细看或问，量面积要用“测量”。"}, {"text": "裁缝把衣服的袖子审了一针。", "explanation": "这里应该用〈缝〉。“审”指仔细看或问，不能表示缝制一针。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '877073eb-87a4-4b4c-8c72-a1ed6a80e827') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92215, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈审了了我的作业，才让我去玩。", "corrected_sentence": "妈妈审了我的作业，才让我去玩。", "error_description": "“了”重复：同一个动词“审”后只用一个“了”，应为“审了我的作业”，写成“审了了”不符合汉语习惯。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '877073eb-87a4-4b4c-8c72-a1ed6a80e827') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92215, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他审了过这份稿子。", "corrected_sentence": "他审过这份稿子。", "error_description": "体标错误：“了”和“过”不能叠用表示同一个体，应为“审过这份稿子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '877073eb-87a4-4b4c-8c72-a1ed6a80e827') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
