INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92216, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "审查；审问。", "primary_collocate": null, "pronunciation": "shěn", "ipa": "ʂən˨˩˦", "syllable_count": 1, "sentences": [{"text": "这个计划要先由领导审，再决定做不做。", "target_word": "审", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察正在审那个偷东西的人。", "target_word": "审", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察审了他三个小时，他什么也不说。", "target_word": "审", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "文章写好后，要先送去审，才能发表。", "target_word": "审", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份材料已经审过了，没有问题。", "target_word": "审", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们的书都要先审，才能进学校。", "target_word": "审", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察抓到小偷后，连夜审了他。", "target_word": "审", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影上映以前，要先送到有关部门审。", "target_word": "审", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事很大，上面派人来审，要查清楚。", "target_word": "审", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们公司的广告，都要经理先审一下。", "target_word": "审", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "審", "label": "繁体"}, {"form": "审了", "label": "体标"}, {"form": "审过", "label": "体标"}, {"form": "审查", "label": "复合"}, {"form": "审问", "label": "复合"}], "register": "正式", "sense_fingerprint": "按规定检查材料是否合格，或警察询问嫌疑人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77de9a14-9b0d-47dd-90ec-b14e6f01c7cf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92216, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "审", "is_correct": true, "explanation": "正确：“审”读 shěn（第三声），意思是审查材料或询问。"}, {"text": "神", "is_correct": false, "explanation": "shén（第二声）与 shěn（第三声）声调不同，意思是神灵。"}, {"text": "省", "is_correct": false, "explanation": "shěng 与 shěn 韵母不同（-ng 与 -n），意思是省份。"}, {"text": "诊", "is_correct": false, "explanation": "zhěn 与 shěn 声母不同（zh 与 sh），意思是诊断。"}], "explanations": {"审": "正确：“审”读 shěn（第三声），意思是审查材料或询问。", "神": "shén（第二声）与 shěn（第三声）声调不同，意思是神灵。", "省": "shěng 与 shěn 韵母不同（-ng 与 -n），意思是省份。", "诊": "zhěn 与 shěn 声母不同（zh 与 sh），意思是诊断。"}, "sentence_index": null, "correct_answer": "审"}, "level_3": {"options": [{"text": "审", "is_correct": true, "explanation": "正确：“审”指审查、审核，与“计划”“再决定做不做”的语境相合。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指把食物咽下去，计划不能吃。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”只说衣服、鞋袜，不能说穿计划。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”搭配歌曲、戏曲，不能用于计划。"}], "explanations": {"审": "正确：“审”指审查、审核，与“计划”“再决定做不做”的语境相合。", "吃": "语义：“吃”指把食物咽下去，计划不能吃。", "穿": "搭配：“穿”只说衣服、鞋袜，不能说穿计划。", "唱": "搭配：“唱”搭配歌曲、戏曲，不能用于计划。"}, "sentence_index": 0, "correct_answer": "审"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医生审了他的心脏，说没什么问题。", "explanation": "这里应该用〈检查〉。“审”用于审查材料或询问，检查身体要用“检查”。"}, {"text": "我把玩具审进箱子里了。", "explanation": "这里应该用〈放〉。“审”指仔细看或问，不能表示把东西放进某处。"}, {"text": "兽医审了小狗。", "explanation": "这里应该用〈看〉。给小狗看病要用“看”，“审问”的对象只能是人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '877073eb-87a4-4b4c-8c72-a1ed6a80e827') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92216, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "审", "is_correct": true, "explanation": "正确：“审”读 shěn（第三声），意思是审查材料或询问。"}, {"text": "肾", "is_correct": false, "explanation": "shèn（第四声）与 shěn（第三声）声调不同，意思是肾脏。"}, {"text": "深", "is_correct": false, "explanation": "shēn（第一声）与 shěn（第三声）声调不同，意思是深。"}, {"text": "枕", "is_correct": false, "explanation": "zhěn 与 shěn 声母不同（zh 与 sh），意思是枕头。"}], "explanations": {"审": "正确：“审”读 shěn（第三声），意思是审查材料或询问。", "肾": "shèn（第四声）与 shěn（第三声）声调不同，意思是肾脏。", "深": "shēn（第一声）与 shěn（第三声）声调不同，意思是深。", "枕": "zhěn 与 shěn 声母不同（zh 与 sh），意思是枕头。"}, "sentence_index": null, "correct_answer": "审"}, "level_3": {"options": [{"text": "审", "is_correct": true, "explanation": "正确：“审”指审问、审查，与“警察抓到小偷”的语境相合。"}, {"text": "戴", "is_correct": false, "explanation": "搭配：“戴”搭配帽子、眼镜等，不能用于人。"}, {"text": "咬", "is_correct": false, "explanation": "语义：“咬”指用牙齿夹住，与“警察抓到小偷后”的语境不符。"}, {"text": "摘", "is_correct": false, "explanation": "搭配：“摘”搭配花、果子等，不能用于人。"}], "explanations": {"审": "正确：“审”指审问、审查，与“警察抓到小偷”的语境相合。", "戴": "搭配：“戴”搭配帽子、眼镜等，不能用于人。", "咬": "语义：“咬”指用牙齿夹住，与“警察抓到小偷后”的语境不符。", "摘": "搭配：“摘”搭配花、果子等，不能用于人。"}, "sentence_index": 6, "correct_answer": "审"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "司机把汽油审进了油箱。", "explanation": "这里应该用〈加〉。“审”指仔细看或问，不能表示把汽油注入油箱。"}, {"text": "妈妈用扫帚审地，然后擦桌子。", "explanation": "这里应该用〈扫〉。“审”指仔细看或问，不能表示用扫帚清理地面。"}, {"text": "小王把脏衣服审干净了。", "explanation": "这里应该用〈洗〉。“审”没有清洗的意思，把脏衣服洗干净要用“洗”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '877073eb-87a4-4b4c-8c72-a1ed6a80e827') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92216, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "会计师了审那家公司的账三次。", "corrected_sentence": "会计师审了那家公司的账三次。", "error_description": "“了”位置错误：“了”应紧跟动词“审”，应为“审了那家公司的账三次”，不能放在动词前面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '877073eb-87a4-4b4c-8c72-a1ed6a80e827') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92216, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份合同，经理要先把它审。", "corrected_sentence": "这份合同，经理要先把它审一下。", "error_description": "补语缺失：“把”字句中动词后要带补语，如“一下”，应为“把它审一下”，不能只说“把它审”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '877073eb-87a4-4b4c-8c72-a1ed6a80e827') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92219, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "民主", "is_correct": true, "explanation": "反义：「民主」与「专制」相对，指大家共同商量、共同决定。"}, {"text": "热情", "is_correct": false, "explanation": "无关：「热情」是待人的态度，与专制的作风没有反义关系。"}, {"text": "粗心", "is_correct": false, "explanation": "无关：「粗心」指做事不仔细，与专制没有反义关系。"}, {"text": "勤快", "is_correct": false, "explanation": "无关：「勤快」指爱干活，与专制没有反义关系。"}], "correct_answer": "民主", "explanations": {"民主": "反义：「民主」与「专制」相对，指大家共同商量、共同决定。", "热情": "无关：「热情」是待人的态度，与专制的作风没有反义关系。", "粗心": "无关：「粗心」指做事不仔细，与专制没有反义关系。", "勤快": "无关：「勤快」指爱干活，与专制没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93d0ef5e-5510-4bb2-b99f-97b0cbc9163c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92219, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "民主", "is_correct": true, "explanation": "反义：「民主」与「专制」相对，指大家共同商量、共同决定。"}, {"text": "小心", "is_correct": false, "explanation": "无关：「小心」指做事留神，与专制没有反义关系。"}, {"text": "活泼", "is_correct": false, "explanation": "无关：「活泼」指性格开朗、爱活动，与专制没有反义关系。"}, {"text": "大方", "is_correct": false, "explanation": "无关：「大方」指不计较、待人慷慨，与专制没有反义关系。"}], "correct_answer": "民主", "explanations": {"民主": "反义：「民主」与「专制」相对，指大家共同商量、共同决定。", "小心": "无关：「小心」指做事留神，与专制没有反义关系。", "活泼": "无关：「活泼」指性格开朗、爱活动，与专制没有反义关系。", "大方": "无关：「大方」指不计较、待人慷慨，与专制没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93d0ef5e-5510-4bb2-b99f-97b0cbc9163c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92219, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "一个人说了算，不管别人怎么想。", "primary_collocate": null, "pronunciation": "zhuān zhì", "ipa": "ʈʂuan˥ ʈʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "他的父亲很专制，家里的事都他说了算。", "target_word": "专制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王经理太专制，从来不听同事的意见。", "target_word": "专制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不喜欢专制的老板，他从不让我们说话。", "target_word": "专制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈对孩子很专制，连穿什么衣服都要管。", "target_word": "专制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老师很专制，学生不能问问题。", "target_word": "专制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他做事专制，大家都不愿意和他商量。", "target_word": "专制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你别这么专制，也听听孩子怎么想。", "target_word": "专制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷年轻时很专制，奶奶什么都得听他的。", "target_word": "专制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "队长太专制了，没人敢说自己的看法。", "target_word": "专制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专制的家长总是不听孩子的想法。", "target_word": "专制", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "专制主义", "label": "复合"}], "register": "通用", "sense_fingerprint": "形容人或家长、上司的作风：独断专行，凡事自己说了算，不听别人的意见", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '074eb1d9-d5d2-4422-9990-2487466d07f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92219, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "专制", "is_correct": true, "explanation": "正确答案，指一个人说了算，不听别人的意见。"}, {"text": "专职", "is_correct": false, "explanation": "专职与专制的声调不同（第二声与第四声），意思是专门负责某项工作。"}, {"text": "装置", "is_correct": false, "explanation": "装置与专制的韵母不同（ang 与 an），意思是设备。"}, {"text": "壮志", "is_correct": false, "explanation": "壮志与专制的韵母不同（ang 与 an），意思是远大的志向。"}, {"text": "专指", "is_correct": false, "explanation": "专指与专制的末字声调不同（第三声与第四声），意思是特别指明。"}, {"text": "转制", "is_correct": false, "explanation": "转制与专制的首字声调不同（第三声与第一声），意思是改变原有制度。"}], "explanations": {"专制": "正确答案，指一个人说了算，不听别人的意见。", "专职": "专职与专制的声调不同（第二声与第四声），意思是专门负责某项工作。", "装置": "装置与专制的韵母不同（ang 与 an），意思是设备。", "壮志": "壮志与专制的韵母不同（ang 与 an），意思是远大的志向。", "专指": "专指与专制的末字声调不同（第三声与第四声），意思是特别指明。", "转制": "转制与专制的首字声调不同（第三声与第一声），意思是改变原有制度。"}, "sentence_index": null, "correct_answer": "专制"}, "level_3": {"options": [{"text": "专制", "is_correct": true, "explanation": "正确：「很专制」指父亲独断，与后半句「家里的事都他说了算」一致。"}, {"text": "民主", "is_correct": false, "explanation": "语义：「民主」指大家共同商量，与「家里的事都他说了算」矛盾。"}, {"text": "懦弱", "is_correct": false, "explanation": "语义：「懦弱」指没有主见、胆小，与「事都他说了算」的强势形象相反。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：「高大」说身材，不说作风，与句中的管理方式无关。"}], "explanations": {"专制": "正确：「很专制」指父亲独断，与后半句「家里的事都他说了算」一致。", "民主": "语义：「民主」指大家共同商量，与「家里的事都他说了算」矛盾。", "懦弱": "语义：「懦弱」指没有主见、胆小，与「事都他说了算」的强势形象相反。", "高大": "体貌：「高大」说身材，不说作风，与句中的管理方式无关。"}, "sentence_index": 0, "correct_answer": "专制"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的朋友很专制，每次聊天都先问问我的想法。", "explanation": "这里应该用〈体贴〉。专制指一个人说了算、不顾别人想法，句子说他先问我的想法，正好相反。"}, {"text": "他做事很专制，常常听取大家的建议。", "explanation": "这里应该用〈谦虚〉。专制指独断专行、不顾别人的意见，句子说他常听取建议，应该用谦虚。"}, {"text": "奶奶很专制，每次做决定都要先问全家人。", "explanation": "这里应该用〈民主〉。专制指一个人说了算，句子说做决定前要问全家人，应该用民主。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93d0ef5e-5510-4bb2-b99f-97b0cbc9163c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92219, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "专制", "is_correct": true, "explanation": "正确：「这么专制」指做事独断，与后半句「也听听孩子怎么想」形成对比。"}, {"text": "平等", "is_correct": false, "explanation": "语义：「平等」与「别这么……」的劝阻语气及后文不协调，句意前后矛盾。"}, {"text": "矮小", "is_correct": false, "explanation": "体貌：「矮小」说身材，与说话做事的态度无关。"}, {"text": "瘦弱", "is_correct": false, "explanation": "体貌：「瘦弱」说身体，不能用来评价做事的态度。"}], "explanations": {"专制": "正确：「这么专制」指做事独断，与后半句「也听听孩子怎么想」形成对比。", "平等": "语义：「平等」与「别这么……」的劝阻语气及后文不协调，句意前后矛盾。", "矮小": "体貌：「矮小」说身材，与说话做事的态度无关。", "瘦弱": "体貌：「瘦弱」说身体，不能用来评价做事的态度。"}, "sentence_index": 6, "correct_answer": "专制"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "姐姐很专制，凡事都愿意听别人的想法。", "explanation": "这里应该用〈随和〉。专制指一个人说了算、不管别人怎么想，句子说她愿意听别人的想法，与之相反。"}, {"text": "这个孩子很专制，每次做游戏都让别人先选。", "explanation": "这里应该用〈谦让〉。专制指独断专行，句子说他让别人先选，应该用谦让。"}, {"text": "她买东西很专制，总是先问朋友想买哪个。", "explanation": "这里应该用〈商量〉。专制指不顾别人，句子说她先问朋友的意见，应该用商量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93d0ef5e-5510-4bb2-b99f-97b0cbc9163c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92219, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他脾气很更专制，什么事都要自己做主。", "corrected_sentence": "他脾气很专制，什么事都要自己做主。", "error_description": "「很」和「更」都表示程度，不能叠用。应去掉「更」，说「他脾气很专制」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93d0ef5e-5510-4bb2-b99f-97b0cbc9163c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92219, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他对孩子专制很得，什么都要管。", "corrected_sentence": "他对孩子专制得很，什么都要管。", "error_description": "「专制得很」是「形容词＋得＋很」的补语结构，「专制很得」语序错误，应说「专制得很」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93d0ef5e-5510-4bb2-b99f-97b0cbc9163c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92220, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "民主", "is_correct": true, "explanation": "反义：「民主」与「专制」相对，指权力属于人民、大家共同决定。"}, {"text": "繁荣", "is_correct": false, "explanation": "无关：「繁荣」指经济兴旺，与专制的统治方式没有反义关系。"}, {"text": "富强", "is_correct": false, "explanation": "无关：「富强」指国家富足强盛，与专制没有反义关系。"}, {"text": "和平", "is_correct": false, "explanation": "无关：「和平」指没有战争，与专制没有反义关系。"}], "correct_answer": "民主", "explanations": {"民主": "反义：「民主」与「专制」相对，指权力属于人民、大家共同决定。", "繁荣": "无关：「繁荣」指经济兴旺，与专制的统治方式没有反义关系。", "富强": "无关：「富强」指国家富足强盛，与专制没有反义关系。", "和平": "无关：「和平」指没有战争，与专制没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93d0ef5e-5510-4bb2-b99f-97b0cbc9163c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92220, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "民主", "is_correct": true, "explanation": "反义：「民主」与「专制」相对，指权力属于人民、大家共同决定。"}, {"text": "安定", "is_correct": false, "explanation": "无关：「安定」指社会平稳，与专制没有反义关系。"}, {"text": "落后", "is_correct": false, "explanation": "无关：「落后」指发展慢，与专制没有反义关系。"}, {"text": "贫穷", "is_correct": false, "explanation": "无关：「贫穷」指缺少钱财，与专制没有反义关系。"}], "correct_answer": "民主", "explanations": {"民主": "反义：「民主」与「专制」相对，指权力属于人民、大家共同决定。", "安定": "无关：「安定」指社会平稳，与专制没有反义关系。", "落后": "无关：「落后」指发展慢，与专制没有反义关系。", "贫穷": "无关：「贫穷」指缺少钱财，与专制没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93d0ef5e-5510-4bb2-b99f-97b0cbc9163c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92220, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "独自掌握权力，独断专行。", "primary_collocate": null, "pronunciation": "zhuān zhì", "ipa": "ʈʂuan˥ ʈʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "这个国家以前很专制，国王一个人掌握所有权力。", "target_word": "专制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专制的国王不让人民选举官员。", "target_word": "专制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古代的政治很专制，权力都在皇帝手里。", "target_word": "专制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个专制的政府不允许报纸批评它。", "target_word": "专制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人们起来反对专制的统治。", "target_word": "专制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专制的国家没有真正的选举。", "target_word": "专制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位将军掌权后越来越专制。", "target_word": "专制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "历史书上说，那个朝代的政治非常专制。", "target_word": "专制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们推翻了专制的王朝，建立了新国家。", "target_word": "专制", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在专制的社会里，老百姓不能自由说话。", "target_word": "专制", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "专制主义", "label": "复合"}], "register": "书面", "sense_fingerprint": "形容国家、政府、统治者独自掌握权力，不受限制，不让人民参与", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '074eb1d9-d5d2-4422-9990-2487466d07f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92220, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "专制", "is_correct": true, "explanation": "正确答案，指独自掌握权力，不受限制。"}, {"text": "专职", "is_correct": false, "explanation": "专职与专制的声调不同（第二声与第四声），意思是专门负责某项工作。"}, {"text": "装置", "is_correct": false, "explanation": "装置与专制的韵母不同（ang 与 an），意思是设备。"}, {"text": "壮志", "is_correct": false, "explanation": "壮志与专制的韵母不同（ang 与 an），意思是远大的志向。"}, {"text": "专指", "is_correct": false, "explanation": "专指与专制的末字声调不同（第三声与第四声），意思是特别指明。"}, {"text": "转制", "is_correct": false, "explanation": "转制与专制的首字声调不同（第三声与第一声），意思是改变原有制度。"}], "explanations": {"专制": "正确答案，指独自掌握权力，不受限制。", "专职": "专职与专制的声调不同（第二声与第四声），意思是专门负责某项工作。", "装置": "装置与专制的韵母不同（ang 与 an），意思是设备。", "壮志": "壮志与专制的韵母不同（ang 与 an），意思是远大的志向。", "专指": "专指与专制的末字声调不同（第三声与第四声），意思是特别指明。", "转制": "转制与专制的首字声调不同（第三声与第一声），意思是改变原有制度。"}, "sentence_index": null, "correct_answer": "专制"}, "level_3": {"options": [{"text": "专制", "is_correct": true, "explanation": "正确：「很专制」说明统治方式，与「国王一个人掌握所有权力」一致。"}, {"text": "民主", "is_correct": false, "explanation": "语义：「民主」指权力属于人民，与「国王一个人掌握所有权力」矛盾。"}, {"text": "自由", "is_correct": false, "explanation": "语义：「自由」指不受约束，与「国王一个人掌握所有权力」矛盾。"}, {"text": "瘦", "is_correct": false, "explanation": "体貌：「瘦」说身材，不能用来形容国家的统治方式。"}], "explanations": {"专制": "正确：「很专制」说明统治方式，与「国王一个人掌握所有权力」一致。", "民主": "语义：「民主」指权力属于人民，与「国王一个人掌握所有权力」矛盾。", "自由": "语义：「自由」指不受约束，与「国王一个人掌握所有权力」矛盾。", "瘦": "体貌：「瘦」说身材，不能用来形容国家的统治方式。"}, "sentence_index": 0, "correct_answer": "专制"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个国家对外很专制，欢迎各国游客。", "explanation": "这里应该用〈开放〉。专制指统治者独揽权力，形容对外交流要用开放。"}, {"text": "这个国家的人民很专制，可以随便说话。", "explanation": "这里应该用〈自由〉。专制指统治者独揽权力，不能用来形容人民。"}, {"text": "这届政府很专制，经常举行全民投票，听取人民的意见。", "explanation": "这里应该用〈民主〉。专制指统治者独揽权力、不让人民参与，句子说政府经常举行全民投票、听取人民意见，应该用民主。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93d0ef5e-5510-4bb2-b99f-97b0cbc9163c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92220, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "专制", "is_correct": true, "explanation": "正确：「越来越专制」指掌权后独断加剧，与句意一致。"}, {"text": "平等", "is_correct": false, "explanation": "语义：「平等」与「掌权后」的语境矛盾，掌权者不会越来越平等。"}, {"text": "瘦弱", "is_correct": false, "explanation": "体貌：「瘦弱」说身体，与掌权后的作风无关。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：「高大」说身材，不说作风，句子不通。"}], "explanations": {"专制": "正确：「越来越专制」指掌权后独断加剧，与句意一致。", "平等": "语义：「平等」与「掌权后」的语境矛盾，掌权者不会越来越平等。", "瘦弱": "体貌：「瘦弱」说身体，与掌权后的作风无关。", "高大": "体貌：「高大」说身材，不说作风，句子不通。"}, "sentence_index": 6, "correct_answer": "专制"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个古国很专制，人民可以自由地选择自己的领导人。", "explanation": "这里应该用〈民主〉。专制指统治者独揽权力、不许人民选择，句子说人民可以自由选领导人，与专制相反。"}, {"text": "这位国王很专制，允许大家提不同意见。", "explanation": "这里应该用〈宽容〉。专制指独断专行，形容能接纳不同意见要用宽容。"}, {"text": "这次考试很专制，每个人都有机会。", "explanation": "这里应该用〈公平〉。专制指独揽权力，形容对每个人一视同仁要用公平。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93d0ef5e-5510-4bb2-b99f-97b0cbc9163c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92220, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那个王朝后期越来越很专制，人民的意见没人听。", "corrected_sentence": "那个王朝后期越来越专制，人民的意见没人听。", "error_description": "「越来越」和「很」都表示程度，不能叠用。应去掉「很」，说「越来越专制」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93d0ef5e-5510-4bb2-b99f-97b0cbc9163c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92220, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他当上皇帝以后，统治的很专制。", "corrected_sentence": "他当上皇帝以后，统治得很专制。", "error_description": "「统治」后面引出程度补语，要用助词「得」，不用「的」。错误形式是「统治的很专制」，正确应为「统治得很专制」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93d0ef5e-5510-4bb2-b99f-97b0cbc9163c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
