INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92227, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "至好是和你最好、最亲近的朋友。", "primary_collocate": null, "pronunciation": "zhì hǎo", "ipa": "tʂɻ̩˥˩ xɑʊ̯˨˩˦", "syllable_count": 2, "sentences": [{"text": "他是我多年的至好，我们无话不谈。", "target_word": "至好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "李明和我是至好，从小一起长大。", "target_word": "至好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把我当作至好，什么事都告诉我。", "target_word": "至好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的几位至好都来参加我的婚礼了。", "target_word": "至好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "毕业以后，我们仍然是至好。", "target_word": "至好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他失去了一位至好，心里非常难过。", "target_word": "至好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老王是父亲的至好，常来我们家做客。", "target_word": "至好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你有没有一个无话不谈的至好？", "target_word": "至好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这个城市，他没有一个至好。", "target_word": "至好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我和她成了至好，每天一起上班。", "target_word": "至好", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "最要好、最亲近的朋友", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f447c5a2-140b-433d-8f46-2a9e5f4c3fee') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92227, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "至好", "is_correct": true, "explanation": "正确：“至好”指最亲近的朋友，与“多年”和“无话不谈”的交情相符。"}, {"text": "陌生人", "is_correct": false, "explanation": "语义：“陌生人”与“无话不谈”矛盾，不可能是多年的交情。"}, {"text": "敌人", "is_correct": false, "explanation": "语义：“敌人”与“无话不谈”的亲近关系相矛盾。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“桌子”不是人，不能用“是……的”来指一段交情。"}], "explanations": {"至好": "正确：“至好”指最亲近的朋友，与“多年”和“无话不谈”的交情相符。", "陌生人": "语义：“陌生人”与“无话不谈”矛盾，不可能是多年的交情。", "敌人": "语义：“敌人”与“无话不谈”的亲近关系相矛盾。", "桌子": "搭配：“桌子”不是人，不能用“是……的”来指一段交情。"}, "sentence_index": 0, "correct_answer": "至好"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在超市遇到一位至好，聊了几句。", "explanation": "这里应该用〈熟人〉。“至好”指交情极深的最亲近的朋友，不能用来指只是认识的人。"}, {"text": "我和他只是至好，见面打个招呼而已。", "explanation": "这里应该用〈点头之交〉。“至好”指交情极深的最亲近的朋友，不能用于只是见面打个招呼、交情很浅的人。"}, {"text": "我在路口问路，一个至好热心地给我指了方向。", "explanation": "这里应该用〈路人〉。“至好”指交情极深的最亲近的朋友，不能用于素不相识、只是偶然相遇的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2c609f2-0a25-4e16-ba53-61943ecc738c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92227, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "至好", "is_correct": true, "explanation": "正确：“至好”指交情极深的朋友，与“父亲的”和“常来做客”相符。"}, {"text": "仇人", "is_correct": false, "explanation": "语义：“仇人”与“常来我们家做客”的关系相矛盾。"}, {"text": "路人", "is_correct": false, "explanation": "语义：“路人”指不相识的过路人，与“常来我们家做客”矛盾。"}, {"text": "房子", "is_correct": false, "explanation": "搭配：“房子”不是人，不能用来指“父亲的”这样的交情关系。"}], "explanations": {"至好": "正确：“至好”指交情极深的朋友，与“父亲的”和“常来做客”相符。", "仇人": "语义：“仇人”与“常来我们家做客”的关系相矛盾。", "路人": "语义：“路人”指不相识的过路人，与“常来我们家做客”矛盾。", "房子": "搭配：“房子”不是人，不能用来指“父亲的”这样的交情关系。"}, "sentence_index": 6, "correct_answer": "至好"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是我的至好，十年来一直在背后骂我。", "explanation": "这里应该用〈敌人〉。“至好”指交情极深的朋友，不能用于在背后辱骂、与自己为敌的人。"}, {"text": "他是我的至好，我从来没有见过他。", "explanation": "这里应该用〈陌生人〉。“至好”指交情极深的朋友，与“从来没有见过”直接矛盾。"}, {"text": "他是我的至好，二十年前陷害过我。", "explanation": "这里应该用〈仇人〉。“至好”指交情极深的最亲近的朋友，不能用于陷害过自己的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2c609f2-0a25-4e16-ba53-61943ecc738c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92227, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他是我从小至好，我们无话不谈。", "corrected_sentence": "他是我从小的至好，我们无话不谈。", "error_description": "“至好”前的定语“从小”后要加“的”，应说“从小的至好”，漏掉“的”是错误形式。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2c609f2-0a25-4e16-ba53-61943ecc738c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (92227, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我身边有几至好，每天都见面。", "corrected_sentence": "我身边有几个至好，每天都见面。", "error_description": "“几”后漏了量词“个”，应说“几个至好”，不能直接用“几”加名词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2c609f2-0a25-4e16-ba53-61943ecc738c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
